window.__LIZZWORD_DEEP_SHARD && window.__LIZZWORD_DEEP_SHARD("0041", [{"word":"classifier","ipa_uk":"/ˈklæsɪfaɪə/","ipa_us":"/ˈklæsɪfaɪər/","definition_zh":"分类者；分选设备；分类器；（语法）类别词、量词；（手语）类别词；分类标签","definition_en":"a person or thing that sorts things into classes; a word or morpheme that marks the class of a noun; an algorithm that assigns items to categories","core_image":"一排抽屉贴着不同标签，一只手把每件东西放进其中一个抽屉","scene":"语言学老师在黑板上写下「三本书」，圈出「本」。In the linguistics class, the teacher writes three books in Chinese on the board, circles the word ben, and says it is a classifier.","sceneCN":"这里 classifier 是「（语法）类别词、量词」（第 3 个义项：标记名词所指类别的词或语素）；句意：老师在黑板上写下「三本书」，圈出「本」，说明它是类别词。图中可辨识物件：黑板、粉笔、三本书、抽屉柜、标签。","pos":[{"tag":"n.","zh":"分类者；分类器；分选设备"},{"tag":"n.","zh":"（语法/手语）类别词、量词"}],"collocations":[{"phrase":"a spam classifier","zh":"垃圾邮件分类器"},{"phrase":"noun classifier","zh":"名词类别词"},{"phrase":"a classifier system","zh":"分类系统"},{"phrase":"train a classifier","zh":"训练分类器"},{"phrase":"classifier handshape","zh":"类别词手形"},{"phrase":"image classifier","zh":"图像分类器"}],"forms":[{"label":"复数","form":"classifiers"},{"label":"动词","form":"classify"},{"label":"名词","form":"classification"},{"label":"形容词","form":"classificatory"}],"derivatives":[{"word":"classify","pos":"v.","zh":"分类；归类"},{"word":"classification","pos":"n.","zh":"分类；分类体系"},{"word":"classificatory","pos":"adj.","zh":"分类上的"},{"word":"classifiable","pos":"adj.","zh":"可分类的"}],"senses":[{"no":"01","title":"A person who sorts","titleCN":"分类者","definition":"a person whose work is to arrange things into groups","definitionCN":"以把事物分组为工作的人","example":"The classifier sorted the specimens by species.","exampleCN":"分类员按物种把标本分开。","why":"The -er suffix is agentive here: a human doing the sorting. This is the plainest reading of the word, and the base from which the technical senses branch.","whyCN":"此处 -er 是施事后缀：一个在做分拣的人。这是该词最朴素的读法，也是技术义分叉的基座。"},{"no":"02","title":"A sorting machine","titleCN":"分选设备；分选机","definition":"a machine that separates items by size, weight, or quality","definitionCN":"按大小、重量或品质分离物料的机器","example":"The air classifier removes fine dust from the crushed ore.","exampleCN":"气流分选机从碎矿中除去细尘。","why":"Industry extends the agent to metal: the machine does what the worker did. The suffix -er covers instruments as easily as people, a common English pattern.","whyCN":"工业把施事扩展到机器：机器做工人做过的事。后缀 -er 与人一样容易指工具，这是英语常见模式。"},{"no":"03","title":"A grammatical classifier","titleCN":"（语法）类别词；量词","definition":"a word or morpheme that must accompany a noun and marks its class, like the Chinese measure word ben used for books","definitionCN":"必须与名词连用并标记其类别的词或语素，如汉语中书的“本”","example":"Chinese uses the measure word zhang for flat objects.","exampleCN":"汉语用类别词“张”来数扁平物体。","why":"Linguistics borrowed the sorting image: the classifier puts a noun into a class (long, flat, human) before it can be counted. English has no full system, which is why the term is learned as a foreign concept.","whyCN":"语言学借用了分拣意象：类别词先把名词归入某类（长形、扁平、人类），然后才能计数。英语没有完整系统，故该术语是作为外来概念学习的。"},{"no":"04","title":"A sign-language classifier","titleCN":"（手语）类别词","definition":"a handshape in sign language that represents a class of objects or how they move","definitionCN":"手语中代表某类物体或其运动方式的手形","example":"The signer used a vehicle classifier for the moving car.","exampleCN":"手语者用车辆类别词表示移动的车。","why":"Sign linguistics extends the grammatical sense to gesture: the handshape itself carries the class. The classifier is not a word but a form that categorizes what the verb describes.","whyCN":"手语语言学把语法义扩展到手势：手形本身承载类别。类别词不是词，而是给动词所述对象归类的形式。"},{"no":"05","title":"A machine-learning classifier","titleCN":"（机器学习）分类器","definition":"an algorithm that assigns a label to new data after training on examples","definitionCN":"在样本上训练后为新数据分配标签的算法","example":"The classifier predicts whether an email is spam.","exampleCN":"该分类器预测邮件是否为垃圾邮件。","why":"Computing keeps the agent slot but fills it with a model. The classifier has learned a boundary between classes; its output is a label, and its quality is measured by accuracy, not by understanding.","whyCN":"计算保留施事位置，却用模型填充。分类器学到了类与类之间的边界；输出是标签，质量以准确率衡量，而非以理解衡量。"},{"no":"06","title":"A biological taxonomist","titleCN":"生物分类学者","definition":"a scientist who assigns organisms to taxonomic groups","definitionCN":"把生物归入分类群的科学家","example":"Early classifiers placed whales among fish.","exampleCN":"早期的分类学者把鲸归入鱼类。","why":"Biology is where classification became a formal science. The classifier's judgements are hypotheses about relatedness, and they can be wrong, as the whale case shows.","whyCN":"生物学是分类成为正式科学之处。分类者的判断是关于亲缘关系的假设，可能出错，鲸的例子即是。"},{"no":"07","title":"A library classifier","titleCN":"图书分类员","definition":"a librarian who assigns classification numbers to books","definitionCN":"给书籍编分类号的图书馆员","example":"The classifier gave the atlas a shelf mark.","exampleCN":"分类员给这本地图册编了排架号。","why":"Library work makes the word institutional: the classifier applies an existing scheme rather than inventing classes. The agent's skill lies in reading a book accurately enough to place it.","whyCN":"图书馆工作使该词制度化：分类员应用既有体系，而非发明类别。其技能在于把书读得足够准，以便安放。"},{"no":"08","title":"A content filter","titleCN":"内容过滤器；过滤分类器","definition":"a system that sorts messages or media into wanted and unwanted categories","definitionCN":"把信息或媒体分为想要与不想要的系统","example":"The classifier flagged the comment as abusive.","exampleCN":"该过滤器把这条评论标为辱骂。","why":"This is the applied face of sense 05: the boundary is put to work. The word hides the human decisions behind the labels, including the choice of what counts as abuse.","whyCN":"这是第 5 义的应用面：边界被投入使用。该词掩盖了标签背后的人为决定，包括“什么算辱骂”的选择。"},{"no":"09","title":"A class label","titleCN":"类别标签；分类标记","definition":"a tag or feature that marks which class an item belongs to","definitionCN":"标记某物属于哪一类的标签或特征","example":"Each record carries a classifier in its metadata.","exampleCN":"每条记录在元数据中带有一个类别标记。","why":"The rarest sense shifts from the sorter to the mark left by sorting. It is the trace of the act, not the act itself, and it shows how far the -er suffix can drift from 'person who'.","whyCN":"最罕见的义项从分拣者转到分拣留下的标记。它是动作的痕迹而非动作本身，显示 -er 后缀可以离“做此事的人”多远。"}],"etymology":{"intro":{"en":"Classifier is classify plus -er. Classify comes from French classifier, built on classe, from Latin classis 'a division or class of citizens' (also 'a fleet'). The second element is -ifier, from Latin -ificare, from facere 'to make': to make into a class. The origin of classis itself is uncertain; one suggestion links it to calare 'to summon', picturing a called-up body of citizens. The grammatical sense is a 20C linguistic borrowing of the sorting image.","cn":"classifier 是 classify 加 -er。classify 出自法语 classifier，基于 classe，源于拉丁 classis“公民的等级/类别”（也指“舰队”）。第二部分 -ifier 出自拉丁 -ificare，源自 facere“做”：使成为一类。classis 本身的来源存疑，一说与 calare“召集”有关，构拟“被召集的公民体”。语法义是二十世纪语言学对“分拣”意象的借用。"},"items":[{"era":"LATIN","en":"classis means 'a division or class of Roman citizens', and also 'a fleet'; its deeper origin is uncertain.","cn":"classis 意为“罗马公民的一个等级/类别”，也指“舰队”；其更深来源存疑。"},{"era":"LATIN","en":"One suggestion connects classis with calare 'to summon', so a class is 'those called together'. This is plausible, not proven.","cn":"一说把 classis 与 calare“召集”联系起来，于是 class 是“被召集到一起的人”。此说合理，但未证实。"},{"era":"LATIN","en":"classicus 'of the first class' is derived from classis and later gives English classic and classical.","cn":"classicus“头等的”由 classis 派生，后来给出英语 classic 与 classical。"},{"era":"FRENCH","en":"French classifier joins classe with -ifier, from Latin -ificare 'to make', so 'to make into a class'.","cn":"法语 classifier 把 classe 与 -ifier 结合，后者出自拉丁 -ificare“使…”，即“使成为一类”。"},{"era":"18C","en":"English adopts classify in the 18C; the agent noun classifier follows with the ordinary -er suffix.","cn":"英语于十八世纪引入 classify；施事名词 classifier 随后以普通 -er 后缀构成。"},{"era":"20C","en":"Linguistics applies classifier to Chinese measure words and to sign-language handshapes, extending the sorting image to grammar.","cn":"二十世纪语言学把 classifier 用于汉语“本”这类词及手语手形，把分拣意象扩展到语法。"}]},"similar":{"note":{"en":"The first group is the classify family and its endings; the second is words for sorting, which differ in whether they name a person, a system, or a single act.","cn":"第一组是 classify 词族及词尾；第二组是“分类”相关词，差别在于指人、指系统还是指一次动作。"},"groups":[{"heading":"WORD FAMILY","entries":[{"word":"classification","ipa":"/ˌklæsɪfɪˈkeɪʃn/","tag":"noun","definition":"the act or system of putting things into classes.","definitionCN":"把事物归类的动作或体系。"},{"word":"classify","ipa":"/ˈklæsɪfaɪ/","tag":"verb","definition":"to arrange into groups according to shared features.","definitionCN":"按共同特征分组。"},{"word":"classifiable","ipa":"/ˈklæsɪfaɪəbl/","tag":"adjective","definition":"able to be placed in a class.","definitionCN":"可被归类的。"}]},{"heading":"NEAR MEANING","entries":[{"word":"taxonomist","ipa":"/tækˈsɒnəmɪst/","tag":"person noun","definition":"a scientist who names and groups organisms. It is the biological specialist of classifier.","definitionCN":"给生物命名并分组的科学家。是 classifier 在生物学的专指。"},{"word":"sorter","ipa":"/ˈsɔːtə/","tag":"noun","definition":"a person or machine that separates items. It is more physical and less technical.","definitionCN":"分拣人或分拣机。更具体，少技术性。"},{"word":"label","ipa":"/ˈleɪbl/","tag":"noun","definition":"a tag naming the class of something. It is the output of classification, not the agent.","definitionCN":"标明类别的标签。是分类的输出，而非施事。"}]}]},"mnemonics":{"normalIntro":{"en":"Real links: Latin classis 'class', facere 'make' via -ify, and the -er suffix that covers both people and machines.","cn":"真实联系：拉丁 classis“类别”、经 -ify 的 facere“做”，以及兼指人与机器的 -er 后缀。"},"normal":[{"en":"Classify = class + -ify, 'make into a class'; add -er and you have the maker of classes.","cn":"classify = class + -ify“使成类”；再加 -er，就得到“造类者”。"},{"en":"The same -er makes 'worker' and 'printer'. That is why a classifier can be a person or a machine.","cn":"同一个 -er 造出 worker 与 printer。故 classifier 可以是人，也可以是机器。"},{"en":"In Chinese, the phrase for 'one book' needs the measure word ben; the classifier is the drawer the noun must go into before it can be counted.","cn":"汉语“一本书”需要“本”；类别词是名词在计数前必须进入的抽屉。"},{"en":"A spam filter is a classifier: it draws a line between two classes and puts each mail on one side.","cn":"垃圾邮件过滤器就是分类器：在两类之间画一条线，把每封邮件放一边。"},{"en":"classis also meant 'fleet'. A fleet is a class of ships, which is a useful picture of a group called together.","cn":"classis 也指“舰队”。舰队就是一类船，这是“被召集的一组”的好画面。"}],"abstract":[{"en":"Classification is power: the one who draws the classes decides what counts as same and what counts as other.","cn":"分类即权力：画类的人决定什么算相同、什么算相异。"},{"en":"Every classifier, human or machine, encodes a prior decision about which differences matter.","cn":"每个分类者，无论人或机器，都编码了“哪些差异重要”的先在决定。"},{"en":"A label is the trace of a judgement; mistaking the trace for the thing is how categories harden into prejudice.","cn":"标签是判断的痕迹；把痕迹当作事物本身，类别就硬化为偏见。"}]},"examples":[{"en":"The classifier placed the new species in its own genus.","cn":"分类者把新物种归入独立属。"},{"en":"Chinese requires a classifier between a number and a noun.","cn":"汉语在数词与名词之间需要类别词。"},{"en":"The trained classifier reaches 94 percent accuracy.","cn":"训练好的分类器达到百分之九十四的准确率。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“克拉西法伊尔”——把克拉（carat）分成等级的人 → classifier 分类者/分类器","word":"classifier"},"root":"classify（法语 classifier，基于拉丁 classis“等级、类别”+-ifier“使…”）+ -er；classis 词源存疑，一说与 calare“召集”相关。","sensesIntro":{"en":"Nine senses of classifier: a person, a machine, a grammar word, a sign-language handshape, a learning algorithm, a taxonomist, a librarian, a content filter, and a class label. All of them draw or apply a line between classes.","cn":"classifier 的九个义项：人、机器、语法词、手语手形、学习算法、生物分类学者、图书分类员、内容过滤器、类别标签。它们都在类与类之间画线或应用已有的线。"},"semanticMap":{"core":{"en":"CORE IMAGE: a hand placing each object into a labelled drawer.","cn":"核心意象：一只手把每件东西放进贴有标签的抽屉。"},"chain":["DRAW THE CLASSES","NAME EACH CLASS","ATTACH A MARKER","READ THE FEATURES","SCORE A NEW ITEM","FILE IT AWAY"],"branches":[{"senses":"S1 · S6 · S7","en":"THE PERSON: a worker, a scientist, a librarian each applies a scheme of classes.","cn":"人：工人、科学家、图书馆员各自应用一套类别体系。"},{"senses":"S2","en":"THE MACHINE: a separator does the sorting with air, weight, or mesh.","cn":"机器：分选机用气流、重量或筛网完成分拣。"},{"senses":"S3 · S4","en":"THE MARKER: grammar and sign language put the class into the noun's companion.","cn":"标记：语法与手语把类别放进名词的伴随成分。"},{"senses":"S5 · S8","en":"THE ALGORITHM: a trained boundary assigns labels and filters content.","cn":"算法：训练出的边界分配标签并过滤内容。"},{"senses":"S9","en":"THE TRACE: the label left behind is the act of sorting turned into metadata.","cn":"痕迹：留下的标签是分拣动作变成的元数据。"}]},"affixes":{"intro":{"en":"Classifier is classify plus -er. Classify is class + -ify, from Latin classis and facere. The family includes classification, classificatory, and classifiable; the base also gives class, classic, and classical.","cn":"classifier 是 classify 加 -er。classify 是 class + -ify，出自拉丁 classis 与 facere。词族含 classification、classificatory、classifiable；词基还给出 class、classic、classical。"},"latinIntro":{"en":"Latin classis 'division, class' combines with -ificare 'to make' to form classifiere in Medieval Latin and classifier in French. English adds -ation, -atory, and -able to the same stem. The root classis also yields classicus 'first class', hence classic.","cn":"拉丁 classis“类别”与 -ificare“使…”结合，形成中世纪拉丁 classifiere 与法语 classifier。英语在同一词干上加 -ation、-atory、-able。词根 classis 还给出 classicus“头等的”，即 classic。"},"items":[{"word":"classifies","structure":"classify + -es (3sg)","meaning":"puts into classes","meaningCN":"归类（三单）","example":"she classifies the samples","exampleCN":"她把样本归类"},{"word":"classified","structure":"classify + -ed (past/participle)","meaning":"placed in a class; also 'secret'","meaningCN":"已归类的；也指“机密的”","example":"classified documents","exampleCN":"机密文件"},{"word":"classifying","structure":"classify + -ing (participle)","meaning":"the act of sorting","meaningCN":"归类中的","example":"classifying plants","exampleCN":"对植物进行分类"},{"word":"classification","structure":"classify + -ation (noun)","meaning":"the act or system of sorting","meaningCN":"分类；分类体系（-ation 名词）","example":"a classification system","exampleCN":"分类体系"},{"word":"classificatory","structure":"classify + -atory (adjective)","meaning":"serving to classify","meaningCN":"分类上的（-atory 形容词）","example":"classificatory criteria","exampleCN":"分类标准"},{"word":"classifiable","structure":"classify + -able (adjective)","meaning":"able to be classified","meaningCN":"可归类的（-able 形容词）","example":"classifiable data","exampleCN":"可归类数据"},{"word":"class","structure":"Latin classis (base)","meaning":"a group, rank, or lesson group","meaningCN":"类别；等级；班级（词基）","example":"a social class","exampleCN":"社会阶层"},{"word":"classic","structure":"classis + -icus (same root)","meaning":"of the highest class","meaningCN":"经典的（同根）","example":"a classic example","exampleCN":"经典例子"},{"word":"classify","structure":"classis + -fy (verb)","meaning":"to arrange into classes","meaningCN":"分类（动词）","example":"classify the data","exampleCN":"对数据分类"}],"latinEntries":[{"word":"classis","structure":"Latin noun","meaning":"a division or class; also a fleet","meaningCN":"等级；类别；舰队"},{"word":"classicus","structure":"classis + -icus","meaning":"of the first class","meaningCN":"头等的；经典的"},{"word":"classificare","structure":"classis + facere","meaning":"to divide into classes (Medieval Latin)","meaningCN":"划分为类（中世纪拉丁）"},{"word":"facere","structure":"Latin verb","meaning":"to make, do","meaningCN":"做；使"}]}},{"word":"clarification","ipa_uk":"/ˌklærɪfɪˈkeɪʃn/","ipa_us":"/ˌklærəfəˈkeɪʃn/","definition_zh":"澄清；说明；澄清声明；（液体）澄清、精炼；语义消歧；（概念）厘清","definition_en":"the act of making something clear or understandable; an explanation that removes confusion; the process of making a liquid clear","core_image":"一杯浑水静置后杂质沉底，上面渐渐透亮，像一句话被解释到没有歧义","scene":"会后他发了一封邮件，对刚才那条政策逐条说明。After the meeting he sends an email that offers a clarification of the policy: which clause applies and which does not.","sceneCN":"这里 clarification 是「澄清说明、消除误解的解释」（第 1 个义项：使某事清楚易懂的行为或说明）；句意：会后他发邮件对那条政策作出澄清：哪一条适用、哪一条不适用。图中可辨识物件：邮件窗口、政策文件、荧光笔、两栏对照表、浑水杯。","pos":[{"tag":"n.","zh":"澄清；说明；澄清声明"},{"tag":"n.","zh":"（液体）澄清；精炼；净化"}],"collocations":[{"phrase":"ask for clarification","zh":"请求澄清"},{"phrase":"seek clarification","zh":"寻求说明"},{"phrase":"a clarification of the rules","zh":"对规则的澄清"},{"phrase":"provide clarification","zh":"提供说明"},{"phrase":"clarified butter","zh":"澄清黄油"},{"phrase":"a point of clarification","zh":"需要澄清的一点"}],"forms":[{"label":"复数","form":"clarifications"},{"label":"动词","form":"clarify"},{"label":"形容词","form":"clarifying / clarificatory"},{"label":"相关名词","form":"clarity"}],"derivatives":[{"word":"clarify","pos":"v.","zh":"澄清；阐明；使清澈"},{"word":"clarifying","pos":"adj.","zh":"澄清的；说明性的"},{"word":"clarity","pos":"n.","zh":"清晰；明确"},{"word":"clarificant","pos":"n.","zh":"澄清剂"}],"senses":[{"no":"01","title":"An explanation that removes confusion","titleCN":"澄清说明","definition":"an explanation that makes a statement or situation easier to understand","definitionCN":"使陈述或情形更易理解的解释","example":"The memo offered a clarification of the new policy.","exampleCN":"备忘录对新政策作了澄清。","why":"This is the dominant modern sense: words, not liquids, are made clear. The clarification does not change the rule; it removes the fog around it.","whyCN":"这是现代主导义：被澄清的是话，不是液体。澄清不改变规则，只去掉规则周围的雾。"},{"no":"02","title":"Making a liquid clear","titleCN":"（液体）澄清","definition":"the process of removing suspended particles so that a liquid becomes transparent","definitionCN":"去除悬浮颗粒使液体变透明的过程","example":"Filtration is the first step in water clarification.","exampleCN":"过滤是水澄清的第一步。","why":"The physical sense is the source image: suspended matter settles or is filtered out, and light passes through. Every later sense keeps this 'remove what blocks seeing' structure.","whyCN":"物理义是源意象：悬浮物沉降或被滤掉，光得以穿过。后来各义都保留这个“去掉挡住视线之物”的结构。"},{"no":"03","title":"Refining butter","titleCN":"（黄油）澄清；精炼","definition":"the process of melting butter and removing milk solids and water","definitionCN":"融化黄油并去除乳固体与水的工序","example":"Clarification raises butter's smoke point.","exampleCN":"澄清能提高黄油的烟点。","why":"Cooking narrows the process to a fat: heat separates the pure butterfat from the parts that burn. The word names a purification that also changes how the substance behaves.","whyCN":"烹饪把过程收窄到油脂：加热把纯乳脂与会烧焦的部分分开。该词命名一种同时改变物质行为的提纯。"},{"no":"04","title":"An official statement","titleCN":"官方澄清声明","definition":"a public statement issued to correct a misunderstanding or rumour","definitionCN":"为纠正误解或传言而发布的公开声明","example":"The ministry issued a clarification about the report.","exampleCN":"该部就报道发布了澄清声明。","why":"Institutions use clarification to correct the record without admitting fault. The genre is defensive: it says 'we did not mean that', and its tone is careful, impersonal, and often legal.","whyCN":"机构用 clarification 纠正记录而不认错。该文体是防御性的：它说“我们不是那个意思”，语气谨慎、非个人化，常带法律味。"},{"no":"05","title":"Disambiguation","titleCN":"（语义）消歧","definition":"the removal of ambiguity from a word, sentence, or rule","definitionCN":"去除词、句或规则中的歧义","example":"The lawyer asked for a clarification of clause 7.","exampleCN":"律师要求对第七条作消歧说明。","why":"Here the fog is ambiguity itself. Clarification chooses one reading among several, and the choice is often the real dispute, since each side wants its own reading fixed.","whyCN":"此处雾就是歧义本身。澄清在数种读法中选一种，而选择常是真正的争点，因为各方都想把自己的读法定下来。"},{"no":"06","title":"Making thought clear","titleCN":"（概念）厘清","definition":"the act of defining a concept so that it can be used consistently","definitionCN":"界定概念使其能被一致使用","example":"The paper begins with a clarification of terms.","exampleCN":"论文以术语厘清开篇。","why":"Academic writing uses the word for the preliminary work of definition. Concepts are treated as cloudy liquids: the unclear part is allowed to settle before argument begins.","whyCN":"学术写作把该词用于定义的预备工作。概念被当作浑浊液体：在论证开始前，让不清楚的部分先沉淀。"},{"no":"07","title":"Fining wine or juice","titleCN":"（酒/果汁）下胶澄清","definition":"the removal of haze from wine or juice by adding a fining agent","definitionCN":"通过加入澄清剂去除酒或果汁中的浑浊","example":"Bentonite is used in wine clarification.","exampleCN":"膨润土用于葡萄酒澄清。","why":"Winemaking gives the process a technical agent: proteins or clay bind haze particles and drag them down. The word stays physical, but the cause is chemical rather than mere settling.","whyCN":"酿酒给过程一个技术性施事：蛋白质或黏土结合浑浊颗粒并把它拖下。词仍是物理的，但成因是化学的，而非单纯沉降。"},{"no":"08","title":"Refining sugar","titleCN":"（糖液）精炼；澄清","definition":"the removal of impurities from sugar liquor before crystallisation","definitionCN":"在结晶前去除糖液中的杂质","example":"Lime is added during juice clarification.","exampleCN":"汁液澄清时加入石灰。","why":"Sugar engineering uses clarification for a step in a chain of purification. Here the goal is not transparency for its own sake but a cleaner crystal, so clarity is a means to purity.","whyCN":"制糖工程把 clarification 用作提纯链中的一步。此处目的不是为透明而透明，而是更纯的晶体，故清澈是纯度的手段。"},{"no":"09","title":"A request for explanation","titleCN":"（请求）澄清","definition":"a question asked in order to have something explained","definitionCN":"为使某事得到解释而提出的问题","example":"She raised a point of clarification.","exampleCN":"她提出一个需要澄清的问题。","why":"This metonymic sense names the request rather than the answer: 'a clarification' can be the act of asking. It is common in meetings, where the floor is asked to make way for understanding.","whyCN":"这是转喻义，指请求而非回答：“a clarification”可以就是提问的动作。会议中常见，用于为理解让出空间。"}],"etymology":{"intro":{"en":"Clarification is clarify plus -ation. Clarify comes from Old French clarifier, from Latin clarificare, itself clarus 'clear, bright' plus facere 'to make': to make clear. The -ation suffix goes back to Latin -atio, the noun of action. The word's history is a steady move from physical brightness to transparency to intellectual clarity. Note that clear is from the same clarus through Old French cler, and declare is clarare with a different prefix; they are relatives, not the same word.","cn":"clarification 是 clarify 加 -ation。clarify 出自古法语 clarifier，源于拉丁 clarificare，即 clarus“明亮、清楚”加 facere“使”：使清楚。-ation 后缀上溯拉丁 -atio，是动作名词。该词史是从物理明亮到透明、再到理智清晰的稳定移动。注意 clear 经古法语 cler 也出自同一 clarus，而 declare 是加不同前缀的 clarare；它们是亲属，不是同一词。"},"items":[{"era":"LATIN","en":"clarus means 'clear, bright, distinct'; it describes both light and speech that can be heard or understood.","cn":"clarus 意为“明亮的、清楚的、分明的”；既形容光，也形容可听可懂的话。"},{"era":"LATIN","en":"clarificare joins clarus with facere 'to make', literally 'to make clear'.","cn":"clarificare 把 clarus 与 facere“使”结合，字面即“使清楚”。"},{"era":"LATIN","en":"clarificatio is the action noun; English -ation continues this pattern of abstract nouns.","cn":"clarificatio 是动作名词；英语 -ation 延续这一抽象名词模式。"},{"era":"OLD FRENCH","en":"Old French clarifier 'to make clear, explain' carries the verb into English in the 14C.","cn":"古法语 clarifier“使清楚、解释”于十四世纪把动词带入英语。"},{"era":"16C","en":"The noun clarification appears in English for both explaining and purifying, keeping the physical and mental senses together.","cn":"名词 clarification 于十六世纪出现在英语中，兼指解释与提纯，把物理义与心智义放在一起。"},{"era":"MODERN","en":"Modern English specializes the noun: policy clarifications, semantic clarification, and industrial or culinary fining all share the 'remove what blocks clarity' pattern.","cn":"现代英语使该名词专门化：政策澄清、语义消歧、工业与烹饪澄清，都共享“去除挡住清晰之物”的模式。"}]},"similar":{"note":{"en":"The first group is the clarify family and its endings; the second is words for explaining, which differ in whether they remove ambiguity, add detail, or correct an error.","cn":"第一组是 clarify 词族及词尾；第二组是“解释”类词，差别在于去除歧义、补充细节还是纠正错误。"},"groups":[{"heading":"WORD FAMILY","entries":[{"word":"clarify","ipa":"/ˈklærɪfaɪ/","tag":"verb","definition":"to make something clear or easier to understand.","definitionCN":"使清楚或更易理解。"},{"word":"clarity","ipa":"/ˈklærəti/","tag":"noun","definition":"the quality of being clear and easy to follow.","definitionCN":"清楚易懂的性质。"},{"word":"clarified","ipa":"/ˈklærɪfaɪd/","tag":"adjective","definition":"made clear, or purified of solids.","definitionCN":"被澄清的；被提纯的。"}]},{"heading":"NEAR MEANING","entries":[{"word":"explanation","ipa":"/ˌekspləˈneɪʃn/","tag":"noun","definition":"a statement that makes something understandable by giving reasons or details. It adds information; clarification removes confusion.","definitionCN":"通过理由或细节使某事可理解的陈述。它增加信息；clarification 去除混乱。"},{"word":"elucidation","ipa":"/ˌiːluːsɪˈdeɪʃn/","tag":"noun","definition":"the act of making something obscure fully clear, often by careful analysis. It is more formal and thorough.","definitionCN":"使晦涩之事完全清楚的行为，常靠细致分析。更正式、更彻底。"},{"word":"disambiguation","ipa":"/ˌdɪsæmbɪɡjuˈeɪʃn/","tag":"noun","definition":"the removal of a specific ambiguity between two or more readings. It is narrower and technical.","definitionCN":"去除两种或多种读法之间的特定歧义。更窄、更技术。"}]}]},"mnemonics":{"normalIntro":{"en":"Real links: Latin clarus 'clear', facere 'make', the -ation action noun, and the physical image of a settling liquid.","cn":"真实联系：拉丁 clarus“清楚”、facere“使”、-ation 动作名词，以及液体沉降的物理意象。"},"normal":[{"en":"Clarificare is 'make clear'. Add -ation and you have the making, not the clear thing.","cn":"clarificare 是“使清楚”。加 -ation 得到“使”的过程，而非清楚之物。"},{"en":"The image is a muddy glass: let the particles fall, and light passes through. Words work the same way.","cn":"意象是一杯浑水：让颗粒落下，光便穿过。话语亦然。"},{"en":"Clarify and clear are cousins: both go back to clarus through French. Declare is another cousin with a different prefix.","cn":"clarify 与 clear 是表亲：都经法语上溯 clarus。declare 是另一个加不同前缀的表亲。"},{"en":"Butter becomes 'clarified' when the milk solids are removed; the word is doing literal purification.","cn":"黄油去掉乳固体后叫 clarified；此处该词在做字面上的提纯。"},{"en":"A 'point of clarification' is a polite way to say 'I do not follow you'. The request, not the answer, gets the name.","cn":"a point of clarification 是“我没跟上”的礼貌说法。得到这个名字的是请求，不是回答。"}],"abstract":[{"en":"Clarification does not add truth; it removes the obstacles that hide truth already present.","cn":"澄清不增加真理；它去掉遮住已有真理的障碍。"},{"en":"Every institution's clarification is also a boundary-setting act: it decides which reading is now official.","cn":"每个机构的澄清同时是划界行为：它决定哪种读法现在是官方的。"},{"en":"To clarify is to make the listener's model of the world match the speaker's, without changing the world.","cn":"澄清是让听者的世界模型与说者的一致，而不改变世界。"}]},"examples":[{"en":"I need a clarification of the second paragraph.","cn":"我需要有人解释一下第二段。"},{"en":"The company issued a clarification after the rumour spread.","cn":"传言扩散后，公司发布了澄清声明。"},{"en":"Clarification removes suspended solids from the juice.","cn":"澄清工序去除果汁中的悬浮固体。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“克拉里菲克ation”——把克拉级的浑浊液体滤清 → clarification 澄清","word":"clarification"},"root":"clarify（古法语 clarifier ← 拉丁 clarificare = clarus“清楚、明亮”+ facere“使”）+ -ation（拉丁 -atio 动作名词）。","sensesIntro":{"en":"Nine senses of clarification: an explanation, a liquid made clear, refined butter, an official statement, disambiguation, conceptual definition, wine fining, sugar refining, and a request for explanation. The invariant is the removal of whatever blocks clarity.","cn":"clarification 的九个义项：解释、液体澄清、黄油精炼、官方声明、消歧、概念界定、葡萄酒下胶、糖液精炼、请求解释。不变量是去除一切挡住清晰之物。"},"semanticMap":{"core":{"en":"CORE IMAGE: a cloudy glass left to settle until light passes straight through.","cn":"核心意象：一杯浑水静置，直到光笔直穿过。"},"chain":["SUSPEND THE HAZE","LET IT SETTLE","FILTER OR BIND IT","MAKE THE LIQUID CLEAR","MAKE THE MEANING CLEAR","FIX ONE READING"],"branches":[{"senses":"01 · 04 · 09","en":"THE WORD: explanation, official statement, and request all work on sentences.","cn":"话：解释、官方声明与请求都作用于句子。"},{"senses":"02 · 07 · 08","en":"THE LIQUID: settling, fining, and refining remove physical haze.","cn":"液体：沉降、下胶与精炼去除物理浑浊。"},{"senses":"03","en":"THE FAT: butter is purified of milk solids, a culinary case of the same process.","cn":"油脂：黄油去除乳固体，是同一过程的烹饪实例。"},{"senses":"05","en":"THE WORD: ambiguity is the haze that must settle before argument.","cn":"概念：歧义是论证前必须散去的雾。"},{"senses":"06","en":"THE METHOD: definition is the instrument that makes a concept usable.","cn":"方法：定义是使概念可用的工具。"}]},"affixes":{"intro":{"en":"Clarification is clarify + -ation. Clarify is Latin clarificare, clarus plus facere. The family includes clarity, clarified, and clarificant; the root clarus also gives clear, declare, and clarion.","cn":"clarification 是 clarify 加 -ation。clarify 是拉丁 clarificare，即 clarus 加 facere。词族含 clarity、clarified、clarificant；词根 clarus 还给出 clear、declare、clarion。"},"latinIntro":{"en":"Latin clarus 'clear' plus facere 'make' yields clarificare 'make clear'. Its action noun clarificatio passes into French clarification and English clarification. The same clarus underlies claritas 'brightness, clarity', the source of English clarity.","cn":"拉丁 clarus“清楚”加 facere“使”生成 clarificare“使清楚”。其动作名词 clarificatio 经法语 clarification 进入英语。同一 clarus 也是 claritas“明亮、清晰”的词基，即英语 clarity 的来源。"},"items":[{"word":"clarifies","structure":"clarify + -es (3sg)","meaning":"makes clear","meaningCN":"澄清（三单）","example":"the note clarifies the rule","exampleCN":"该说明澄清了规则"},{"word":"clarified","structure":"clarify + -ed (past/participle)","meaning":"made clear or purified","meaningCN":"已澄清的","example":"clarified butter","exampleCN":"澄清黄油"},{"word":"clarifying","structure":"clarify + -ing (participle)","meaning":"in the act of making clear","meaningCN":"澄清中的","example":"a clarifying question","exampleCN":"澄清性问题"},{"word":"clarification","structure":"clarify + -ation (noun)","meaning":"the act of making clear","meaningCN":"澄清；说明（-ation 名词）","example":"a policy clarification","exampleCN":"政策澄清"},{"word":"clarificatory","structure":"clarify + -atory (adjective)","meaning":"serving to clarify","meaningCN":"澄清性的（-atory 形容词）","example":"clarificatory remarks","exampleCN":"澄清性发言"},{"word":"clarity","structure":"clarus + -itas (noun)","meaning":"clearness of thought or expression","meaningCN":"清晰；明确（-ity 名词）","example":"clarity of purpose","exampleCN":"目标明确"},{"word":"clear","structure":"clarus via Old French cler (adjective)","meaning":"bright, transparent, easy to understand","meaningCN":"清楚的；透明的（同根）","example":"clear water","exampleCN":"清澈的水"},{"word":"declare","structure":"de- + clarare (same root)","meaning":"to make clear publicly","meaningCN":"宣布；声明（同根，前缀不同）","example":"declare independence","exampleCN":"宣布独立"},{"word":"clarion","structure":"clarus + -ion (noun)","meaning":"a clear-sounding trumpet","meaningCN":"号角（同根，音色清楚）","example":"a clarion call","exampleCN":"响亮的号召"}],"latinEntries":[{"word":"clarus","structure":"Latin adjective","meaning":"clear, bright, distinct","meaningCN":"明亮的；清楚的"},{"word":"clarificare","structure":"clarus + facere","meaning":"to make clear","meaningCN":"使清楚"},{"word":"clarificatio","structure":"clarificare + -tio","meaning":"a making clear","meaningCN":"澄清；说明"},{"word":"claritas","structure":"clarus + -itas","meaning":"brightness, clarity","meaningCN":"明亮；清晰"}]}},{"word":"collectively","ipa_uk":"/kəˈlektɪvli/","ipa_us":"/kəˈlektɪvli/","definition_zh":"集体地；共同地；总计地；作为整体地；统称地；集体负责地","definition_en":"as a group rather than individually; by the combined action or total of many; taken together","core_image":"许多只手把各自的绳子拉到同一根桅杆上，桅杆才立起来","scene":"这些实验单独看都不显著。Taken one by one the experiments are not significant, but collectively they point to a stable effect.","sceneCN":"这里 collectively 是「综合起来、作为整体来看」（第 6 个义项：把多个项目合并考虑）；句意：这些实验单独看不显著，综合起来却指向一个稳定的效应。图中可辨识物件：多组图表、合并后的趋势线、统计软件窗口、放大镜、绳索。","pos":[{"tag":"adv.","zh":"集体地；共同地；总计地；作为整体地"}],"collocations":[{"phrase":"collectively known as","zh":"统称为"},{"phrase":"collectively responsible","zh":"集体负责"},{"phrase":"work collectively","zh":"集体工作"},{"phrase":"collectively bargain","zh":"集体谈判"},{"phrase":"collectively account for","zh":"合计占"},{"phrase":"collectively agree","zh":"共同同意"}],"forms":[{"label":"形容词","form":"collective"},{"label":"名词","form":"collective / collectivity"},{"label":"动词","form":"collectivize"},{"label":"名词","form":"collectivism"}],"derivatives":[{"word":"collective","pos":"adj./n.","zh":"集体的；集体"},{"word":"collectivity","pos":"n.","zh":"集体性；集体"},{"word":"collectivism","pos":"n.","zh":"集体主义"},{"word":"collectivize","pos":"v.","zh":"集体化"}],"senses":[{"no":"01","title":"As a group","titleCN":"集体地；作为群体","definition":"acting or happening as one group rather than as separate individuals","definitionCN":"以一个群体而非各自单独地行动或发生","example":"The workers collectively refused the offer.","exampleCN":"工人们集体拒绝了这一提议。","why":"This is the core adverb: the subject is plural, but the action is attributed to the group as a unit. It answers 'how', and its force is unity of action.","whyCN":"这是核心副词义：主语为复数，但动作归于作为单位的群体。它回答“如何”，力量来自行动的统一。"},{"no":"02","title":"By combined effort","titleCN":"共同地","definition":"through the added effort of many people","definitionCN":"通过许多人的合力","example":"They collectively rebuilt the bridge.","exampleCN":"他们共同重建了这座桥。","why":"Here the emphasis is labour added together. No single hand could do it; the adverb reports a sum of contributions that produces a result none could produce alone.","whyCN":"此处强调劳动相加。没有哪一只手能完成；副词报告贡献之和，产生了任何单方都无法产生的结果。"},{"no":"03","title":"In total","titleCN":"总计地；合计","definition":"when the amounts of several items are added together","definitionCN":"把若干项的数量相加时","example":"The three firms collectively employ 2,000 people.","exampleCN":"这三家公司合计雇用两千人。","why":"This sense is numerical: the group is treated as a sum. It is close to 'altogether' and often appears with numbers, shares, or percentages.","whyCN":"此义是数量性的：群体被当作总和。近于 altogether，常与数字、份额或百分比连用。"},{"no":"04","title":"Held in common","titleCN":"共同所有地；共同持有","definition":"owned or held by all members of a group rather than by individuals","definitionCN":"由群体全体而非个人拥有或持有","example":"The land was collectively owned.","exampleCN":"这块土地为集体所有。","why":"Property language gives the adverb a legal edge: title rests with the group. The contrast is with private ownership, and the word can carry a political charge.","whyCN":"财产语给副词法律边缘：产权归于群体。对照是私有，词可带政治色彩。"},{"no":"05","title":"As shared responsibility","titleCN":"集体负责地","definition":"with responsibility borne by the group rather than one person","definitionCN":"责任由群体而非一人承担","example":"The cabinet is collectively responsible to parliament.","exampleCN":"内阁对议会集体负责。","why":"Constitutional usage makes accountability collective: a decision binds all members, so praise or blame cannot be assigned to one. The adverb names a doctrine, not just a fact.","whyCN":"宪制用法使问责集体化：决定约束全体，故褒贬不能归于一人。副词命名一种学说，而不只是事实。"},{"no":"06","title":"Taken together","titleCN":"综合起来；整体来看","definition":"when several items are considered as a whole rather than one by one","definitionCN":"把若干项作为整体而非逐项考虑","example":"Collectively, the studies suggest a link.","exampleCN":"综合来看，这些研究提示存在关联。","why":"Research writing uses the adverb to shift the level of analysis. Each study may be weak; the body of evidence, taken together, may be strong. This is an inferential move, not a sum.","whyCN":"研究写作把副词用于切换分析层级。单项研究可能弱；证据整体合并可能强。这是推论动作，不是加法。"},{"no":"07","title":"Through collective bargaining","titleCN":"（集体）谈判地","definition":"through negotiation conducted by a union on behalf of a group of workers","definitionCN":"由工会代表一群工人进行谈判","example":"Wages are set collectively.","exampleCN":"工资通过集体谈判确定。","why":"Industrial relations fixes the adverb to a procedure: the group speaks with one voice because one bargaining agent represents it. The word names the mechanism, not the mood.","whyCN":"劳资关系把副词固定到程序：群体以一口说话，因为一个谈判代理人代表它。该词命名机制，而非情绪。"},{"no":"08","title":"By common consent","titleCN":"共同一致地","definition":"by the agreement of all or most members of a group","definitionCN":"经群体全体或多数同意","example":"The members collectively approved the plan.","exampleCN":"成员共同批准了该计划。","why":"Here collective action is also collective assent. The adverb can hide whether the agreement was unanimous or majoritarian, which is often the point of dispute.","whyCN":"此处集体行动也是集体同意。副词可掩盖同意是全票还是多数，而这常是争点。"},{"no":"09","title":"Under one name","titleCN":"统称地；总称地","definition":"when several things are referred to by a single shared label","definitionCN":"用同一个名称指称若干事物","example":"These animals are collectively called ruminants.","exampleCN":"这些动物统称为反刍动物。","why":"Naming is the loosest sense: the group exists because a word gathers its members. The adverb marks a linguistic bundling, which may or may not reflect a real class.","whyCN":"命名是最松的义：群体因一个词而聚。副词标记语言上的打包，未必反映真实的类。"}],"etymology":{"intro":{"en":"Collectively is collective plus -ly. Collective comes from Latin collectivus, from colligere 'to gather together', itself com- 'together' plus legere 'to gather, pick, read'. The -ive suffix is Latin -ivus; -ly is the English adverb ending from Old English -lice. The base legere also gives collect, select, elect, lecture, and legible, so the family is wide. The semantic path is 'gathered' → 'of a group' → 'as a group'.","cn":"collectively 是 collective 加 -ly。collective 出自拉丁 collectivus，源于 colligere“聚拢”，即 com-“一起”加 legere“收集、拾取、读”。-ive 是拉丁 -ivus；-ly 是英语副词后缀，出自古英语 -lice。词基 legere 还给出 collect、select、elect、lecture、legible，词族很广。语义路径是“被聚拢” → “群体的” → “以群体方式”。"},"items":[{"era":"LATIN","en":"legere means 'to gather, pick up, read'; it is the root of a large family of collecting and selecting words.","cn":"legere 意为“收集、拾取、读”，是收集与选择一大词族的根。"},{"era":"LATIN","en":"colligere is com- 'together' plus legere 'gather': to bring things into one place.","cn":"colligere 是 com-“一起”加 legere“收集”：把东西聚到一处。"},{"era":"LATIN","en":"collectivus 'serving to collect, of a collective' is formed from the past participle collectus plus -ivus.","cn":"collectivus“用于收集的、集体的”由过去分词 collectus 加 -ivus 构成。"},{"era":"17C","en":"English collective appears in the 17C in philosophy and politics, naming what belongs to a group.","cn":"英语 collective 于十七世纪出现在哲学与政治中，命名属于群体之物。"},{"era":"19C","en":"Collectivism and collective ownership become political terms, giving the adverb a doctrinal edge.","cn":"十九世纪，集体主义与集体所有成为政治术语，使副词带上学说色彩。"},{"era":"MODERN","en":"Collectively now ranges from arithmetic totals to research synthesis to constitutional responsibility.","cn":"现代 collectively 从算术总计，延伸到研究综合与宪制责任。"}]},"similar":{"note":{"en":"The first group is the collective family and its endings; the second is adverbs of grouping, which differ in whether they mean together, in total, or by common consent.","cn":"第一组是 collective 词族及词尾；第二组是“聚合”类副词，差别在于指共同、总计还是一致同意。"},"groups":[{"heading":"WORD FAMILY","entries":[{"word":"collective","ipa":"/kəˈlektɪv/","tag":"adjective/noun","definition":"shared by a group; a group or enterprise owned in common.","definitionCN":"群体共享的；共有团体或企业。"},{"word":"collectivity","ipa":"/ˌkɒlekˈtɪvəti/","tag":"noun","definition":"the state of being a collective whole.","definitionCN":"作为集体整体的状态。"},{"word":"collectivism","ipa":"/kəˈlektɪvɪzəm/","tag":"noun","definition":"the doctrine that the group or state should own the means of production.","definitionCN":"主张群体或国家应拥有生产资料的学说。"}]},{"heading":"NEAR MEANING","entries":[{"word":"together","ipa":"/təˈɡeðə/","tag":"adverb","definition":"in company or in one place. It is spatial and simple; collectively adds the idea of a group acting as one.","definitionCN":"在一起或在一处。空间而简单；collectively 增加“群体作为一体行动”。"},{"word":"jointly","ipa":"/ˈdʒɔɪntli/","tag":"adverb","definition":"by two or more parties sharing an action or responsibility. It stresses the parties more than the group.","definitionCN":"由两个或多个方共同行动或负责。更强调各方，而非群体。"},{"word":"altogether","ipa":"/ˌɔːltəˈɡeðə/","tag":"adverb","definition":"in total, completely. It is the arithmetic sense of collectively.","definitionCN":"完全地；总共。是 collectively 的算术义。"}]}]},"mnemonics":{"normalIntro":{"en":"Real links: legere 'gather', colligere 'bring together', the -ive adjective and -ly adverb, and the shift from 'gathered' to 'as a group'.","cn":"真实联系：legere“收集”、colligere“聚拢”、-ive 形容词与 -ly 副词，以及从“被聚拢”到“以群体方式”的偏移。"},"normal":[{"en":"Collect is 'gather together'; collective is 'of the gathered group'; collectively is 'in that manner'.","cn":"collect 是“聚拢”；collective 是“被聚拢群体的”；collectively 是“以那种方式”。"},{"en":"The root legere also means 'read', which is why lecture and legible sit in the same family: reading is gathering letters.","cn":"词根 legere 也指“读”，故 lecture 与 legible 同族：读就是收集字母。"},{"en":"Numbers: three firms collectively employ 2,000. The adverb turns three subjects into one sum.","cn":"数字：三家公司合计雇两千人。副词把三个主语变成一笔总和。"},{"en":"Politics: collective ownership puts title in the group, not the person. The adverb carries that legal edge.","cn":"政治：集体所有把产权放在群体而非个人。副词带着这一法律边缘。"},{"en":"'Collectively known as' means a name, not a proof, has gathered the members.","cn":"collectively known as 意味着是名称、而非证据，把成员聚在一起。"}],"abstract":[{"en":"The collective is a level of description: the same facts can be told one by one or as a group, and the level changes the inference.","cn":"集体是一个描述层级：同一事实可逐项讲，也可作为群体讲，层级改变推论。"},{"en":"Every collective claim hides a rule of aggregation; the adverb never tells you whether the group is a sum, a consensus, or a fiction.","cn":"每个集体主张都藏有一条聚合规则；副词从不告诉你群体是总和、共识还是虚构。"},{"en":"Responsibility that is collectively held can be shared or evaded; the same word supports both solidarity and diffusion.","cn":"集体承担的责任既可分担也可推卸；同一个词同时支持团结与分散。"}]},"examples":[{"en":"The three countries collectively produce half the world's coffee.","cn":"这三个国家合计生产世界一半的咖啡。"},{"en":"They collectively decided to postpone the launch.","cn":"他们共同决定推迟发布。"},{"en":"These compounds are collectively known as alkaloids.","cn":"这些化合物统称为生物碱。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“科莱克提夫利”——把所有人 collect 到一起，再一起走 → collectively 集体地","word":"collectively"},"root":"collective（拉丁 collectivus ← colligere = com-“一起”+ legere“收集”）+ -ly；legere 同族有 collect、select、elect、lecture、legible。","sensesIntro":{"en":"Nine senses of collectively: as a group, by combined effort, in total, held in common, as shared responsibility, taken together, through collective bargaining, by common consent, and under one name. Each answers 'how' at the level of the group.","cn":"collectively 的九个义项：作为群体、共同出力、总计、共同所有、集体负责、综合来看、集体谈判、共同同意、统称。每一项都在群体层面回答“如何”。"},"semanticMap":{"core":{"en":"CORE IMAGE: many hands pulling separate ropes tied to one mast until it stands.","cn":"核心意象：许多只手拉着系在同一根桅杆上的绳子，直到桅杆立起。"},"chain":["GATHER THE MANY","TIE THEM TOGETHER","ACT AS ONE","ADD THE AMOUNTS","SHARE THE OWNERSHIP","NAME THE WHOLE"],"branches":[{"senses":"S1 · S2 · S8","en":"THE ACT: group action, combined labour, and common assent are one deed done by many.","cn":"行动：群体行动、合力与共同同意，是多人做的一件事。"},{"senses":"S3","en":"THE SUM: numbers are added, and the group appears as a total.","cn":"总和：数字相加，群体显现为一个总计。"},{"senses":"S4 · S5","en":"THE TITLE: common ownership and collective responsibility place rights and duties in the group.","cn":"产权：共同所有与集体责任把权利与义务放在群体。"},{"senses":"S6","en":"THE SYNTHESIS: separate studies become one body of evidence.","cn":"综合：各自的研究变成一个证据整体。"},{"senses":"S7 · S9","en":"THE MECHANISM AND THE NAME: bargaining and labelling are procedures that make a group speak or count as one.","cn":"机制与名称：谈判与命名是使群体以一口说话或算作一体的程序。"}]},"affixes":{"intro":{"en":"Collectively is collective + -ly. Collective is Latin collectivus, from colligere, com- plus legere. The family includes collectivity, collectivism, collectivize, collect, and collection; the same legere root gives select, elect, lecture, and legible.","cn":"collectively 是 collective 加 -ly。collective 是拉丁 collectivus，出自 colligere（com- 加 legere）。词族含 collectivity、collectivism、collectivize、collect、collection；同一 legere 词根给出 select、elect、lecture、legible。"},"latinIntro":{"en":"Latin legere 'gather, read' gives colligere 'gather together' and its participle collectus. collectivus adds -ivus to that stem; English keeps -ive and adds -ly, -ity, -ism, and -ize.","cn":"拉丁 legere“收集、读”给出 colligere“聚拢”及其分词 collectus。collectivus 在该词干上加 -ivus；英语保留 -ive，并加 -ly、-ity、-ism、-ize。"},"items":[{"word":"collects","structure":"collect + -s (3sg)","meaning":"gathers things together","meaningCN":"收集（三单）","example":"she collects data","exampleCN":"她收集数据"},{"word":"collected","structure":"collect + -ed (past/participle)","meaning":"gathered; also 'calm'","meaningCN":"收集了；也指“镇定”","example":"collected works","exampleCN":"文集"},{"word":"collecting","structure":"collect + -ing (participle)","meaning":"the act of gathering","meaningCN":"收集中的","example":"collecting stamps","exampleCN":"集邮"},{"word":"collection","structure":"collect + -ion (noun)","meaning":"a group of gathered things","meaningCN":"收藏；收集（-ion 名词）","example":"a stamp collection","exampleCN":"邮票收藏"},{"word":"collective","structure":"collect + -ive (adjective)","meaning":"shared by a group","meaningCN":"集体的（-ive 形容词）","example":"collective effort","exampleCN":"集体努力"},{"word":"collectively","structure":"collective + -ly (adverb)","meaning":"as a group","meaningCN":"集体地（-ly 副词）","example":"work collectively","exampleCN":"集体工作"},{"word":"collectivity","structure":"collective + -ity (noun)","meaning":"the state of being collective","meaningCN":"集体性（-ity 名词）","example":"social collectivity","exampleCN":"社会集体性"},{"word":"collectivism","structure":"collective + -ism (noun)","meaning":"the doctrine of collective ownership","meaningCN":"集体主义（-ism 名词）","example":"economic collectivism","exampleCN":"经济集体主义"},{"word":"select","structure":"se- + legere (same root)","meaning":"to pick out from a group","meaningCN":"挑选（同根，前缀不同）","example":"select a winner","exampleCN":"选出获胜者"}],"latinEntries":[{"word":"legere","structure":"Latin verb","meaning":"to gather, pick, read","meaningCN":"收集；拾取；读"},{"word":"colligere","structure":"com- + legere","meaning":"to gather together","meaningCN":"聚拢"},{"word":"collectus","structure":"past participle of colligere","meaning":"gathered","meaningCN":"被聚拢的"},{"word":"collectivus","structure":"collectus + -ivus","meaning":"of a collective","meaningCN":"集体的"}]}},{"word":"combination","ipa_uk":"/ˌkɒmbɪˈneɪʃn/","ipa_us":"/ˌkɑːmbɪˈneɪʃn/","definition_zh":"组合；结合；搭配；（数学）组合；号码组合；化合；联合；连击；基因组合","definition_en":"the act of joining two or more things; a set of things joined together; (mathematics) a selection of items from a larger set without regard to order","core_image":"两股不同颜色的线在掌心交叉，拧成一根更结实的绳","scene":"这道菜的秘诀是酸、辣、甜三种味道同时出现，却谁也不压过谁。The secret of the dish is a combination of sour, hot and sweet that lets no single taste dominate.","sceneCN":"这里 combination 是「组合、搭配」（第 1 个义项：两个或更多事物结合的状态）；句意：这道菜的秘诀是酸、辣、甜三种味道的组合，谁也不压过谁。图中可辨识物件：三只调料碗、交叉的彩线、炒锅、味碟、写有配方的卡片。","pos":[{"tag":"n.","zh":"组合；结合；搭配；联合"},{"tag":"n.","zh":"（数学）组合；（化学）化合"}],"collocations":[{"phrase":"a combination of A and B","zh":"A 与 B 的结合"},{"phrase":"a winning combination","zh":"制胜组合"},{"phrase":"a combination lock","zh":"密码锁"},{"phrase":"in combination with","zh":"与…联合"},{"phrase":"a combination of factors","zh":"多种因素的组合"},{"phrase":"mathematical combination","zh":"数学组合"}],"forms":[{"label":"复数","form":"combinations"},{"label":"动词","form":"combine"},{"label":"形容词","form":"combinational / combinative"},{"label":"口语缩略","form":"combo"}],"derivatives":[{"word":"combine","pos":"v./n.","zh":"结合；联合；联合收割机"},{"word":"combined","pos":"adj.","zh":"联合的；合并的"},{"word":"combinational","pos":"adj.","zh":"组合的"},{"word":"combinatorial","pos":"adj.","zh":"组合数学的"},{"word":"combo","pos":"n.","zh":"组合；套餐（口语）"}],"senses":[{"no":"01","title":"A joining of things","titleCN":"组合；结合","definition":"the state or result of two or more things being joined","definitionCN":"两个或更多事物被结合的状态或结果","example":"The dish is a combination of sweet and sour.","exampleCN":"这道菜是酸甜的结合。","why":"This is the general sense: separate elements are brought into one arrangement. The word does not say whether they merge or stay distinct, only that they now form a set.","whyCN":"这是总义：分离的元素被带入一个安排。该词不说它们是融合还是保持区分，只说它们现在构成一个集合。"},{"no":"02","title":"A mathematical combination","titleCN":"（数学）组合","definition":"a selection of items from a larger set where order does not matter","definitionCN":"从较大集合中选取若干项而不计顺序","example":"There are ten combinations of three items from five.","exampleCN":"从五项中取三项有十种组合。","why":"Mathematics sharpens the everyday sense by fixing one feature: order is ignored. Permutations count order, combinations do not, and the noun becomes a precise object of counting.","whyCN":"数学通过固定一个特征来锐化日常义：不计顺序。排列计顺序，组合不计，名词遂成为精确的计数对象。"},{"no":"03","title":"A lock's number set","titleCN":"密码锁的号码组合","definition":"the sequence of numbers or symbols that opens a combination lock","definitionCN":"打开密码锁所需的数字或符号序列","example":"He forgot the combination to the safe.","exampleCN":"他忘了保险柜的密码。","why":"Here the joined elements are digits, and the order does matter, which is technically a permutation rather than a combination. Everyday usage ignores the mathematical distinction.","whyCN":"此处结合的元素是数字，而顺序确实重要，技术上属排列而非组合。日常用法不顾这一数学区分。"},{"no":"04","title":"A sequence of moves","titleCN":"连击；动作组合","definition":"a set of movements performed in sequence, especially in sport or martial arts","definitionCN":"按顺序完成的一组动作，尤用于运动或武术","example":"She finished with a combination of jabs and hooks.","exampleCN":"她以直拳与勾拳的连击收尾。","why":"Sport treats the combination as a trained unit: separate moves are linked so smoothly that they read as one action. Practice turns a list into a single response.","whyCN":"运动把组合当作训练单位：分开的动作被连接得如此顺畅，读起来像一个动作。练习把清单变成单一反应。"},{"no":"05","title":"Chemical combination","titleCN":"化合；化合物","definition":"the joining of substances in fixed proportions to form a compound","definitionCN":"物质按固定比例结合成化合物","example":"Water is a combination of hydrogen and oxygen.","exampleCN":"水是氢与氧的化合物。","why":"Chemistry uses the word for a fixed-ratio union that produces a new substance. Unlike a mixture, the parts lose their separate properties, which is a stronger claim than the everyday sense.","whyCN":"化学用该词指产生新物质的定比结合。与混合物不同，各部分失去各自性质，这比日常义的主张更强。"},{"no":"06","title":"A business combine","titleCN":"企业联合；联合体","definition":"an alliance of firms or a large merged enterprise","definitionCN":"多家公司的联盟或大型合并企业","example":"The trust was a combination of several railroads.","exampleCN":"该托拉斯是数条铁路的联合体。","why":"Economic history uses combination for mergers and cartels. The word can sound neutral ('joined firms') or suspicious ('combination in restraint of trade'), depending on who is speaking.","whyCN":"经济史用 combination 指合并与卡特尔。该词可听起来中性（“联合的公司”）或可疑（“限制贸易的联合”），取决于说话者。"},{"no":"07","title":"A chord or note set","titleCN":"（音乐）音的组合","definition":"a set of notes sounded together or in a pattern","definitionCN":"同时或按一定模式发出的一组音","example":"The theme is a combination of two motifs.","exampleCN":"该主题是两个动机的组合。","why":"Music joins the general and structural senses: notes combine into chords, motifs into themes. The combination is heard as a whole before its parts are analysed.","whyCN":"音乐连接总义与结构义：音组合成和弦，动机组合成主题。组合先作为整体被听见，再分析其部分。"},{"no":"08","title":"A set package","titleCN":"套餐；组合套装","definition":"a product or service sold as a bundle of items","definitionCN":"作为一组项目出售的产品或服务","example":"The phone comes with a combination of apps and storage.","exampleCN":"该手机配有应用与存储的组合。","why":"Commerce uses the noun for bundling: items are priced and sold together, often cheaper than apart. The combination is a sales unit, and its logic is margin, not essence.","whyCN":"商业用该名词指打包：项目合价出售，常比单买便宜。组合是销售单位，其逻辑是利润，而非本质。"},{"no":"09","title":"A genetic combination","titleCN":"基因组合","definition":"the particular set of alleles an organism carries","definitionCN":"生物体所携带的特定等位基因组合","example":"The disease depends on a combination of genes.","exampleCN":"该病取决于一组基因的组合。","why":"Genetics extends the word to inheritance: traits arise from many genes acting together. The combination is not designed but assorted, and its effects can be non-additive.","whyCN":"遗传学把词扩展到遗传：性状由多基因共同作用。组合不是设计的，而是配成的，其效应可以是非加和的。"}],"etymology":{"intro":{"en":"Combination is combine plus -ation. Combine comes from Old French combiner, from Late Latin combinare 'to join two by two', built on bini 'two each', from bis 'twice'. The original image is pairing, not general mixing. The -ation noun follows Latin combinatio. The word's history is a widening: from joining in twos to joining anything, and then to technical sets in mathematics, chemistry, and genetics. Note that combo is a 20C clipping of combination, not a separate root.","cn":"combination 是 combine 加 -ation。combine 出自古法语 combiner，源于晚期拉丁 combinare“两两结合”，基于 bini“每两个”，再出自 bis“两次”。原意象是配对，而非泛泛混合。名词 -ation 依拉丁 combinatio。词史是一次拓宽：从两两结合到任意结合，再到数学、化学、遗传学的技术集合。注意 combo 是二十世纪对 combination 的截短，不是另一个词根。"},"items":[{"era":"LATIN","en":"bis means 'twice'; from it comes bini 'two each, in pairs'.","cn":"bis 意为“两次”；由其生出 bini“每两个、成对”。"},{"era":"LATIN","en":"combinare 'to join two by two' is com- 'together' plus bini, so the earliest image is pairing.","cn":"combinare“两两结合”是 com-“一起”加 bini，故最早意象是配对。"},{"era":"LATIN","en":"combinatio is the action noun; English combination continues the -ation pattern of abstract nouns.","cn":"combinatio 是动作名词；英语 combination 延续 -ation 抽象名词模式。"},{"era":"15C","en":"English combination enters in the 15C, first for joining in general and later for organized groups.","cn":"英语 combination 于十五世纪进入，先指一般结合，后指有组织的团体。"},{"era":"17C","en":"Mathematics fixes the technical sense: a selection in which order is irrelevant, as against permutation.","cn":"十七世纪数学固定其技术义：不计顺序的选取，与排列相对。"},{"era":"MODERN","en":"Chemistry, business, music, and genetics each take the noun for their own kind of joining, while combo becomes a casual clipping.","cn":"化学、商业、音乐与遗传学各取该名词指自己的结合方式，同时 combo 成为随意的截短形式。"}]},"similar":{"note":{"en":"The first group is the combine family and its endings; the second is words for joining, which differ in whether the parts remain distinct, merge, or are merely bundled.","cn":"第一组是 combine 词族及词尾；第二组是“结合”类词，差别在于各部分保持区分、融合还是仅被打包。"},"groups":[{"heading":"WORD FAMILY","entries":[{"word":"combine","ipa":"/kəmˈbaɪn/","tag":"verb/noun","definition":"to join together; also a harvester or a business alliance.","definitionCN":"结合；也指联合收割机或企业联盟。"},{"word":"combined","ipa":"/kəmˈbaɪnd/","tag":"adjective","definition":"joined into one.","definitionCN":"合并的；联合的。"},{"word":"combo","ipa":"/ˈkɒmbəʊ/","tag":"noun","definition":"a casual word for a combination, especially in food or gaming.","definitionCN":"组合的口语说法，尤用于餐饮或游戏。"}]},{"heading":"NEAR MEANING","entries":[{"word":"mixture","ipa":"/ˈmɪkstʃə/","tag":"noun","definition":"a combination in which the parts keep their own properties. It contrasts with a compound.","definitionCN":"各部分保持自身性质的结合。与化合物相对。"},{"word":"blend","ipa":"/blend/","tag":"noun","definition":"a combination in which the parts are merged smoothly and lose clear edges.","definitionCN":"各部分平滑融合、失去清晰边界的结合。"},{"word":"union","ipa":"/ˈjuːniən/","tag":"noun","definition":"a joining into a single body, often institutional or political.","definitionCN":"结合成单一整体，常为制度或政治的。"}]}]},"mnemonics":{"normalIntro":{"en":"Real links: bini 'two each', combinare 'join in pairs', the -ation noun, and the later widening to sets and compounds.","cn":"真实联系：bini“每两个”、combinare“成对结合”、-ation 名词，以及后来向集合与化合物的拓宽。"},"normal":[{"en":"Combinare is 'join two by two'. The word began as pairing, then learned to join any number.","cn":"combinare 是“两两结合”。词始于配对，后来学会结合任意数量。"},{"en":"bini 'two each' is still visible in binary: both words come from the same 'two' family.","cn":"bini“每两个”仍见于 binary：两词出自同一“二”的家族。"},{"en":"A combination lock is really a permutation, because order matters; everyday speech is looser than mathematics.","cn":"密码锁其实是排列，因为顺序重要；日常语比数学松。"},{"en":"Chemical combination makes a new substance; a mixture does not. The stronger claim hides in the same noun.","cn":"化合产生新物质；混合物不产生。更强的主张藏在同一名词里。"},{"en":"'A winning combination' is a bundle that works; 'a combination in restraint of trade' is a bundle that is suspect.","cn":"a winning combination 是有效的搭配；a combination in restraint of trade 是可疑的联合。"}],"abstract":[{"en":"A combination is an arrangement, and every arrangement has a rule: order, ratio, or purpose. The noun alone never says which.","cn":"组合是一种安排，而每种安排都有规则：顺序、比例或目的。单看名词永远不知道是哪一种。"},{"en":"Combining is creative when the parts keep their difference and produce a third thing neither could be alone.","cn":"当各部分保持差异并产生任何一方单独无法产生的第三者时，结合才是创造性的。"},{"en":"The same word covers a chord and a cartel, because both are sets whose power lies in the relation, not the members.","cn":"同一个词覆盖和弦与卡特尔，因为两者都是力量在关系而非成员中的集合。"}]},"examples":[{"en":"The vaccine is a combination of two proteins.","cn":"该疫苗是两种蛋白的组合。"},{"en":"Her success was a combination of talent and luck.","cn":"她的成功是天赋与运气的结合。"},{"en":"A combination lock needs the right order, not just the right numbers.","cn":"密码锁需要正确顺序，不只是正确数字。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“康比内申”——把两样东西“并”到一起，像双线拧成一股 → combination 组合","word":"combination"},"root":"combine（古法语 combiner ← 晚期拉丁 combinare“两两结合”= com-“一起”+ bini“每两个”，bini 出自 bis“两次”）+ -ation。","sensesIntro":{"en":"Nine senses of combination: a joining, a mathematical selection, a lock's code, a sequence of moves, a chemical compound, a business alliance, a musical set, a product bundle, and a genetic set. All are arrangements whose meaning depends on the rule of arrangement.","cn":"combination 的九个义项：结合、数学选取、密码、动作连击、化合物、企业联合、音乐音组、产品套餐、基因组合。它们都是安排，意义取决于安排规则。"},"semanticMap":{"core":{"en":"CORE IMAGE: two differently coloured threads crossed in the palm and twisted into one stronger cord.","cn":"核心意象：两股不同颜色的线在掌心交叉，拧成一根更结实的绳。"},"chain":["TAKE TWO THINGS","PUT THEM TOGETHER","FIX A PROPORTION OR ORDER","FORM A NEW SET","GIVE IT A USE","NAME THE WHOLE"],"branches":[{"senses":"S1 · S2","en":"THE ARRANGEMENT: everyday joining and mathematical selection differ only in whether order counts.","cn":"安排：日常结合与数学选取只差在是否计顺序。"},{"senses":"S3 · S4 · S7","en":"THE SEQUENCE: lock codes, fighting moves, and musical motifs all depend on ordered succession.","cn":"序列：密码、连击与音乐动机都依赖有序连续。"},{"senses":"S5","en":"THE SUBSTANCE: chemical combination makes a compound, a stronger union than mixture.","cn":"物质：化合产生化合物，比混合物更强的结合。"},{"senses":"S6 · S8","en":"THE INSTITUTION AND THE BUNDLE: firms and products are joined for advantage or sale.","cn":"机构与套餐：公司与产品为利益或销售而结合。"},{"senses":"S9","en":"THE INHERITANCE: genes combine without design, and their effects may not add up.","cn":"遗传：基因无设计地组合，其效应未必相加。"}]},"affixes":{"intro":{"en":"Combination is combine + -ation. Combine is from Late Latin combinare, com- plus bini 'two each'. The family includes combined, combinational, combinatorial, and the clipping combo. The base bini also gives binary and bis.","cn":"combination 是 combine 加 -ation。combine 出自晚期拉丁 combinare（com- 加 bini“每两个”）。词族含 combined、combinational、combinatorial 与截短形式 combo。词基 bini 还给出 binary 与 bis。"},"latinIntro":{"en":"Late Latin combinare 'join two by two' is built on bini 'two each'. Its noun combinatio passes through French into English combination. The stem also yields combinatory and combinatorial in modern technical English.","cn":"晚期拉丁 combinare“两两结合”基于 bini“每两个”。其名词 combinatio 经法语进入英语 combination。词干在现代技术英语中还给出 combinatory 与 combinatorial。"},"items":[{"word":"combines","structure":"combine + -s (3sg)","meaning":"joins together","meaningCN":"结合（三单）","example":"the recipe combines spices","exampleCN":"该配方混合香料"},{"word":"combined","structure":"combine + -ed (past/participle)","meaning":"joined into one","meaningCN":"合并的","example":"combined efforts","exampleCN":"共同努力"},{"word":"combining","structure":"combine + -ing (participle)","meaning":"the act of joining","meaningCN":"结合中的","example":"combining two methods","exampleCN":"结合两种方法"},{"word":"combination","structure":"combine + -ation (noun)","meaning":"a set of joined things","meaningCN":"组合；结合（-ation 名词）","example":"a combination of factors","exampleCN":"多种因素的组合"},{"word":"combinational","structure":"combination + -al (adjective)","meaning":"relating to combinations","meaningCN":"组合的（-al 形容词）","example":"combinational logic","exampleCN":"组合逻辑"},{"word":"combinatorial","structure":"combination + -orial (adjective)","meaning":"relating to counting arrangements","meaningCN":"组合数学的（-orial 形容词）","example":"a combinatorial problem","exampleCN":"组合问题"},{"word":"combo","structure":"clipping of combination","meaning":"a casual combination, often a meal or move set","meaningCN":"组合；套餐（截短）","example":"a combo meal","exampleCN":"套餐"},{"word":"binary","structure":"bini + -ary (same base)","meaning":"using two states","meaningCN":"二进制的；二元的（同词基）","example":"binary code","exampleCN":"二进制代码"},{"word":"bis","structure":"Latin bis (base)","meaning":"twice","meaningCN":"两次（词基）","example":"bis- as a prefix","exampleCN":"bis- 前缀"}],"latinEntries":[{"word":"bis","structure":"Latin adverb","meaning":"twice","meaningCN":"两次"},{"word":"bini","structure":"bis + -ni (distributive)","meaning":"two each, in pairs","meaningCN":"每两个；成对"},{"word":"combinare","structure":"com- + bini","meaning":"to join two by two","meaningCN":"两两结合"},{"word":"combinatio","structure":"combinare + -tio","meaning":"a joining together","meaningCN":"结合；组合"}]}},{"word":"comparable","ipa_uk":"/ˈkɒmpərəbl/","ipa_us":"/ˈkɑːmpərəbl/","definition_zh":"可比较的；可比的；类似的；相当的；比得上的；同等的；（统计）口径可比的","definition_en":"able to be compared with something else; similar enough in amount or quality to be judged together; equivalent","core_image":"两把尺子并排放好，刻度对齐，才能量出谁长谁短","scene":"两份数据的采集方法不同。The two datasets were collected in different ways, so strictly they are not comparable and cannot share one chart.","sceneCN":"这里 comparable 是「（数据/口径）可比的、可比较的」（第 3 个义项：因方法或标准相同而能被公正比较）；句意：两份数据的采集方法不同，严格说并不可比，不能画在同一张图上。图中可辨识物件：两把刻度尺、两份数据表、折线图、放大镜、校准砝码。","pos":[{"tag":"adj.","zh":"可比较的；可比的；类似的；相当的"}],"collocations":[{"phrase":"comparable data","zh":"可比数据"},{"phrase":"comparable to","zh":"与…相当/可比"},{"phrase":"comparable with","zh":"可与…相比"},{"phrase":"at a comparable price","zh":"以相当的价格"},{"phrase":"comparable worth","zh":"可比价值（同值同酬）"},{"phrase":"broadly comparable","zh":"大体相当"}],"forms":[{"label":"副词","form":"comparably"},{"label":"名词","form":"comparability"},{"label":"动词","form":"compare"},{"label":"形容词（比较的）","form":"comparative"}],"derivatives":[{"word":"comparability","pos":"n.","zh":"可比性"},{"word":"comparably","pos":"adv.","zh":"可比较地；类似地"},{"word":"compare","pos":"v.","zh":"比较；比作"},{"word":"comparison","pos":"n.","zh":"比较；对照"},{"word":"comparative","pos":"adj.","zh":"比较的；相对的"}],"senses":[{"no":"01","title":"Able to be compared","titleCN":"可比较的","definition":"able to be examined alongside something else","definitionCN":"能与另一事物并置考察的","example":"The two poems are comparable in form.","exampleCN":"这两首诗在形式上有可比性。","why":"This is the literal -able sense: the things can be put side by side. It makes no claim yet about whether they turn out equal; it only opens the possibility of comparison.","whyCN":"这是 -able 的字面义：两物可以并排放。它尚未断言是否相等，只打开比较的可能性。"},{"no":"02","title":"Similar in size or quality","titleCN":"类似的；相当的","definition":"similar enough in size, amount, or quality to be regarded as alike","definitionCN":"在大小、数量或品质上相似到可视为同类","example":"Their incomes are comparable.","exampleCN":"他们的收入相当。","why":"Here the possibility becomes a judgement: comparison finds them close. The word is deliberately imprecise, because it says 'close enough to compare' rather than 'identical'.","whyCN":"此处可能性变成判断：比较发现它们接近。该词刻意不精确，因为它说的是“接近到可比较”，而非“完全相同”。"},{"no":"03","title":"Methodologically comparable","titleCN":"（统计）口径可比的","definition":"measured or defined in the same way, so that comparison is valid","definitionCN":"以相同方式测量或定义，因而比较有效","example":"Only comparable figures were included in the meta-analysis.","exampleCN":"元分析只纳入口径可比的数据。","why":"Statistics turns the adjective into a condition of validity. If definitions differ, the numbers are not comparable, and the comparison itself is a category error however similar the digits look.","whyCN":"统计把该形容词变成有效性条件。若定义不同，数字就不可比；无论数字看起来多相似，比较本身都是范畴错误。"},{"no":"04","title":"Comparable to a standard","titleCN":"可对照的；可参照的","definition":"able to be measured against a known standard or example","definitionCN":"能与已知标准或范例对照衡量的","example":"The results are comparable to last year's baseline.","exampleCN":"结果可与去年基线对照。","why":"Here the second term is a standard, not a peer. The word licenses a measurement, and 'comparable to' is the usual frame: the new case is placed against an established one.","whyCN":"此处第二项是标准，而非同侪。该词授权一次测量，常用框架是 comparable to：新案例被放到既定案例旁。"},{"no":"05","title":"Good enough to match","titleCN":"比得上的","definition":"of a quality that can stand comparison with the best","definitionCN":"质量上可与最好者相比","example":"Her voice is comparable to the great sopranos.","exampleCN":"她的嗓音可与伟大女高音相比。","why":"This is evaluative and often complimentary: the thing is not merely similar but worthy of the same league. The comparison implies respect rather than equality.","whyCN":"此义带评价且常为称赞：该物不仅相似，还配得上同一档次。比较暗示尊敬，而非完全相等。"},{"no":"06","title":"Comparable worth","titleCN":"可比价值（同值同酬）","definition":"the principle that different jobs of equal value should receive equal pay","definitionCN":"不同但价值相等的工作应获同等报酬的原则","example":"Comparable worth seeks pay equity across job categories.","exampleCN":"可比价值原则寻求跨岗位类别的薪酬公平。","why":"Labour policy uses the adjective in a fixed phrase. 'Comparable' here means equal in assessed value, not equal in task, which is precisely the disputed claim.","whyCN":"劳动政策把该形容词用于固定短语。此处 comparable 指评估价值相等，而非任务相同，而这正是有争议的主张。"},{"no":"07","title":"Comparable groups (research)","titleCN":"可比较的实验组","definition":"groups similar in relevant variables so that a fair comparison is possible","definitionCN":"在相关变量上相似、可作公平比较的组","example":"The trial used comparable control and treatment groups.","exampleCN":"该试验使用了可比的对照与治疗组。","why":"Experimental design makes comparability a property of groups. If the groups differ in age or severity, the treatment effect cannot be isolated; the word names a condition of causal inference.","whyCN":"实验设计使可比性成为组的属性。若各组在年龄或严重程度上不同，疗效无法被隔离；该词命名因果推论的一项条件。"},{"no":"08","title":"Comparable prices","titleCN":"（经济）可比价格","definition":"prices adjusted to a common base year so that real changes can be seen","definitionCN":"调整到共同基年以便看出实际变化的价格","example":"Growth is measured in comparable prices.","exampleCN":"增长以可比价格衡量。","why":"Economics adjusts nominal figures to remove inflation. 'Comparable' means the units have been made to speak the same language, not that the goods are similar.","whyCN":"经济学调整名义数字以去除通胀。comparable 指单位被调成同一语言，而非商品相似。"},{"no":"09","title":"Comparable cases (law)","titleCN":"可类比的判例","definition":"precedents similar enough in material facts to justify the same rule","definitionCN":"在实质事实上相似到可适用同一规则的先例","example":"The court found no comparable case.","exampleCN":"法院未找到可类比的判例。","why":"Legal reasoning runs on analogy: a new case is comparable if its material facts match. The adjective carries a heavy burden, because the choice of comparable cases often decides the outcome.","whyCN":"法律推理依赖类比：新案若实质事实相符即为可比。该形容词负担很重，因为选择哪些可比案例常决定结果。"}],"etymology":{"intro":{"en":"Comparable is compare plus -able. Compare comes from Latin comparare 'to pair together, match', from com- 'together' plus par 'equal'. The -able suffix is Latin -abilis, 'able to be'. So the literal sense is 'able to be paired'. The same par gives parity, peer, pair, and nonpareil; comparison comes from Latin comparatio. Note that comparable and comparative are different: -able says 'can be compared or is close enough', -ive says 'of or involving comparison'.","cn":"comparable 是 compare 加 -able。compare 出自拉丁 comparare“配对、匹敌”，由 com-“一起”加 par“相等”构成。-able 后缀是拉丁 -abilis“能被…的”。故字面义是“能被配对”。同一 par 还给出 parity、peer、pair、nonpareil；comparison 出自拉丁 comparatio。注意 comparable 与 comparative 不同：-able 说“可比或接近到可比”，-ive 说“比较的、涉及比较的”。"},"items":[{"era":"LATIN","en":"par means 'equal'; it survives in English parity and peer, and in the phrase on a par with.","cn":"par 意为“相等”；仍存于英语 parity、peer 及短语 on a par with。"},{"era":"LATIN","en":"comparare is com- 'together' plus par 'equal': to put things together as equals, hence to compare.","cn":"comparare 是 com-“一起”加 par“相等”：把事物作为对等者放在一起，故为比较。"},{"era":"LATIN","en":"comparabilis 'able to be compared' adds -abilis to the stem; English -able continues this suffix.","cn":"comparabilis“可比较的”在词干上加 -abilis；英语 -able 延续该后缀。"},{"era":"15C","en":"English comparable appears in the 15C, first in the plain sense 'able to be compared'.","cn":"英语 comparable 于十五世纪出现，初为“可被比较”的朴素义。"},{"era":"17C","en":"The evaluative sense 'similar enough to be judged together' becomes common in science and commerce.","cn":"十七世纪，“相似到可同判”的评价义在科学与商业中普及。"},{"era":"MODERN","en":"Statistics and economics turn comparability into a technical requirement: same definitions, same base year, same variables.","cn":"现代统计与经济学把可比性变成技术要求：同定义、同基年、同变量。"}]},"similar":{"note":{"en":"The first group is the compare family, where -able and -ive pull apart; the second is adjectives of similarity, which differ in precision and in whether equality is claimed.","cn":"第一组是 compare 词族，-able 与 -ive 在此分开；第二组是相似形容词，精确度与是否主张相等不同。"},"groups":[{"heading":"WORD FAMILY","entries":[{"word":"comparability","ipa":"/ˌkɒmpərəˈbɪləti/","tag":"noun","definition":"the quality of being comparable; in statistics, the validity of a comparison.","definitionCN":"可比性；统计上指比较的有效性。"},{"word":"comparably","ipa":"/ˈkɒmpərəbli/","tag":"adverb","definition":"in a similar or equal measure.","definitionCN":"类似地；相当地。"},{"word":"comparative","ipa":"/kəmˈpærətɪv/","tag":"adjective","definition":"involving comparison; in grammar, the form marking 'more'.","definitionCN":"比较的；语法中表“更”的形式。"}]},{"heading":"NEAR MEANING","entries":[{"word":"similar","ipa":"/ˈsɪmələ/","tag":"adjective","definition":"alike in appearance or nature, without any claim about measurement.","definitionCN":"外观或性质相似，不涉及测量主张。"},{"word":"equivalent","ipa":"/ɪˈkwɪvələnt/","tag":"adjective","definition":"equal in value, meaning, or effect. It is stronger and more exact than comparable.","definitionCN":"在价值、意义或效果上相等。比 comparable 更强、更精确。"},{"word":"analogous","ipa":"/əˈnæləɡəs/","tag":"adjective","definition":"similar in structure or function, often across different domains. It licenses an analogy, not a measurement.","definitionCN":"在结构或功能上相似，常跨领域。它授权类比，而非测量。"}]}]},"mnemonics":{"normalIntro":{"en":"Real links: par 'equal', comparare 'pair as equals', the -able suffix, and the split between comparable and comparative.","cn":"真实联系：par“相等”、comparare“作为对等者配对”、-able 后缀，以及 comparable 与 comparative 的分工。"},"normal":[{"en":"Comparare is 'put together as equals'. Comparable is 'able to be put together' — the -able does the work.","cn":"comparare 是“作为对等者放在一起”。comparable 是“能被放在一起”——出活的是 -able。"},{"en":"par 'equal' is visible in parity, peer, and 'on a par with'. Equal things are the ones we can compare fairly.","cn":"par“相等”见于 parity、peer 与 on a par with。相等之物才是能公平比较之物。"},{"en":"Comparable says 'can be compared or close enough'; comparative says 'about comparing'. One letter changes the job.","cn":"comparable 说“可比或够接近”；comparative 说“关于比较”。一个字母换了工作。"},{"en":"In statistics, comparable means same definitions and same base year, not similar-looking numbers.","cn":"统计中 comparable 指同定义、同基年，而非数字看起来相似。"},{"en":"Comparable worth is not 'same work'; it is 'different work judged equal in value', which is why it is argued over.","cn":"comparable worth 不是“同样的工作”，而是“不同工作被判定价值相等”，故有争议。"}],"abstract":[{"en":"Comparability is a precondition of judgement: until units and definitions align, comparison produces only noise.","cn":"可比性是判断的前提：在单位与定义对齐之前，比较只产生噪声。"},{"en":"The adjective hides a decision about which differences to ignore; that decision is where bias enters.","cn":"该形容词藏着一个“忽略哪些差异”的决定；偏见由此进入。"},{"en":"To call two things comparable is to grant them a shared scale, and scales are never neutral.","cn":"称两物可比，就是授予它们一把共同的尺，而尺从不中立。"}]},"examples":[{"en":"The two cities have comparable populations.","cn":"这两座城市人口相当。"},{"en":"These figures are not comparable because the methods differ.","cn":"这些数字不可比，因为方法不同。"},{"en":"Her performance is comparable to the best in the field.","cn":"她的表现可与该领域最好者相比。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“康帕拉伯”——两样东西能“compare”得起来 → comparable 可比较的","word":"comparable"},"root":"compare（拉丁 comparare“配对、匹敌”= com-“一起”+ par“相等”）+ -able（拉丁 -abilis“能…的”）。","sensesIntro":{"en":"Nine senses of comparable: able to be compared, similar in amount, methodologically valid, measurable against a standard, good enough to match, equal in assessed worth, similar as research groups, adjusted to a common price base, and analogous as legal precedents.","cn":"comparable 的九个义项：可比较、数量相近、口径可比、可对照标准、比得上、评估价值相等、实验组可比、可比价格、判例可类比。"},"semanticMap":{"core":{"en":"CORE IMAGE: two rulers laid side by side with their zero marks aligned.","cn":"核心意象：两把尺子并排，零刻度对齐。"},"chain":["PUT THEM SIDE BY SIDE","ALIGN THE UNITS","READ THE DIFFERENCE","JUDGE THEM CLOSE","GRANT THE SAME SCALE","LET THE COMPARISON COUNT"],"branches":[{"senses":"S1","en":"THE POSSIBILITY: the -able sense opens comparison without judging it.","cn":"可能：-able 义打开比较，尚未评判。"},{"senses":"S2 · S5","en":"THE JUDGEMENT: similar enough, or good enough to stand in the same league.","cn":"判断：足够相似，或好到可入同一档次。"},{"senses":"S3 · S7 · S8","en":"THE METHOD: definitions, groups, and base years must match for comparison to be valid.","cn":"方法：定义、分组与基年必须一致，比较才有效。"},{"senses":"S4","en":"THE STANDARD: comparable to a baseline places a new case against an established one.","cn":"标准：comparable to 基线，把新案例放到既定案例旁。"},{"senses":"S6 · S9","en":"THE INSTITUTION: comparable worth and comparable cases turn the word into a legal or policy claim.","cn":"制度：可比价值与可比判例把该词变成法律或政策主张。"}]},"affixes":{"intro":{"en":"Comparable is compare + -able. Compare is Latin comparare, com- plus par 'equal'. The family includes comparability, comparably, comparison, and comparative; the same par gives parity, peer, and pair.","cn":"comparable 是 compare 加 -able。compare 是拉丁 comparare（com- 加 par“相等”）。词族含 comparability、comparably、comparison、comparative；同一 par 给出 parity、peer、pair。"},"latinIntro":{"en":"Latin par 'equal' forms comparare 'match, compare', whose stem takes -abilis to make comparabilis 'able to be compared'. English also builds comparison from comparatio and comparative from comparativus, so -able and -ive sit on one base with different jobs.","cn":"拉丁 par“相等”构成 comparare“匹敌、比较”，其词干加 -abilis 成 comparabilis“可比较的”。英语还由 comparatio 造 comparison，由 comparativus 造 comparative，故 -able 与 -ive 在同一词基上分工不同。"},"items":[{"word":"compares","structure":"compare + -s (3sg)","meaning":"sets side by side","meaningCN":"比较（三单）","example":"she compares the prices","exampleCN":"她比较价格"},{"word":"compared","structure":"compare + -ed (past/participle)","meaning":"set against another","meaningCN":"比较了","example":"compared with last year","exampleCN":"与去年相比"},{"word":"comparing","structure":"compare + -ing (participle)","meaning":"in the act of comparison","meaningCN":"比较中的","example":"comparing two texts","exampleCN":"比较两份文本"},{"word":"comparison","structure":"compare + -ison (noun)","meaning":"the act of comparing","meaningCN":"比较（-ison 名词）","example":"a fair comparison","exampleCN":"公平比较"},{"word":"comparable","structure":"compare + -able (adjective)","meaning":"able to be compared","meaningCN":"可比较的（-able 形容词）","example":"comparable data","exampleCN":"可比数据"},{"word":"comparably","structure":"comparable + -ly (adverb)","meaning":"in a comparable way","meaningCN":"可比地；类似地（-ly 副词）","example":"comparably priced","exampleCN":"价格相当"},{"word":"comparative","structure":"compare + -ative (adjective)","meaning":"involving comparison","meaningCN":"比较的（-ative 形容词）","example":"a comparative study","exampleCN":"比较研究"},{"word":"comparatively","structure":"comparative + -ly (adverb)","meaning":"by comparison; relatively","meaningCN":"相对地（-ly 副词）","example":"comparatively cheap","exampleCN":"相对便宜"},{"word":"parity","structure":"par + -ity (same base)","meaning":"equality of status or amount","meaningCN":"平等；平价（同词基）","example":"pay parity","exampleCN":"薪酬平等"}],"latinEntries":[{"word":"par","structure":"Latin adjective/noun","meaning":"equal, a match","meaningCN":"相等的；对等者"},{"word":"comparare","structure":"com- + par","meaning":"to pair, match, compare","meaningCN":"配对；匹敌；比较"},{"word":"comparabilis","structure":"comparare + -abilis","meaning":"able to be compared","meaningCN":"可比较的"},{"word":"comparatio","structure":"comparare + -tio","meaning":"a comparing, comparison","meaningCN":"比较"}]}},{"word":"comparatively","ipa_uk":"/kəmˈpærətɪvli/","ipa_us":"/kəmˈpærətɪvli/","definition_zh":"相对地；比较而言；通过比较（方法）；较为；相对数量上；相对价格上","definition_en":"when judged by comparison with something else; relatively; by means of comparison","core_image":"两个人站上同一块背景板，标尺一拉，才知道谁其实更高","scene":"这里冬天温和，可比起南方，仍然冷得让人缩手。Winters here are comparatively mild, though next to the south they still make your hands curl.","sceneCN":"这里 comparatively 是「相对地、比较而言」（第 1 个义项：与别的情形对照后才成立的程度）；句意：这里冬天相对温和，但比起南方仍冷得让人缩手。图中可辨识物件：温度计、两地对照照片、标尺、围巾、地图。","pos":[{"tag":"adv.","zh":"相对地；比较而言；用比较方法"}],"collocations":[{"phrase":"comparatively speaking","zh":"相对来说"},{"phrase":"comparatively cheap","zh":"相对便宜"},{"phrase":"comparatively few","zh":"相对较少"},{"phrase":"comparatively recently","zh":"相对较近"},{"phrase":"comparatively large","zh":"相对较大"},{"phrase":"comparatively well","zh":"相对较好"}],"forms":[{"label":"形容词","form":"comparative"},{"label":"动词","form":"compare"},{"label":"名词","form":"comparison"},{"label":"同根形容词","form":"comparable"}],"derivatives":[{"word":"comparative","pos":"adj./n.","zh":"比较的；比较级"},{"word":"compare","pos":"v.","zh":"比较"},{"word":"comparison","pos":"n.","zh":"比较"},{"word":"comparably","pos":"adv.","zh":"可比较地；同样地"}],"senses":[{"no":"01","title":"Relatively","titleCN":"相对地","definition":"in a way that is true only when measured against something else","definitionCN":"只有与别物对照才成立的程度","example":"The region is comparatively dry.","exampleCN":"该地区相对干燥。","why":"This is the core use: a statement is true not absolutely but against a baseline. The adverb always points to an unspoken comparison, and the hearer must supply it.","whyCN":"这是核心用法：陈述不是绝对成立，而是相对于某基线成立。副词总指向一个未说出的比较，听者须自行补上。"},{"no":"02","title":"Comparatively speaking","titleCN":"比较而言","definition":"as a discourse marker introducing a comparison","definitionCN":"作为引入比较的话语标记","example":"Comparatively speaking, the second plan is safer.","exampleCN":"比较而言，第二个方案更安全。","why":"Here the adverb manages the conversation: it warns that the next claim is scaled, not absolute. It softens commitment and often invites the hearer to agree on the frame.","whyCN":"此处副词管理对话：它提醒接下来的主张是相对尺度，而非绝对。它软化承诺，且常邀听者认同该框架。"},{"no":"03","title":"By comparative method","titleCN":"用比较方法","definition":"by studying two or more cases side by side in order to find differences and patterns","definitionCN":"并置研究两个或更多案例以找差异与模式","example":"The two languages were studied comparatively.","exampleCN":"这两种语言被比较地研究。","why":"This is methodological: comparison is the instrument, not a hedge. Linguistics, anatomy, and sociology all use the adverb to name a technique that produces evidence.","whyCN":"这是方法论的：比较是工具，不是模糊限制。语言学、解剖学与社会学都用该副词命名一种产生证据的技术。"},{"no":"04","title":"Somewhat; fairly","titleCN":"较为；相对地（修饰形容词）","definition":"to a moderate degree when seen against the usual level","definitionCN":"相对于通常水平达到中等程度","example":"The exam was comparatively easy.","exampleCN":"这次考试较为容易。","why":"The adverb scales an adjective: easy compared with what? Usually with other exams or with expectations. It is a hedge that still makes a claim.","whyCN":"副词给形容词定标：相对于什么算容易？通常是相对于其他考试或预期。它仍是作出主张的模糊限制。"},{"no":"05","title":"In relatively small number","titleCN":"相对数量少","definition":"in a smaller number than the relevant alternative","definitionCN":"比相关对照在数量上更少","example":"Comparatively few students chose the course.","exampleCN":"相对较少的学生选了这门课。","why":"Quantity is where the missing baseline matters most. 'Few' alone is vague; 'comparatively few' says the number is low for this class of case, and the class is the hidden comparison.","whyCN":"数量处最见缺失基线的重要性。单说 few 模糊；comparatively few 说该数目对此类情形偏低，而“此类”就是隐藏的比较项。"},{"no":"06","title":"At a relatively low cost","titleCN":"相对价格低","definition":"at a lower price than the usual or alternative option","definitionCN":"比通常或替代选择价格更低","example":"Housing is comparatively cheap here.","exampleCN":"这里住房相对便宜。","why":"Economic comparisons are usually local and time-bound: cheap compared with the capital, or with last year. The adverb does not say cheap in itself, and prices are never cheap in themselves.","whyCN":"经济比较通常受地点与时间限制：比首都便宜，或比去年便宜。副词不说本身便宜，而价格从不本身便宜。"},{"no":"07","title":"Of relatively greater importance","titleCN":"相对更重要","definition":"more important than other items in the same comparison","definitionCN":"在同一比较中比其他项更重要","example":"This point is comparatively important.","exampleCN":"这一点相对重要。","why":"Evaluation uses the adverb to rank without absolute claims. It can also weaken a point by suggesting it matters only next to something lesser, which is why tone matters.","whyCN":"评价用该副词排序而不作绝对主张。它也可能通过暗示“只是比更小者重要”来削弱论点，故语气重要。"},{"no":"08","title":"Relatively recently","titleCN":"相对较近（时间）","definition":"in a period closer to now than the comparison period","definitionCN":"比对照时段更接近现在","example":"The technique was developed comparatively recently.","exampleCN":"该技术是相对较近才发展起来的。","why":"Time comparisons need an anchor: recent compared with the field's history, not with last week. The adverb makes the anchor implicit, and confusion arises when hearers pick a different one.","whyCN":"时间比较需要锚点：相对于该领域历史算近，而非相对于上周。副词把锚点隐含，听者选了不同锚点时便生混淆。"},{"no":"09","title":"In relative proportion","titleCN":"相对比例上","definition":"as a share that is larger or smaller than the comparison share","definitionCN":"作为比对照份额更大或更小的比例","example":"A comparatively large share of the budget goes to health.","exampleCN":"预算中相对较大的一份用于卫生。","why":"Proportional use adds a denominator. The share may be large while the total is small; the adverb compares ratios, not raw amounts, and that distinction is often the whole argument.","whyCN":"比例用法加了分母。份额可以很大而总额很小；副词比较的是比率而非绝对量，这一区分常是争论的全部。"}],"etymology":{"intro":{"en":"Comparatively is comparative plus -ly. Comparative comes from Latin comparativus, from comparare 'to pair, match', com- plus par 'equal'. The -ive suffix is Latin -ivus; -ly is the English adverb ending. The word's meaning is not 'in a comparing manner' only but 'when compared', a use that grew in the 17C alongside scientific and statistical writing. Note the contrast with comparably: comparably means 'in a similar or equal measure', while comparatively means 'relatively, by comparison'.","cn":"comparatively 是 comparative 加 -ly。comparative 出自拉丁 comparativus，源于 comparare“配对、匹敌”（com- 加 par“相等”）。-ive 是拉丁 -ivus；-ly 是英语副词后缀。其义不只是“以比较的方式”，更是“经比较看来”，这一用法随十七世纪科学与统计写作而增长。注意与 comparably 的对照：comparably 指“以相似或相等的程度”，comparatively 指“相对地、经比较”。"},"items":[{"era":"LATIN","en":"par 'equal' underlies comparare 'to pair or match', the source of the whole family.","cn":"par“相等”是 comparare“配对、匹敌”的词基，也是整族的来源。"},{"era":"LATIN","en":"comparativus 'of comparison' adds -ivus to the stem; English keeps it as -ive.","cn":"comparativus“比较的”在词干上加 -ivus；英语保留为 -ive。"},{"era":"GRAMMAR","en":"The grammatical 'comparative degree' (bigger, more careful) is named from the same adjective in the 16C.","cn":"语法上的“比较级”（bigger、more careful）在十六世纪由同一形容词得名。"},{"era":"17C","en":"The adverb comparatively develops the sense 'when compared, relatively', especially in science and travel writing.","cn":"十七世纪副词 comparatively 发展出“经比较看来、相对地”义，尤见于科学与游记写作。"},{"era":"19C","en":"Statistics and economics make it a standard hedge for figures that need a baseline.","cn":"十九世纪统计与经济学使它成为需要基线的数字的标准限定语。"},{"era":"MODERN","en":"Modern usage splits it from comparably: comparatively = relatively; comparably = in a similar measure.","cn":"现代用法把它与 comparably 分开：comparatively 表相对；comparably 表相似程度。"}]},"similar":{"note":{"en":"The first group is the compare family with its -ive and -able branches; the second is adverbs of degree and relation, which differ in whether they hedge, rank, or measure.","cn":"第一组是 compare 词族的 -ive 与 -able 两支；第二组是程度与关系副词，差别在于模糊限制、排序还是测量。"},"groups":[{"heading":"WORD FAMILY","entries":[{"word":"comparative","ipa":"/kəmˈpærətɪv/","tag":"adjective","definition":"involving comparison; the grammar form marking 'more'.","definitionCN":"比较的；语法中表“更”的形式。"},{"word":"comparably","ipa":"/ˈkɒmpərəbli/","tag":"adverb","definition":"in a similar or equal measure.","definitionCN":"以相似或相等的程度。"},{"word":"comparison","ipa":"/kəmˈpærɪsn/","tag":"noun","definition":"the act of comparing two or more things.","definitionCN":"比较两个或更多事物的行为。"}]},{"heading":"NEAR MEANING","entries":[{"word":"relatively","ipa":"/ˈrelətɪvli/","tag":"adverb","definition":"in relation to something else; comparatively. It is the closest synonym and often interchangeable.","definitionCN":"相对于他物；比较地。最近的同义词，常可互换。"},{"word":"somewhat","ipa":"/ˈsʌmwɒt/","tag":"adverb","definition":"to a moderate degree, without saying what it is compared with.","definitionCN":"达到中等程度，不说与何物比较。"},{"word":"fairly","ipa":"/ˈfeəli/","tag":"adverb","definition":"to a moderate degree, often with approval. It scales but does not point to a baseline.","definitionCN":"达到中等程度，常带赞许。它定标但不指向基线。"}]}]},"mnemonics":{"normalIntro":{"en":"Real links: par 'equal', comparare 'match', the -ive adjective and -ly adverb, and the modern split from comparably.","cn":"真实联系：par“相等”、comparare“匹敌”、-ive 形容词与 -ly 副词，以及现代与 comparably 的分工。"},"normal":[{"en":"Comparative is the adjective of comparison; add -ly and it becomes 'by comparison', not 'equally'.","cn":"comparative 是比较的形容词；加 -ly 后是“经比较”，不是“相等地”。"},{"en":"Comparatively cheap means cheap next to something; comparably cheap means cheap to a similar degree. One letter, two baselines.","cn":"comparatively cheap 指相对某物便宜；comparably cheap 指便宜到相似程度。一个字母，两种基线。"},{"en":"The adverb always hides a 'than what?'. If the hearer cannot fill it, the sentence is incomplete.","cn":"该副词总藏着“比什么？”。听者填不上，句子就不完整。"},{"en":"In grammar the 'comparative degree' is the -er/more form; the same adjective names both the grammar and the method.","cn":"语法中“比较级”是 -er/more 形式；同一形容词既命名语法，也命名方法。"},{"en":"par 'equal' is still alive in parity and peer; comparison is the act of putting equals side by side.","cn":"par“相等”仍活在 parity 与 peer；比较就是把对等者并排放。"}],"abstract":[{"en":"Relativity in language is a hedge and a claim at once: it lowers the volume but still asserts a difference.","cn":"语言中的相对性同时是模糊限制与主张：它降低音量，却仍断言差异。"},{"en":"The missing baseline is where speakers disagree; 'comparatively' hides a choice that can be contested.","cn":"缺失的基线正是说话者分歧之处；comparatively 藏着一个可被质疑的选择。"},{"en":"Comparison creates a scale, and a scale turns difference into a judgement of more or less.","cn":"比较创造尺度，而尺度把差异变成多少的判断。"}]},"examples":[{"en":"The winters here are comparatively mild.","cn":"这里的冬天相对温和。"},{"en":"Comparatively speaking, the risk is small.","cn":"相对来说，风险很小。"},{"en":"Comparatively few firms survived the crisis.","cn":"相对较少的企业挺过了危机。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“康帕拉提夫利”——先 compare 一下，再说话 → comparatively 相对地","word":"comparatively"},"root":"comparative（拉丁 comparativus ← comparare“配对、匹敌”= com-“一起”+ par“相等”）+ -ly。","sensesIntro":{"en":"Nine senses of comparatively: relatively, as a discourse marker, by comparative method, somewhat, in small number, at low cost, of greater importance, recently, and in relative proportion. Every one of them hides a baseline that the hearer must supply.","cn":"comparatively 的九个义项：相对地、作为话语标记、用比较方法、较为、数量少、价格低、更重要、时间较近、比例上。每一个都藏着听者须补上的基线。"},"semanticMap":{"core":{"en":"CORE IMAGE: two figures standing against one measured backdrop so that a difference can be read.","cn":"核心意象：两个人站在同一块有刻度的背景板前，差异才可读出。"},"chain":["NAME A BASELINE","PLACE TWO CASES ON IT","READ THE DIFFERENCE","SCALE THE CLAIM DOWN","RANK OR MEASURE","LEAVE THE BASELINE IMPLICIT"],"branches":[{"senses":"S1 · S2","en":"THE HEDGE: the core relative use and the discourse marker both soften an absolute claim.","cn":"模糊限制：核心相对义与话语标记都软化绝对主张。"},{"senses":"S3","en":"THE METHOD: comparison as an instrument that produces evidence.","cn":"方法：比较作为产生证据的工具。"},{"senses":"S4 · S5 · S6","en":"THE DEGREE: easy, few, cheap are all scaled against a usual level.","cn":"程度：容易、少、便宜都相对于通常水平定标。"},{"senses":"S7 · S9","en":"THE RANK AND THE SHARE: importance and proportion compare positions or ratios, not raw amounts.","cn":"排序与份额：重要性与比例比较位置或比率，而非绝对量。"},{"senses":"S8","en":"THE TIME: 'recently' needs the field's history as its anchor.","cn":"时间：“较近”需要以该领域历史为锚。"}]},"affixes":{"intro":{"en":"Comparatively is comparative + -ly. Comparative is Latin comparativus, from comparare, com- plus par. Its family includes comparison, comparable, comparably, and comparability; par also gives parity and peer.","cn":"comparatively 是 comparative 加 -ly。comparative 是拉丁 comparativus，出自 comparare（com- 加 par）。词族含 comparison、comparable、comparably、comparability；par 还给出 parity 与 peer。"},"latinIntro":{"en":"Latin comparare 'match' gives comparativus 'of comparison'. English keeps -ive for the adjective and adds -ly for the adverb. The same stem yields comparatio, hence comparison, and comparabilis, hence comparable.","cn":"拉丁 comparare“匹敌”给出 comparativus“比较的”。英语保留 -ive 作形容词，加 -ly 作副词。同一词干给出 comparatio（即 comparison）与 comparabilis（即 comparable）。"},"items":[{"word":"compares","structure":"compare + -s (3sg)","meaning":"sets side by side","meaningCN":"比较（三单）","example":"she compares the two","exampleCN":"她比较两者"},{"word":"compared","structure":"compare + -ed (past/participle)","meaning":"set against another","meaningCN":"比较了","example":"compared with the old model","exampleCN":"与旧模型相比"},{"word":"comparing","structure":"compare + -ing (participle)","meaning":"in the act of comparison","meaningCN":"比较中的","example":"comparing costs","exampleCN":"比较成本"},{"word":"comparison","structure":"compare + -ison (noun)","meaning":"the act of comparing","meaningCN":"比较（名词）","example":"a direct comparison","exampleCN":"直接比较"},{"word":"comparative","structure":"compare + -ative (adjective)","meaning":"involving comparison; grammar 'more'","meaningCN":"比较的；比较级（-ative 形容词）","example":"comparative literature","exampleCN":"比较文学"},{"word":"comparatively","structure":"comparative + -ly (adverb)","meaning":"relatively, by comparison","meaningCN":"相对地（-ly 副词）","example":"comparatively rare","exampleCN":"相对罕见"},{"word":"comparable","structure":"compare + -able (adjective)","meaning":"able to be compared","meaningCN":"可比较的（-able 形容词）","example":"comparable results","exampleCN":"可比结果"},{"word":"comparably","structure":"comparable + -ly (adverb)","meaning":"in a similar measure","meaningCN":"相似程度地（-ly 副词）","example":"comparably skilled","exampleCN":"技能相当"},{"word":"parity","structure":"par + -ity (same base)","meaning":"equality","meaningCN":"平等；平价（同词基）","example":"parity of treatment","exampleCN":"同等待遇"}],"latinEntries":[{"word":"par","structure":"Latin adjective","meaning":"equal","meaningCN":"相等的"},{"word":"comparare","structure":"com- + par","meaning":"to pair, match, compare","meaningCN":"配对；匹敌；比较"},{"word":"comparativus","structure":"comparare + -ivus","meaning":"of comparison","meaningCN":"比较的"},{"word":"comparatio","structure":"comparare + -tio","meaning":"a comparison","meaningCN":"比较"}]}},{"word":"compatibility","ipa_uk":"/kəmˌpætəˈbɪləti/","ipa_us":"/kəmˌpætəˈbɪləti/","definition_zh":"兼容性；相容性；可共存性；配伍性；匹配度；（生物）相容性","definition_en":"the ability of two or more things to exist or work together without conflict; the state of being compatible","core_image":"两块齿轮咬合转动，齿距一致，所以既不打滑也不卡死","scene":"装驱动前先查说明书，看这块显卡和主板能不能一起工作。Before installing the driver, check the manual for the compatibility of this graphics card with the motherboard.","sceneCN":"这里 compatibility 是「（硬件/软件）兼容性」（第 1 个义项：两个系统能一起正常工作而不冲突）；句意：装驱动前先查说明书，确认这块显卡与主板的兼容性。图中可辨识物件：显卡、主板、齿轮、驱动安装界面、兼容列表。","pos":[{"tag":"n.","zh":"兼容性；相容性；可共存性；匹配度"}],"collocations":[{"phrase":"software compatibility","zh":"软件兼容性"},{"phrase":"backward compatibility","zh":"向后兼容"},{"phrase":"blood compatibility","zh":"血液相容性"},{"phrase":"compatibility with","zh":"与…的兼容性"},{"phrase":"compatibility mode","zh":"兼容模式"},{"phrase":"biological compatibility","zh":"生物相容性"}],"forms":[{"label":"形容词","form":"compatible"},{"label":"副词","form":"compatibly"},{"label":"否定形容词","form":"incompatible"},{"label":"否定名词","form":"incompatibility"}],"derivatives":[{"word":"compatible","pos":"adj.","zh":"兼容的；相容的"},{"word":"compatibly","pos":"adv.","zh":"兼容地"},{"word":"incompatible","pos":"adj.","zh":"不兼容的"},{"word":"incompatibility","pos":"n.","zh":"不兼容；不相容"}],"senses":[{"no":"01","title":"Hardware and software compatibility","titleCN":"（软硬件）兼容性","definition":"the ability of devices or programs to work together without conflict","definitionCN":"设备或程序能一起工作而不冲突的能力","example":"The update improves compatibility with older printers.","exampleCN":"该更新改善了与旧打印机的兼容性。","why":"Computing gives the word its most concrete modern home: two systems must share protocols and formats. Compatibility is not identity; the parts differ but can still cooperate.","whyCN":"计算给该词最具体的现代归宿：两个系统必须共享协议与格式。兼容不是同一；部件不同，却仍能协作。"},{"no":"02","title":"Personal compatibility","titleCN":"（性格）相容性","definition":"the quality of getting along well with another person","definitionCN":"与另一人相处融洽的性质","example":"Their compatibility made the partnership easy.","exampleCN":"他们的相容性使合作变得轻松。","why":"The interpersonal sense is psychological: temperaments fit without constant friction. It does not require sameness, and often the best fit is complementary rather than identical.","whyCN":"人际义是心理性的：气质相合，不常摩擦。它不要求相同，最佳匹配常是互补而非同一。"},{"no":"03","title":"Medical compatibility","titleCN":"（药物/血型）配伍性；相容性","definition":"the safety of combining drugs, blood types, or tissues without harmful reaction","definitionCN":"药物、血型或组织合用时无有害反应的安全性","example":"The surgeon checked tissue compatibility before the graft.","exampleCN":"移植前外科医生检查了组织相容性。","why":"Medicine turns compatibility into a safety condition. An incompatible match can kill, so the word carries a threshold: compatible means no harmful reaction, not merely similar.","whyCN":"医学把兼容性变成安全条件。不相配可能致命，故该词带阈值：相容指无有害反应，而不只是相似。"},{"no":"04","title":"Coexistence without conflict","titleCN":"可共存性","definition":"the ability of different systems, species, or ideas to exist side by side","definitionCN":"不同系统、物种或观念并立而不冲突的能力","example":"The paper argues for the compatibility of science and religion.","exampleCN":"论文主张科学与宗教可以共存。","why":"Intellectual and ecological uses extend the word to coexistence. The claim is not that the two are the same, but that neither must destroy the other; compatibility is a peace treaty, not a merger.","whyCN":"知识与生态用法把词扩展到共存。主张不是两者相同，而是任何一方都不必消灭另一方；兼容是和平条约，不是合并。"},{"no":"05","title":"Version compatibility","titleCN":"（版本/格式）兼容","definition":"the ability of older and newer versions to exchange data","definitionCN":"新旧版本交换数据的能力","example":"The file format offers backward compatibility.","exampleCN":"该文件格式提供向后兼容。","why":"Software engineering distinguishes forward and backward compatibility: old files open in new programs, or new files in old ones. The word now names a direction as well as a relation.","whyCN":"软件工程区分前向与向后兼容：旧文件能在新程序打开，或新文件能在旧程序打开。该词现在既命名关系，也命名方向。"},{"no":"06","title":"Institutional compatibility","titleCN":"（制度/法律）相容","definition":"the condition of two rules or systems not contradicting each other","definitionCN":"两套规则或制度不互相矛盾的状态","example":"The new law must be checked for compatibility with EU rules.","exampleCN":"新法须检查是否与欧盟规则相容。","why":"Legal compatibility is consistency under a higher norm. It is judged by how rules interact in hard cases, not by whether they share wording.","whyCN":"法律相容是在更高规范下的一致。判断依据是规则在难题中如何相互作用，而非措辞是否相同。"},{"no":"07","title":"Match between partners","titleCN":"匹配度","definition":"the degree to which two people or parties suit each other","definitionCN":"两人或两方彼此适合的程度","example":"The dating app scores compatibility on shared values.","exampleCN":"该交友应用按共同价值观给匹配度打分。","why":"The commercial sense quantifies fit. A score makes compatibility seem measurable, but the variables chosen are themselves a theory of what makes a good match.","whyCN":"商业义把适合度量化为分数。分数让匹配度看似可测，但所选变量本身就是一套“何为良配”的理论。"},{"no":"08","title":"Biocompatibility","titleCN":"生物相容性","definition":"the ability of an implant or material to function in the body without rejection","definitionCN":"植入物或材料在体内工作而不被排斥的能力","example":"Titanium is valued for its biocompatibility.","exampleCN":"钛因生物相容性而受重视。","why":"Biomaterials use the word for a host response: the body must tolerate the foreign object. Compatibility here is an immune judgement, which is why 'incompatible' can mean rejection, not disagreement.","whyCN":"生物材料用该词指宿主反应：身体必须耐受外来物。此处相容是免疫判断，故 incompatible 可指排斥，而非意见不合。"},{"no":"09","title":"Compatibility mode","titleCN":"兼容模式","definition":"a setting that makes a program behave like an older version","definitionCN":"使程序表现得像旧版本的设置","example":"Run the legacy app in compatibility mode.","exampleCN":"以兼容模式运行旧应用。","why":"The phrase turns an abstract relation into a switch. The mode does not make the systems identical; it emulates the old environment so that old assumptions still hold.","whyCN":"该短语把抽象关系变成开关。模式不使系统同一；它模拟旧环境，使旧假设仍成立。"}],"etymology":{"intro":{"en":"Compatibility is compatible plus -ity. Compatible comes through French compatible from Medieval Latin compatibilis, formed on compati 'to suffer with', from com- 'with' plus pati 'to suffer, endure'. The original sense is theological: to feel with another's suffering, to have compassion. From 'able to suffer together' came 'able to exist together', and then the technical senses of systems, drugs, and versions. The stem pati also gives patient, passion, and compassion, so the word's neighbours are about enduring, not about matching.","cn":"compatibility 是 compatible 加 -ity。compatible 经法语 compatible 出自中世纪拉丁 compatibilis，基于 compati“与之共受苦”，即 com-“与”加 pati“忍受、受苦”。原义是神学的：与他人的苦难共感，即怜悯。由“能一起受苦”生出“能一起存在”，再到系统、药物与版本的技术义。词干 pati 还给出 patient、passion、compassion，故该词的邻居是关于“忍受”，而非关于“匹配”。"},"items":[{"era":"LATIN","en":"pati means 'to suffer, endure, undergo'; it is the root of patient and passion.","cn":"pati 意为“受苦、忍受、经历”，是 patient 与 passion 的根。"},{"era":"LATIN","en":"compati is com- 'with' plus pati: to suffer with another, to feel their pain.","cn":"compati 是 com-“与”加 pati：与他人共苦，感受其痛。"},{"era":"MEDIEVAL","en":"compatibilis 'able to suffer with' is formed in Medieval Latin, first in theological writing on compassion.","cn":"compatibilis“能与之共苦”在中世纪拉丁形成，最早见于论怜悯的神学写作。"},{"era":"FRENCH","en":"French compatible carries the word into English; the modern sense shifts from shared feeling to shared functioning.","cn":"法语 compatible 把词带入英语；现代义从“共同感受”转向“共同运作”。"},{"era":"19C","en":"Science and medicine adopt compatibility for drugs, tissues, and instruments that can work together safely.","cn":"十九世纪科学与医学采用 compatibility 指能安全合用的药物、组织与器械。"},{"era":"20C","en":"Computing makes it a mass-market term: hardware, software, and file formats must be compatible to cooperate.","cn":"二十世纪计算使它成为大众术语：硬件、软件与文件格式必须兼容才能协作。"}]},"similar":{"note":{"en":"The first group is the compatible family and its negative; the second is words for fitting together, which differ in whether they are about feeling, function, or measurement.","cn":"第一组是 compatible 词族及其否定；第二组是“相合”类词，差别在于讲感受、功能还是测量。"},"groups":[{"heading":"WORD FAMILY","entries":[{"word":"compatible","ipa":"/kəmˈpætəbl/","tag":"adjective","definition":"able to exist or work together without conflict.","definitionCN":"能共存或共用而不冲突的。"},{"word":"incompatible","ipa":"/ˌɪnkəmˈpætəbl/","tag":"adjective","definition":"not able to coexist or work together.","definitionCN":"不能共存或共用的。"},{"word":"compatibly","ipa":"/kəmˈpætəbli/","tag":"adverb","definition":"in a compatible way.","definitionCN":"兼容地。"}]},{"heading":"NEAR MEANING","entries":[{"word":"interoperability","ipa":"/ˌɪntərˌɒpərəˈbɪləti/","tag":"noun","definition":"the ability of systems to exchange and use each other's data. It is narrower and more technical than compatibility.","definitionCN":"系统交换并使用彼此数据的能力。比 compatibility 更窄、更技术。"},{"word":"congruity","ipa":"/kɒŋˈɡruːəti/","tag":"noun","definition":"the quality of being in harmony or agreement, often of ideas or parts.","definitionCN":"和谐一致的性质，常用于观念或部件。"},{"word":"affinity","ipa":"/əˈfɪnəti/","tag":"noun","definition":"a natural liking or attraction between people or things. It stresses attraction, not mere non-conflict.","definitionCN":"人或物之间天然的喜欢或吸引。强调吸引，而非仅仅不冲突。"}]}]},"mnemonics":{"normalIntro":{"en":"Real links: compati 'suffer with', the -ibilis suffix, the pati family, and the shift from compassion to technical cooperation.","cn":"真实联系：compati“共苦”、-ibilis 后缀、pati 词族，以及从怜悯到技术协作的偏移。"},"normal":[{"en":"Compati is 'suffer with'. Compatibility began as the ability to feel another's pain; it became the ability to work beside another.","cn":"compati 是“共苦”。compatibility 始于感受他人之痛的能力；后来变成与另一物共事的能力。"},{"en":"The pati family is about endurance: patient, passion, compassion. None of them means 'matching', which shows how far the word travelled.","cn":"pati 词族关于忍受：patient、passion、compassion。它们都不指“匹配”，可见该词走了多远。"},{"en":"Compatible is not identical. Two different systems can cooperate if their interfaces align.","cn":"compatible 不是相同。两个不同系统只要接口对齐就能协作。"},{"en":"Backward compatibility is a direction: old files open in new software, not the reverse.","cn":"向后兼容是方向：旧文件能在新软件打开，反之不然。"},{"en":"A compatibility mode is an emulation, not an equality; it makes old assumptions true again.","cn":"兼容模式是模拟，不是等同；它让旧假设重新成立。"}],"abstract":[{"en":"Compatibility is a relation, not a property: nothing is compatible alone, only with something.","cn":"兼容是关系而非属性：没有东西独自兼容，只能与某物兼容。"},{"en":"The word's history turns sympathy into engineering, a reminder that cooperation can be built from shared vulnerability.","cn":"该词史把同情变成工程，提醒合作可以从共同脆弱中建立。"},{"en":"Every compatibility test chooses a boundary: what must match for the pair to count as compatible, and what may differ.","cn":"每个兼容测试都在选边界：什么必须一致才算兼容，什么可以不同。"}]},"examples":[{"en":"Check the compatibility of the software with your system.","cn":"请检查该软件与你系统的兼容性。"},{"en":"The two blood types are not compatible.","cn":"这两种血型不相容。"},{"en":"Backward compatibility lets old files open in the new version.","cn":"向后兼容让旧文件能在新版本中打开。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“康帕提比里提”——com + pati，能一起“忍”得住对方 → compatibility 相容性","word":"compatibility"},"root":"compatible（法语 compatible ← 中世纪拉丁 compatibilis ← compati“共苦”= com-“与”+ pati“忍受”）+ -ity。","sensesIntro":{"en":"Nine senses of compatibility: hardware and software, personality, medicine, coexistence, versions, institutions, partners, implants, and a legacy mode. The invariant is the ability to be together without breaking.","cn":"compatibility 的九个义项：软硬件、性格、医学、共存、版本、制度、伴侣、植入物、兼容模式。不变量是“能在一起而不崩坏”的能力。"},"semanticMap":{"core":{"en":"CORE IMAGE: two gears of different make meshing because their teeth are pitched to match.","cn":"核心意象：两个不同来路的齿轮因齿距相合而咬合转动。"},"chain":["PUT TWO THINGS TOGETHER","TEST THE INTERFACE","CHECK FOR CONFLICT","ADJUST THE DIFFERENCE","LET THEM WORK AS ONE","KEEP THE OPTION OPEN"],"branches":[{"senses":"01 · 09","en":"THE MACHINE: hardware and emulation modes are engineered interfaces.","cn":"机器：硬件与模拟模式都是被工程化的接口。"},{"senses":"02 · 07","en":"THE PERSON: temperament and partner matching judge fit between people.","cn":"人：气质与伴侣匹配判断人与人是否相合。"},{"senses":"03 · 08","en":"THE BODY: drugs, blood, and implants must be tolerated by the host.","cn":"身体：药物、血液与植入物必须被宿主耐受。"},{"senses":"04 · 06","en":"THE IDEA AND THE RULE: science and religion, or two legal systems, can coexist without contradiction.","cn":"观念与规则：科学与宗教、或两套法律，可以共存而不矛盾。"},{"senses":"05","en":"THE DIRECTION: forward and backward compatibility name which way the old and new must speak.","cn":"方向：前向与向后兼容命名新旧应当由哪一方迁就。"}]},"affixes":{"intro":{"en":"Compatibility is compatible + -ity. Compatible is Medieval Latin compatibilis, from compati, com- plus pati 'suffer'. The family includes incompatible and incompatibility; the same pati root gives patient, passion, and compassion.","cn":"compatibility 是 compatible 加 -ity。compatible 是中世纪拉丁 compatibilis，出自 compati（com- 加 pati“受苦”）。词族含 incompatible 与 incompatibility；同一 pati 词根给出 patient、passion、compassion。"},"latinIntro":{"en":"Latin pati 'suffer' gives compati 'suffer with' and the Medieval Latin adjective compatibilis 'able to suffer with'. English adds -ity for the noun and in- for the negative. The stem's other descendants are about endurance rather than fit.","cn":"拉丁 pati“受苦”给出 compati“共苦”与中世纪拉丁形容词 compatibilis“能共苦的”。英语加 -ity 成名词，加 in- 成否定。该词干的其他后裔关于忍受，而非相合。"},"items":[{"word":"compatible","structure":"compati + -ible (adjective)","meaning":"able to exist or work together","meaningCN":"兼容的（-ible 形容词）","example":"compatible devices","exampleCN":"兼容设备"},{"word":"compatibility","structure":"compatible + -ity (noun)","meaning":"the ability to work together","meaningCN":"兼容性（-ity 名词）","example":"software compatibility","exampleCN":"软件兼容性"},{"word":"compatibly","structure":"compatible + -ly (adverb)","meaning":"in a compatible way","meaningCN":"兼容地（-ly 副词）","example":"behave compatibly","exampleCN":"表现相容"},{"word":"incompatible","structure":"in- + compatible (negative)","meaning":"not able to work together","meaningCN":"不兼容的（in- 否定）","example":"incompatible formats","exampleCN":"不兼容格式"},{"word":"incompatibility","structure":"in- + compatibility (negative)","meaning":"the state of not being compatible","meaningCN":"不兼容（否定名词）","example":"blood incompatibility","exampleCN":"血液不相容"},{"word":"compatibilism","structure":"compatibility + -ism (doctrine)","meaning":"the view that free will and determinism can coexist","meaningCN":"相容论（-ism 学说）","example":"philosophical compatibilism","exampleCN":"哲学相容论"},{"word":"compatibilist","structure":"compatibilism + -ist (person)","meaning":"one who holds the compatibilist view","meaningCN":"相容论者（-ist 人）","example":"a compatibilist account","exampleCN":"相容论解释"},{"word":"patient","structure":"pati + -iens (same root)","meaning":"one who suffers or endures","meaningCN":"病人；忍耐者（同根）","example":"a patient in hospital","exampleCN":"住院病人"},{"word":"compassion","structure":"com- + pati + -ion (same root)","meaning":"suffering with another","meaningCN":"同情；怜悯（同根）","example":"show compassion","exampleCN":"表示同情"}],"latinEntries":[{"word":"pati","structure":"Latin verb","meaning":"to suffer, endure","meaningCN":"受苦；忍受"},{"word":"compati","structure":"com- + pati","meaning":"to suffer with","meaningCN":"共苦"},{"word":"compatibilis","structure":"compati + -ibilis","meaning":"able to suffer with; compatible","meaningCN":"能共苦的；相容的"},{"word":"passio","structure":"pati + -tio","meaning":"suffering, passion","meaningCN":"受苦；激情"}]}},{"word":"complexity","ipa_uk":"/kəmˈpleksəti/","ipa_us":"/kəmˈpleksəti/","definition_zh":"复杂性；复杂程度；（计算）复杂度；错综复杂的事物；复杂性科学","definition_en":"the state of having many interconnected parts or aspects; the degree to which something is hard to understand or analyse","core_image":"一张网越织越密，每根线都搭在别的线上，抽动一根，整张网都动","scene":"这个问题的难处不在参数多，而在参数彼此牵连，改一个就牵动全部。The real complexity of the problem is not the number of parameters but the way each one pulls on all the others.","sceneCN":"这里 complexity 是「复杂性、错综关联的程度」（第 1 个义项：由许多相互关联的部分构成的状态）；句意：这个问题的真正复杂性不在参数多，而在参数彼此牵连。图中可辨识物件：密集的网、相互连接的节点、参数面板、放大的线结、演算纸。","pos":[{"tag":"n.","zh":"复杂性；复杂程度；复杂度"},{"tag":"n.","zh":"复杂的事物；难题"}],"collocations":[{"phrase":"the complexity of the system","zh":"系统的复杂性"},{"phrase":"computational complexity","zh":"计算复杂度"},{"phrase":"reduce complexity","zh":"降低复杂性"},{"phrase":"a high degree of complexity","zh":"高度复杂"},{"phrase":"complexity science","zh":"复杂性科学"},{"phrase":"time complexity","zh":"时间复杂度"}],"forms":[{"label":"复数","form":"complexities"},{"label":"形容词","form":"complex"},{"label":"副词","form":"complexly"},{"label":"反义名词","form":"simplicity"}],"derivatives":[{"word":"complex","pos":"adj./n.","zh":"复杂的；综合体"},{"word":"complexly","pos":"adv.","zh":"复杂地"},{"word":"complexify","pos":"v.","zh":"使复杂化"},{"word":"complexification","pos":"n.","zh":"复杂化过程"}],"senses":[{"no":"01","title":"Many interconnected parts","titleCN":"复杂性","definition":"the state of consisting of many parts that affect one another","definitionCN":"由许多相互影响的部分构成的状态","example":"The complexity of the ecosystem defies simple models.","exampleCN":"该生态系统的复杂性使简单模型失效。","why":"This is the core sense: not merely 'many', but 'many and linked'. A pile of sand has many grains but low complexity; a web has fewer threads but high complexity because each pull travels.","whyCN":"这是核心义：不只是“多”，而是“多且相互关联”。一堆沙粒很多却复杂度低；一张网线更少却复杂度高，因为每次拉动都会传导。"},{"no":"02","title":"Computational complexity","titleCN":"计算复杂度","definition":"the amount of time or memory an algorithm needs as input size grows","definitionCN":"算法随输入规模增长所需的时间或内存量","example":"Sorting has a complexity of n log n.","exampleCN":"排序的复杂度为 n log n。","why":"Computer science makes complexity a measurable quantity. It is not about how hard the code looks but about how resource use scales, which turns an intuition into a curve.","whyCN":"计算机科学使复杂性成为可测量。它不是看代码多难懂，而是看资源用量如何随规模增长，把直觉变成曲线。"},{"no":"03","title":"A level of complexity","titleCN":"复杂程度","definition":"the degree to which something is complex, often compared across cases","definitionCN":"某物复杂的程度，常用于跨案例比较","example":"The tasks were ranked by complexity.","exampleCN":"这些任务按复杂程度排序。","why":"The noun can be countable here: one complexity, a higher complexity. This lets researchers compare systems on a scale, even though the scale itself must be defined.","whyCN":"此处名词可数：一种复杂度、更高的复杂度。这使研究者能在尺度上比较系统，尽管尺度本身须被定义。"},{"no":"04","title":"Intricacy of plot or structure","titleCN":"错综复杂（情节/结构）","definition":"the quality of a story or structure with many intertwined threads","definitionCN":"故事或结构有多条交织线索的性质","example":"the complexity of the novel's timeline","exampleCN":"小说时间线的错综复杂","why":"Literary criticism uses the word for designed intricacy. Unlike confusion, complexity can be a value: the reader is trusted to hold several threads at once.","whyCN":"文学批评用该词指有意设计的错综。与混乱不同，复杂性可以是一种价值：读者被信任能同时握住多条线。"},{"no":"05","title":"Complexity science","titleCN":"复杂性科学","definition":"the study of systems whose collective behaviour emerges from many interacting parts","definitionCN":"研究由许多相互作用部分涌现出集体行为的系统","example":"Complexity science studies markets, cells, and cities.","exampleCN":"复杂性科学研究市场、细胞与城市。","why":"This is an institutional sense: a field named after its object. It treats emergence, feedback, and adaptation as shared features across very different systems.","whyCN":"这是制度义：以对象命名的领域。它把涌现、反馈与适应当作跨非常不同系统的共同特征。"},{"no":"06","title":"A complicated thing","titleCN":"复杂的事物；难题","definition":"a particular thing, situation, or detail that is hard to handle","definitionCN":"难以处理的特定事物、情形或细节","example":"We must deal with several complexities first.","exampleCN":"我们得先处理若干复杂问题。","why":"The countable plural turns the abstract quality into obstacles. In project talk, 'the complexities' are the specific snags that must be listed, priced, and solved.","whyCN":"可数复数把抽象性质变成障碍。在项目话语中，the complexities 是必须列出、计价并解决的具体麻烦。"},{"no":"07","title":"Biological complexity","titleCN":"生物复杂性","definition":"the layered organization of living systems from molecules to ecosystems","definitionCN":"生命系统从分子到生态的多层组织","example":"Cellular complexity arose early in evolution.","exampleCN":"细胞复杂性在演化早期就出现了。","why":"Biology uses the word for levels of organization and their integration. The puzzle is how simple components produce hierarchical order without a central designer.","whyCN":"生物学用该词指组织层级及其整合。谜题是简单组分如何在没有中心设计者的情况下产生层级秩序。"},{"no":"08","title":"Algorithmic time complexity","titleCN":"（算法）时间复杂度","definition":"the growth rate of an algorithm's running time with input size","definitionCN":"算法运行时间随输入规模增长的速率","example":"This search has linear time complexity.","exampleCN":"该搜索具有线性时间复杂度。","why":"This narrow sense names a class of functions, not a feeling. Complexity here is a property of a procedure, and 'high complexity' can be a technical defect even in a fast program.","whyCN":"这一窄义命名一类函数，而非感觉。此处复杂性是程序的属性，“高复杂度”即使在快程序中也可以是技术缺陷。"},{"no":"09","title":"Social complexity","titleCN":"社会复杂性","definition":"the density of roles, rules, and interactions in a society or organization","definitionCN":"社会或组织中角色、规则与互动的密度","example":"Urban life brings social complexity.","exampleCN":"城市生活带来社会复杂性。","why":"Social science uses the word for differentiated roles and institutions. More complexity can mean more capacity, but also more points of failure and more unequal access to understanding.","whyCN":"社会科学用该词指分化的角色与制度。更高的复杂性可意味着更强能力，也意味着更多故障点与更不平等的理解通道。"}],"etymology":{"intro":{"en":"Complexity is complex plus -ity. Complex comes from Latin complexus, the past participle of complecti 'to encircle, embrace', from com- 'together' plus plectere 'to weave, braid'. The image is strands woven into one fabric, not parts merely piled up. The -ity noun follows Latin -itas. Note the near-twin complicated: it comes from complicare, com- plus plicare 'to fold', a different though related root. Complex says 'woven together'; complicated says 'folded together'.","cn":"complexity 是 complex 加 -ity。complex 出自拉丁 complexus，即 complecti“环绕、拥抱”的过去分词，由 com-“一起”加 plectere“编织、编辫”构成。意象是多股线织成一块布，而非零件堆放。名词 -ity 依拉丁 -itas。注意近形词 complicated：它出自 complicare，com- 加 plicare“折叠”，词根不同但相关。complex 说“织在一起”；complicated 说“折在一起”。"},"items":[{"era":"LATIN","en":"plectere means 'to weave, braid, intertwine'; it gives the 'plex' seen in complex and perplex.","cn":"plectere 意为“编织、编辫、缠绕”，给出 complex、perplex 中的 -plex。"},{"era":"LATIN","en":"complecti is com- 'together' plus plectere: to embrace or encircle, literally to weave together.","cn":"complecti 是 com-“一起”加 plectere：拥抱、环绕，字面即“织在一起”。"},{"era":"LATIN","en":"complexus, its past participle, means 'interwoven, encircling'; English complex keeps the sense of many parts joined.","cn":"其过去分词 complexus 意为“交织的、环绕的”；英语 complex 保留“多部分相连”义。"},{"era":"17C","en":"English complexity appears in the 17C for the state of being complex, first in learned prose.","cn":"英语 complexity 于十七世纪出现，指复杂的状态，最早用于学术散文。"},{"era":"20C","en":"Mathematics and computer science make 'complexity' a measurable growth rate for algorithms.","cn":"二十世纪数学与计算机科学把 complexity 变成算法可测量的增长率。"},{"era":"MODERN","en":"Complexity science turns the noun into a field name for systems with emergent collective behaviour.","cn":"复杂性科学把该名词变成领域名称，指具有涌现集体行为的系统。"}]},"similar":{"note":{"en":"The first group is the complex family and its look-alike relatives; the second is words for difficulty, which differ in whether they name many parts, tangled folds, or mere difficulty.","cn":"第一组是 complex 词族及其近形亲属；第二组是“难”类词，差别在于指多部分、乱折叠还是单纯困难。"},"groups":[{"heading":"WORD FAMILY","entries":[{"word":"complex","ipa":"/ˈkɒmpleks/","tag":"adjective/noun","definition":"woven from many interconnected parts; also a group of linked buildings or symptoms.","definitionCN":"由许多相互关联部分织成的；也指建筑群或症状群。"},{"word":"complexion","ipa":"/kəmˈplekʃn/","tag":"noun","definition":"the natural colour and texture of the skin; also the general character of something.","definitionCN":"肤色与质地；也指某物的总体性质。"},{"word":"perplex","ipa":"/pəˈpleks/","tag":"verb","definition":"to confuse by complexity, literally to weave thoroughly.","definitionCN":"因复杂而使人困惑，字面即“织得密不透风”。"}]},{"heading":"NEAR MEANING","entries":[{"word":"complication","ipa":"/ˌkɒmplɪˈkeɪʃn/","tag":"noun","definition":"a difficulty that makes a situation harder; literally a folding together. It is a separate root from complex.","definitionCN":"使情形更难的因素；字面即“折在一起”。与 complex 词根不同。"},{"word":"intricacy","ipa":"/ˈɪntrɪkəsi/","tag":"noun","definition":"the quality of having many fine, entangled details. It stresses fine structure rather than scale.","definitionCN":"有许多细密缠结细节的性质。强调细结构，而非规模。"},{"word":"difficulty","ipa":"/ˈdɪfɪkəlti/","tag":"noun","definition":"the quality of being hard to do or understand. It names resistance, not structure.","definitionCN":"难以做成或理解的性质。命名阻力，而非结构。"}]}]},"mnemonics":{"normalIntro":{"en":"Real links: plectere 'weave', complexus 'woven together', the -ity noun, and the contrast with complicare 'fold together'.","cn":"真实联系：plectere“编织”、complexus“织在一起”、-ity 名词，以及与 complicare“折在一起”的对照。"},"normal":[{"en":"Complex is 'woven together', from plectere 'weave'. The parts are threads, and the pattern is the point.","cn":"complex 是“织在一起”，出自 plectere“编织”。部分是线，图案才是关键。"},{"en":"Complicated is 'folded together', from plicare 'fold'. Folded paper is tangled; woven cloth is structured. The twins are not the same.","cn":"complicated 是“折在一起”，出自 plicare“折叠”。折纸是乱缠；织布是有结构。这对双胞胎并不相同。"},{"en":"Complexity is not the count of parts but the density of their connections.","cn":"复杂性不是部分的数量，而是连接密度。"},{"en":"In algorithms, complexity is a growth curve, not a mood; n log n is a different claim from 'hard'.","cn":"算法中，复杂度是增长曲线，不是情绪；n log n 与“难”是不同主张。"},{"en":"'The complexities' are the specific snags a project must price; the abstract noun becomes a checklist.","cn":"the complexities 是项目必须计价的具体麻烦；抽象名词变成清单。"}],"abstract":[{"en":"Complexity is relational: it belongs to the pattern of dependence, not to any single part.","cn":"复杂性是关系性的：它属于依赖模式，而不属于任何单个部分。"},{"en":"A system can be complex and still predictable, or simple and chaotic; complexity is structure, not uncertainty.","cn":"系统可以复杂却可预测，也可以简单却混沌；复杂性是结构，不是不确定性。"},{"en":"Naming something complex is often a claim about who is entitled to understand it.","cn":"把某物称为复杂，常是关于“谁有资格理解它”的主张。"}]},"examples":[{"en":"The complexity of the tax code is a burden on small firms.","cn":"税法的复杂性是小企业的负担。"},{"en":"This algorithm has quadratic time complexity.","cn":"该算法具有平方时间复杂度。"},{"en":"The novel's complexity rewards a second reading.","cn":"这部小说的复杂性值得再读一遍。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“康普莱克西提”——许多线 com 在一起织成 plex → complexity 复杂性","word":"complexity"},"root":"complex（拉丁 complexus ← complecti“环绕、织在一起”= com-“一起”+ plectere“编织”）+ -ity；近形词 complicated 出自 complicare（plicare“折叠”），词根不同。","sensesIntro":{"en":"Nine senses of complexity: interconnected parts, computational cost, a degree, narrative intricacy, a science, a specific snag, biological organization, algorithmic growth, and social density. All turn on how parts are related, not how many there are.","cn":"complexity 的九个义项：相互关联的部分、计算代价、程度、叙事错综、一门科学、具体麻烦、生物组织、算法增长、社会密度。关键都在部分如何关联，而非数量多少。"},"semanticMap":{"core":{"en":"CORE IMAGE: a net so densely woven that pulling one thread moves the whole web.","cn":"核心意象：一张织得极密的网，抽动一根线，整张网都动。"},"chain":["MANY PARTS","WEAVE THEM TOGETHER","EACH PULL TRAVELS","THE PATTERN RESISTS ANALYSIS","MEASURE OR NAME IT","DEAL WITH THE SNAGS"],"branches":[{"senses":"S1 · S4 · S7","en":"THE PATTERN: ecosystems, plots, and cells are woven structures whose order is the object.","cn":"图案：生态系统、情节与细胞都是织成结构，其秩序才是对象。"},{"senses":"S2 · S8","en":"THE COST: computing turns complexity into a growth rate of time or memory.","cn":"代价：计算把复杂性变成时间或内存的增长率。"},{"senses":"S3 · S6","en":"THE DEGREE AND THE SNAG: one can rank complexity and list its concrete troubles.","cn":"程度与麻烦：既可给复杂性排序，也可列出其具体麻烦。"},{"senses":"S5","en":"THE FIELD: complexity science studies emergence across markets, cells, and cities.","cn":"领域：复杂性科学研究市场、细胞与城市中的涌现。"},{"senses":"S9","en":"THE SOCIETY: roles and rules multiply, adding capacity and fragility at once.","cn":"社会：角色与规则增殖，同时增加能力与脆弱。"}]},"affixes":{"intro":{"en":"Complexity is complex + -ity. Complex is Latin complexus, from complecti, com- plus plectere 'weave'. The family includes complexify and complexification; the same root gives complexion and perplex, while the look-alike complicated comes from plicare 'fold'.","cn":"complexity 是 complex 加 -ity。complex 是拉丁 complexus，出自 complecti（com- 加 plectere“编织”）。词族含 complexify 与 complexification；同根给出 complexion 与 perplex，而近形词 complicated 出自 plicare“折叠”。"},"latinIntro":{"en":"Latin plectere 'weave' gives complecti 'embrace, weave together' and its participle complexus. English builds complex, complexity, and complexify on this stem. The parallel root plicare 'fold' gives complicate and complication, which is why the two English adjectives feel alike but are not cognate twins.","cn":"拉丁 plectere“编织”给出 complecti“拥抱、织在一起”及其分词 complexus。英语在此词干上造 complex、complexity、complexify。平行词根 plicare“折叠”给出 complicate 与 complication，故两个英语形容词感觉相近却并非同源双生。"},"items":[{"word":"complex","structure":"complexus (adjective/noun)","meaning":"woven from many interconnected parts","meaningCN":"复杂的；综合体（形容词/名词）","example":"a complex system","exampleCN":"复杂系统"},{"word":"complexity","structure":"complex + -ity (noun)","meaning":"the state of being complex","meaningCN":"复杂性（-ity 名词）","example":"the complexity of the brain","exampleCN":"大脑的复杂性"},{"word":"complexities","structure":"complexity + -es (plural)","meaning":"specific difficult features","meaningCN":"具体复杂问题（复数）","example":"legal complexities","exampleCN":"法律上的复杂问题"},{"word":"complexly","structure":"complex + -ly (adverb)","meaning":"in a complex way","meaningCN":"复杂地（-ly 副词）","example":"a complexly layered design","exampleCN":"层次复杂的设计"},{"word":"complexify","structure":"complex + -ify (verb)","meaning":"to make more complex","meaningCN":"使复杂化（-ify 动词）","example":"complexify the model","exampleCN":"使模型复杂化"},{"word":"complexification","structure":"complexify + -ation (noun)","meaning":"the process of becoming complex","meaningCN":"复杂化过程（-ation 名词）","example":"progressive complexification","exampleCN":"逐步复杂化"},{"word":"complexion","structure":"complexus + -ion (same root)","meaning":"skin colour; general character","meaningCN":"肤色；总体性质（同根）","example":"a pale complexion","exampleCN":"苍白的肤色"},{"word":"perplex","structure":"per- + plectere (same root)","meaning":"to confuse, literally weave through","meaningCN":"使困惑（同根，前缀不同）","example":"a perplexing question","exampleCN":"令人困惑的问题"},{"word":"plexus","structure":"plexus (Latin noun)","meaning":"a network of nerves or vessels","meaningCN":"神经丛；血管丛（同根）","example":"the brachial plexus","exampleCN":"臂神经丛"}],"latinEntries":[{"word":"plectere","structure":"Latin verb","meaning":"to weave, braid, intertwine","meaningCN":"编织；缠绕"},{"word":"complecti","structure":"com- + plectere","meaning":"to embrace, encircle","meaningCN":"拥抱；环绕"},{"word":"complexus","structure":"past participle of complecti","meaning":"interwoven, encircling","meaningCN":"交织的；环绕的"},{"word":"complexio","structure":"complecti + -io","meaning":"a combination, connection","meaningCN":"结合；连接"}]}},{"word":"complication","ipa_uk":"/ˌkɒmplɪˈkeɪʃn/","ipa_us":"/ˌkɑːmplɪˈkeɪʃn/","definition_zh":"并发症；复杂化；复杂因素；纠葛；复杂情况；（棋）复杂局面；折叠交织（罕见本义）","definition_en":"a secondary problem or disease that makes a situation worse; the act of making something more complex; a tangled feature of a plot or process","core_image":"原本一条直线的手术方案，被一个突然出现的岔口折成死结","scene":"手术后第三天，伤口感染，原本一周的恢复期被拉长成一个月。On the third day after surgery an infection appears, a complication that stretches a one-week recovery into a month.","sceneCN":"这里 complication 是「并发症」（第 1 个义项：在原有疾病或手术后出现的、使病情更严重的继发问题）；句意：术后第三天出现感染这一并发症，把一周的恢复期拉长成一个月。图中可辨识物件：病床、输液架、伤口敷料、体温单、被折起的病历纸。","pos":[{"tag":"n.","zh":"并发症；复杂化；复杂因素；纠葛"}],"collocations":[{"phrase":"a medical complication","zh":"医学并发症"},{"phrase":"postoperative complication","zh":"术后并发症"},{"phrase":"add a complication","zh":"增加复杂因素"},{"phrase":"a complication arises","zh":"出现复杂情况"},{"phrase":"without complication","zh":"无并发症"},{"phrase":"a legal complication","zh":"法律上的纠葛"}],"forms":[{"label":"复数","form":"complications"},{"label":"动词","form":"complicate"},{"label":"形容词","form":"complicated"},{"label":"形容词","form":"complicating"}],"derivatives":[{"word":"complicate","pos":"v.","zh":"使复杂化"},{"word":"complicated","pos":"adj.","zh":"复杂的；棘手的"},{"word":"complicating","pos":"adj.","zh":"使复杂化的"},{"word":"uncomplicated","pos":"adj.","zh":"不复杂的；无并发症的"}],"senses":[{"no":"01","title":"A medical complication","titleCN":"并发症","definition":"a secondary disease or condition that arises during or after another illness or treatment","definitionCN":"在另一疾病或治疗期间或之后出现的继发疾病或状况","example":"Infection is a common complication after surgery.","exampleCN":"感染是术后常见并发症。","why":"Medicine gives the word its sharpest sense: the new problem is caused by the first one or its treatment, not merely coincident. The prefix-like 'com-' is no longer felt; the word is a technical label.","whyCN":"医学给该词最锋利的义：新问题由第一个病或其治疗引起，而非仅仅同时发生。com- 已不被感知；该词是技术标签。"},{"no":"02","title":"The act of making harder","titleCN":"复杂化；使更麻烦","definition":"the act of making a situation more difficult or tangled","definitionCN":"使情形更难或更纠缠的行为","example":"The new rule was an unnecessary complication.","exampleCN":"新规定是一次不必要的复杂化。","why":"This is the plain action sense: something simple is folded into something harder. The noun can name the act, the result, or the factor that does the folding.","whyCN":"这是朴素动作义：简单之事被折成更难之事。名词可指动作、结果，或做折叠的那个因素。"},{"no":"03","title":"A tangled feature of a plot","titleCN":"（情节）纠葛","definition":"an added plot element that makes the story more intricate","definitionCN":"使故事更错综的附加情节元素","example":"The letter introduces a complication in the second act.","exampleCN":"那封信在第二幕引入一个纠葛。","why":"Narrative uses the word for the turn that prevents a simple resolution. A complication is not a flaw; it is the obstacle that makes a story worth telling.","whyCN":"叙事用该词指阻止简单解决的那个转折。纠葛不是缺陷；它是使故事值得讲述的障碍。"},{"no":"04","title":"An extra complicating factor","titleCN":"额外复杂因素","definition":"an additional fact or condition that must now be considered","definitionCN":"现在必须考虑的额外事实或条件","example":"Cost is a further complication.","exampleCN":"成本是又一个复杂因素。","why":"This sense is analytic: a factor enters the situation and changes the calculation. It is countable, and often introduced by 'another' or 'a further'.","whyCN":"此义是分析性的：一个因素进入情形并改变计算。它可数，常由 another 或 a further 引出。"},{"no":"05","title":"Over-complication of a process","titleCN":"（流程）复杂化","definition":"the state of having more steps or rules than the task requires","definitionCN":"步骤或规则多于任务所需的状态","example":"The approval process suffers from complication.","exampleCN":"审批流程深受复杂化之累。","why":"Here the word is critical: complexity has outrun need. The implied standard is fitness, not simplicity for its own sake; a complicated procedure can still be justified.","whyCN":"此处该词带批评：复杂性已超出需要。隐含标准是适配，而非为简而简；复杂的程序仍可有理。"},{"no":"06","title":"A postoperative complication","titleCN":"术后并发症","definition":"a problem occurring in the period after an operation","definitionCN":"手术之后一段时间内出现的问题","example":"Bleeding is a recognised postoperative complication.","exampleCN":"出血是已知的术后并发症。","why":"The compound is a fixed medical category. 'Postoperative' sets the time window, and the complication is counted in audits, which makes it an administrative as well as a clinical object.","whyCN":"该复合词是固定医学类别。postoperative 设定时间窗，并发症在审计中被计数，故它既是临床对象，也是行政对象。"},{"no":"07","title":"An unforeseen difficulty","titleCN":"未预料的复杂情况","definition":"an unexpected difficulty that changes the plan","definitionCN":"改变计划的意外困难","example":"An unforeseen complication delayed the launch.","exampleCN":"未预料的复杂情况推迟了发布。","why":"Project language uses the word to name surprises. The difficulty is not necessarily caused by error; it is a fold in the path that no one had mapped.","whyCN":"项目语言用该词命名意外。困难未必由错误引起；它是没人画过的路径折口。"},{"no":"08","title":"A tactical complication (chess)","titleCN":"（棋）复杂局面","definition":"a position with many interacting threats that must be calculated","definitionCN":"有许多相互作用的威胁、需要计算的位置","example":"The opening led to rich complications.","exampleCN":"开局引出丰富的复杂局面。","why":"Chess uses the plural for lines where several threats interact. Here complication is almost a virtue: the player who can calculate the tangle better wins.","whyCN":"棋类用复数指多个威胁相互作用的线路。此处 complication 近乎优点：算清乱局者胜。"},{"no":"09","title":"A literal folding together","titleCN":"折叠；交织（罕见本义）","definition":"the act of folding or weaving things together, now rare outside technical writing","definitionCN":"把事物折叠或交织在一起的行为，技术文本外罕见","example":"The term once named the complication of strands.","exampleCN":"该词曾指线股的交织。","why":"This is the etymological sense, still visible in the Latin root but almost dead in English. It is kept here because it explains the metaphor behind all the others.","whyCN":"这是词源义，仍见于拉丁词根，在英语中几近消失。保留此义，因为它解释其余义项背后的隐喻。"}],"etymology":{"intro":{"en":"Complication is complicate plus -ation. Complicate comes from Latin complicare 'to fold together', from com- 'together' plus plicare 'to fold'. The -ation noun follows Latin complicatio. The literal sense 'a folding together' is almost lost; what survives is the image of a simple line becoming a tangle. Medicine's 'complication' (a secondary condition) is a 17C development, and it now dominates. Note that complication is not from the same root as complex: complex goes back to plectere 'weave', complication to plicare 'fold'.","cn":"complication 是 complicate 加 -ation。complicate 出自拉丁 complicare“折在一起”，由 com-“一起”加 plicare“折叠”构成。名词 -ation 依拉丁 complicatio。字面义“折在一起”几近消失；留下的是“一条简单的线变成乱结”的意象。医学的“并发症”（继发状况）是十七世纪的发展，现占主导。注意 complication 与 complex 并非同根：complex 上溯 plectere“编织”，complication 上溯 plicare“折叠”。"},"items":[{"era":"LATIN","en":"plicare means 'to fold, bend, ply'; it gives explicit, implicate, multiply, and complicate.","cn":"plicare 意为“折叠、弯曲、使屈从”，给出 explicit、implicate、multiply、complicate。"},{"era":"LATIN","en":"complicare is com- 'together' plus plicare: to fold several things into one another.","cn":"complicare 是 com-“一起”加 plicare：把数物互相折在一起。"},{"era":"LATIN","en":"complicatio is the action noun; English complication keeps the -ation abstract-noun pattern.","cn":"complicatio 是动作名词；英语 complication 保留 -ation 抽象名词模式。"},{"era":"17C","en":"The medical sense 'a secondary condition' appears in the 17C and gradually becomes the dominant one.","cn":"十七世纪出现医学义“继发状况”，并逐渐成为主导义。"},{"era":"19C","en":"Everyday and literary uses extend the word to any added difficulty in plans, plots, and procedures.","cn":"十九世纪日常与文学用法把词扩展到计划、情节与程序中的任何附加困难。"},{"era":"MODERN","en":"Chess, project management, and clinical auditing each keep a specialised countable sense of the noun.","cn":"棋类、项目管理与临床审计各保留该名词一个专门的可数义。"}]},"similar":{"note":{"en":"The first group is the complicate family, with its folded root; the second is words for added difficulty, which differ in cause and scale.","cn":"第一组是 complicate 词族及其“折叠”词根；第二组是“附加困难”类词，成因与规模不同。"},"groups":[{"heading":"WORD FAMILY","entries":[{"word":"complicate","ipa":"/ˈkɒmplɪkeɪt/","tag":"verb","definition":"to make something more difficult by adding parts or conditions.","definitionCN":"通过增加部分或条件使某事更难。"},{"word":"complicated","ipa":"/ˈkɒmplɪkeɪtɪd/","tag":"adjective","definition":"made of many interconnected parts; hard to understand.","definitionCN":"由许多相互关联部分构成、难以理解的。"},{"word":"uncomplicated","ipa":"/ˌʌnˈkɒmplɪkeɪtɪd/","tag":"adjective","definition":"simple; also, in medicine, without secondary problems.","definitionCN":"简单的；医学上也指无并发症的。"}]},{"heading":"NEAR MEANING","entries":[{"word":"complexity","ipa":"/kəmˈpleksəti/","tag":"noun","definition":"the state of many interconnected parts. It is structural; complication is an added difficulty.","definitionCN":"许多相互关联部分的状态。它是结构性的；complication 是附加困难。"},{"word":"setback","ipa":"/ˈsetbæk/","tag":"noun","definition":"a problem that delays progress. It stresses reversal, not added intricacy.","definitionCN":"延误进展的问题。强调倒退，而非增加错综。"},{"word":"snag","ipa":"/snæɡ/","tag":"noun","definition":"a small unexpected problem. It is informal and usually minor.","definitionCN":"小的意外问题。口语，通常较小。"}]}]},"mnemonics":{"normalIntro":{"en":"Real links: plicare 'fold', complicare 'fold together', the -ation noun, and the medical specialisation in the 17C.","cn":"真实联系：plicare“折叠”、complicare“折在一起”、-ation 名词，以及十七世纪的医学专门化。"},"normal":[{"en":"Complicare is 'fold together'. A complication is a fold in a path that was supposed to be straight.","cn":"complicare 是“折在一起”。complication 是原本该笔直的路径上的一个折口。"},{"en":"The root plicare also gives explicit ('unfolded') and implicate ('folded in'). The family is about folding, not weaving.","cn":"词根 plicare 还给出 explicit（“展开”）与 implicate（“折入”）。该族关乎折叠，不是编织。"},{"en":"Complex is woven (plectere); complicated is folded (plicare). The two adjectives are near-twins from different parents.","cn":"complex 是编织（plectere）；complicated 是折叠（plicare）。两个近形形容词来自不同父母。"},{"en":"In medicine, a complication is not a coincidence: it follows from the illness or the treatment.","cn":"医学中，并发症不是巧合：它由疾病或治疗引出。"},{"en":"In chess, complications are calculated, not regretted; the tangle is the game.","cn":"棋中，复杂局面是被计算的，不是被懊悔的；乱局就是棋。"}],"abstract":[{"en":"A complication is a second-order problem: it arises from the response to the first problem, not from the first problem alone.","cn":"并发症是二阶问题：它由对第一问题的反应产生，而非仅由第一问题产生。"},{"en":"Every plan meets folds it did not draw; the difference between failure and adaptation is whether the fold is mapped in time.","cn":"每个计划都会遇到未画的折口；失败与适应的差别在于折口是否被及时画出。"},{"en":"Calling something a complication is a causal claim: it says this difficulty belongs to that situation, not to chance.","cn":"称某事为并发症是一个因果主张：它说此困难属于彼情形，而非偶然。"}]},"examples":[{"en":"Pneumonia is a serious complication of flu.","cn":"肺炎是流感的严重并发症。"},{"en":"The delay added another complication to the schedule.","cn":"延误给日程增加了又一个复杂因素。"},{"en":"The plot's complications are resolved in the final chapter.","cn":"情节的纠葛在最后一章得到解决。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“康普利克申”——把简单的事折（plicare）成一团 → complication 复杂化/并发症","word":"complication"},"root":"complicate（拉丁 complicare“折在一起”= com-“一起”+ plicare“折叠”）+ -ation；与 complex（plectere“编织”）不同根。","sensesIntro":{"en":"Nine senses of complication: a medical secondary condition, an act of making harder, a plot tangle, an added factor, over-complication, a postoperative problem, an unforeseen difficulty, a chess tangle, and the rare literal folding. All are folds added to a simpler line.","cn":"complication 的九个义项：并发症、使复杂化、情节纠葛、附加因素、过度复杂化、术后问题、意外困难、棋局复杂、罕见的字面折叠。它们都是加到更简单线路上的折口。"},"semanticMap":{"core":{"en":"CORE IMAGE: a straight surgical line folded into a knot by a sudden branch.","cn":"核心意象：一条笔直的手术线被突然的岔口折成死结。"},"chain":["START WITH A SIMPLE LINE","ADD ANOTHER PART","FOLD THEM TOGETHER","THE PATH TANGLES","A NEW PROBLEM APPEARS","IT MUST BE UNFOLDED"],"branches":[{"senses":"S1 · S6","en":"THE BODY: secondary conditions and postoperative problems follow from illness or treatment.","cn":"身体：继发状况与术后问题由疾病或治疗引出。"},{"senses":"S2 · S5","en":"THE ACT: making harder, and over-complication beyond need, are judgements about added folds.","cn":"动作：使更难与超出需要的复杂化，都是对附加折口的判断。"},{"senses":"S3 · S7 · S8","en":"THE STORY AND THE PLAN: plot tangles, surprises, and chess complications change the calculation.","cn":"故事与计划：情节纠葛、意外与棋局复杂都改变计算。"},{"senses":"S4","en":"THE FACTOR: a countable extra condition enters the situation.","cn":"因素：一个可数的额外条件进入情形。"},{"senses":"S9","en":"THE ROOT: the literal folding together is the image all the other senses inherit.","cn":"词根：字面的折在一起，是其余义项继承的意象。"}]},"affixes":{"intro":{"en":"Complication is complicate + -ation. Complicate is Latin complicare, com- plus plicare 'fold'. The family includes complicated, complicating, and uncomplicated; the same plicare root gives explicit, implicate, and multiply.","cn":"complication 是 complicate 加 -ation。complicate 是拉丁 complicare（com- 加 plicare“折叠”）。词族含 complicated、complicating、uncomplicated；同一 plicare 词根给出 explicit、implicate、multiply。"},"latinIntro":{"en":"Latin plicare 'fold' gives complicare 'fold together' and complicatio 'a folding'. English keeps -ation, -ed, and -ing on the stem. The parallel root plectere 'weave' gives complex, a different image and a different family.","cn":"拉丁 plicare“折叠”给出 complicare“折在一起”与 complicatio“折叠”。英语在词干上保留 -ation、-ed、-ing。平行词根 plectere“编织”给出 complex，意象与词族都不同。"},"items":[{"word":"complicates","structure":"complicate + -s (3sg)","meaning":"makes more difficult","meaningCN":"使复杂（三单）","example":"the rule complicates hiring","exampleCN":"该规则使招聘更复杂"},{"word":"complicated","structure":"complicate + -ed (past/participle)","meaning":"made tangled; hard to understand","meaningCN":"复杂的；棘手的","example":"a complicated process","exampleCN":"复杂流程"},{"word":"complicating","structure":"complicate + -ing (participle)","meaning":"making something harder","meaningCN":"使复杂化的","example":"a complicating factor","exampleCN":"复杂化因素"},{"word":"complication","structure":"complicate + -ation (noun)","meaning":"an added difficulty or secondary condition","meaningCN":"并发症；复杂化（-ation 名词）","example":"a postoperative complication","exampleCN":"术后并发症"},{"word":"complications","structure":"complication + -s (plural)","meaning":"several added problems","meaningCN":"多种复杂情况（复数）","example":"legal complications","exampleCN":"法律纠葛"},{"word":"complicacy","structure":"complicate + -acy (rare noun)","meaning":"the state of being complicated","meaningCN":"复杂状态（罕见名词）","example":"the complicacy of the case","exampleCN":"案件的复杂"},{"word":"uncomplicated","structure":"un- + complicated (negative)","meaning":"simple; without secondary problems","meaningCN":"不复杂的；无并发症的","example":"an uncomplicated recovery","exampleCN":"顺利的康复"},{"word":"explicit","structure":"ex- + plicare (same root)","meaning":"unfolded and fully stated","meaningCN":"明确的（同根）","example":"explicit consent","exampleCN":"明确同意"},{"word":"implicate","structure":"im- + plicare (same root)","meaning":"to fold in, involve","meaningCN":"牵连；暗含（同根）","example":"implicate a colleague","exampleCN":"牵连同事"}],"latinEntries":[{"word":"plicare","structure":"Latin verb","meaning":"to fold, bend","meaningCN":"折叠；弯曲"},{"word":"complicare","structure":"com- + plicare","meaning":"to fold together","meaningCN":"折在一起"},{"word":"complicatio","structure":"complicare + -tio","meaning":"a folding together","meaningCN":"折叠；复杂"},{"word":"explicare","structure":"ex- + plicare","meaning":"to unfold, explain","meaningCN":"展开；解释"}]}},{"word":"composition","ipa_uk":"/ˌkɒmpəˈzɪʃn/","ipa_us":"/ˌkɑːmpəˈzɪʃn/","definition_zh":"组成；构成；成分；作文；作曲；作品；构图；化合物；（印刷）排版；和解协议","definition_en":"the parts or ingredients that make up something; the act of putting things together; a written or musical work; the arrangement of elements in an image","core_image":"不同的颜料被一笔笔放到画布上，最后成为一幅有结构的画","scene":"这篇作文的优点是结构清楚：开头、论证、反例、结论，各占其位。The strength of this composition is its clear structure: opening, argument, counter-example and conclusion each hold their place.","sceneCN":"这里 composition 是「作文、写作作品」（第 2 个义项：学生或作者写成的文章）；句意：这篇作文的优点是结构清楚：开头、论证、反例、结论各占其位。图中可辨识物件：稿纸、钢笔、画布与颜料、乐谱、结构提纲。","pos":[{"tag":"n.","zh":"组成；构成；成分；作品；作文"},{"tag":"n.","zh":"作曲；构图；排版；和解协议"}],"collocations":[{"phrase":"the composition of the atmosphere","zh":"大气的成分"},{"phrase":"a musical composition","zh":"音乐作品"},{"phrase":"write a composition","zh":"写一篇作文"},{"phrase":"chemical composition","zh":"化学组成"},{"phrase":"composition and structure","zh":"组成与结构"},{"phrase":"reach a composition with creditors","zh":"与债权人达成和解"}],"forms":[{"label":"复数","form":"compositions"},{"label":"动词","form":"compose"},{"label":"形容词","form":"compositional"},{"label":"施事名词","form":"composer"}],"derivatives":[{"word":"compose","pos":"v.","zh":"组成；创作；使平静"},{"word":"composer","pos":"n.","zh":"作曲家"},{"word":"compositional","pos":"adj.","zh":"构成的；构图的"},{"word":"composite","pos":"adj./n.","zh":"复合的；复合材料"},{"word":"component","pos":"n.","zh":"组成部分"}],"senses":[{"no":"01","title":"The parts that make something up","titleCN":"组成；成分","definition":"the parts or ingredients of which something consists","definitionCN":"某物由以构成的各部分或成分","example":"the composition of the atmosphere","exampleCN":"大气的成分","why":"This is the analytic sense: the whole is asked to give an account of its parts. It is not the act of making but the make-up that results, and it is usually stated in percentages or proportions.","whyCN":"这是分析义：要求整体交代其部分。它不是制造动作，而是由此形成的构成，通常以百分比或比例陈述。"},{"no":"02","title":"A written exercise","titleCN":"作文","definition":"a short piece of writing done as an exercise, especially by a student","definitionCN":"作为练习写成的短篇文章，尤指学生所作","example":"She wrote a composition on her hometown.","exampleCN":"她写了一篇关于家乡的作文。","why":"School usage narrows the word to a set task. The composition is judged on organization as much as content, which is why the same noun also names the arrangement of parts.","whyCN":"学校用法把词收窄为规定任务。作文既评内容也评组织，故同一名词也指部分的安排。"},{"no":"03","title":"A musical work","titleCN":"（音乐）作品；作曲","definition":"a piece of music, or the art of writing one","definitionCN":"一部音乐作品，或写作音乐的艺术","example":"The symphony is his finest composition.","exampleCN":"这部交响曲是他最好的作品。","why":"Music turns 'putting together' into an art: notes, rhythms, and sections are composed into a whole. The composer is literally one who puts together, and the work is the result.","whyCN":"音乐把“放在一起”变成艺术：音符、节奏与段落被组合成整体。composer 字面即“组合者”，作品是结果。"},{"no":"04","title":"Arrangement in an image","titleCN":"构图","definition":"the arrangement of elements within a picture or photograph","definitionCN":"画面或照片中各元素的安排","example":"The photograph's composition leads the eye to the door.","exampleCN":"这张照片的构图把视线引向门口。","why":"Visual art uses the word for the deliberate placement of forms. Composition is not the subject but the order that makes the subject readable, and it can be judged apart from what is depicted.","whyCN":"视觉艺术用该词指形式的刻意布置。构图不是题材，而是使题材可读的秩序，且可脱离所画内容被评价。"},{"no":"05","title":"Chemical composition","titleCN":"化学组成；化合物","definition":"the identity and proportion of substances in a material","definitionCN":"材料中物质的种类与比例","example":"The lab analysed the water's chemical composition.","exampleCN":"实验室分析了水的化学组成。","why":"Chemistry makes the parts measurable: elements and ratios. A change of composition is a change of substance, so the word can mark a boundary between one material and another.","whyCN":"化学使部分可测：元素与比例。组成改变即物质改变，故该词可标记一种材料与另一种的边界。"},{"no":"06","title":"Typesetting","titleCN":"（印刷）排版","definition":"the arrangement of type and images on a page before printing","definitionCN":"印刷前页面中文字与图像的安排","example":"The printer checked the composition of the page.","exampleCN":"印刷工检查了页面排版。","why":"Printing is an industrial cousin of sense 04: elements are placed in a fixed frame. The word names the stage before impression, when the page is still only an arrangement.","whyCN":"印刷是第 4 义的工业表亲：元素被置于固定框内。该词命名压印之前的阶段，页面此时仍只是安排。"},{"no":"07","title":"A settlement with creditors","titleCN":"（法律）和解协议","definition":"an agreement by which a debtor pays part of a debt and the rest is discharged","definitionCN":"债务人偿还部分债务、其余被免除的协议","example":"The firm reached a composition with its creditors.","exampleCN":"该公司与债权人达成和解协议。","why":"Insolvency law uses composition for a voluntary arrangement. The parties 'compose' their differences, which links the legal sense to the older sense of settling a quarrel.","whyCN":"破产法用 composition 指自愿安排。各方“compose”其分歧，把法律义与更早的“平息争执”义连起来。"},{"no":"08","title":"Word formation by combining","titleCN":"（构词）复合","definition":"the formation of a word by joining two or more existing words","definitionCN":"把两个或更多现有词结合成新词","example":"'Blackbird' is a composition of 'black' and 'bird'.","exampleCN":"blackbird 是 black 与 bird 的复合。","why":"Linguistics uses the word for compounding. The parts remain recognizable, which distinguishes composition from derivation, where an affix is added and the base may change shape.","whyCN":"语言学用该词指复合构词。各部分仍可辨识，这区别于加缀派生——后者加词缀，词基可能变形。"},{"no":"09","title":"A whole work of art","titleCN":"作品整体","definition":"a complete artistic or literary work considered as an integrated whole","definitionCN":"被视为整合整体的完整艺术或文学作品","example":"The composition balances light and shadow.","exampleCN":"这幅作品平衡了光与影。","why":"The sense shifts from the act to the finished object. A composition is judged as a whole, and its quality lies in the relation of parts rather than in any part alone.","whyCN":"此义从动作转向成品。作品作为整体被评价，其质量在部分关系中，而非任何单独部分。"}],"etymology":{"intro":{"en":"Composition is compose plus -ition, from Latin compositio. Compose comes from Old French composer 'put together', from Latin componere, com- 'together' plus ponere 'place'. The literal image is placing things side by side into one arrangement. The same stem gives component, composite, and compost; compost looks like a close relative and is one, but it took a separate path through 'mixed dung' to its modern garden sense.","cn":"composition 是 compose 加 -ition，出自拉丁 compositio。compose 出自古法语 composer“放在一起”，源于拉丁 componere，即 com-“一起”加 ponere“放置”。字面意象是把事物并排放成一个安排。同一词干给出 component、composite 与 compost；compost 看似近亲且确为近亲，但它经“混合粪肥”走上另一条路，才到现代园艺义。"},"items":[{"era":"LATIN","en":"ponere means 'to place, put'; it gives component, deposit, impose, and postpone.","cn":"ponere 意为“放置、放”，给出 component、deposit、impose、postpone。"},{"era":"LATIN","en":"componere is com- 'together' plus ponere: to put several things into one place or order.","cn":"componere 是 com-“一起”加 ponere：把数物放到一处或一个秩序中。"},{"era":"LATIN","en":"compositio 'a putting together, arrangement' is the action noun behind English composition.","cn":"compositio“放在一起、安排”是英语 composition 背后的动作名词。"},{"era":"OLD FRENCH","en":"Old French composer broadens the verb to arranging, writing, and settling, and English takes it in the 14C.","cn":"古法语 composer 把动词拓宽到安排、写作与平息，英语于十四世纪引入。"},{"era":"18C","en":"The musical sense 'a piece composed' becomes established, along with composer for the writer of music.","cn":"十八世纪“写成的乐曲”义确立，composer 也固定指音乐写作者。"},{"era":"MODERN","en":"Chemistry, printing, law, and linguistics each fix a technical sense, while the school 'composition' remains the everyday one.","cn":"化学、印刷、法律与语言学各固定一个技术义，学校“作文”仍是日常义。"}]},"similar":{"note":{"en":"The first group is the compose family, including the look-alike compost; the second is words for make-up and arrangement, which differ in whether they name parts, structure, or the finished work.","cn":"第一组是 compose 词族，含近形词 compost；第二组是“构成与安排”类词，差别在于指部分、结构还是成品。"},"groups":[{"heading":"WORD FAMILY","entries":[{"word":"compose","ipa":"/kəmˈpəʊz/","tag":"verb","definition":"to put together; to write music or text; to calm oneself.","definitionCN":"组成；创作；使平静。"},{"word":"composer","ipa":"/kəmˈpəʊzə/","tag":"person noun","definition":"one who writes music.","definitionCN":"作曲家。"},{"word":"composite","ipa":"/kəmˈpɒzɪt/","tag":"adjective/noun","definition":"made of separate parts combined; a combined whole.","definitionCN":"复合的；合成物。"}]},{"heading":"NEAR MEANING","entries":[{"word":"structure","ipa":"/ˈstrʌktʃə/","tag":"noun","definition":"the arrangement and relation of parts. It stresses organization rather than ingredients.","definitionCN":"部分的安排与关系。强调组织，而非成分。"},{"word":"make-up","ipa":"/ˈmeɪkʌp/","tag":"noun","definition":"the composition or character of something, often informal.","definitionCN":"某物的构成或性质，常口语。"},{"word":"arrangement","ipa":"/əˈreɪndʒmənt/","tag":"noun","definition":"the way things are placed or ordered. It is the act or result of placing, without the chemical or artistic weight.","definitionCN":"事物被放置或排序的方式。是放置的动作或结果，不带化学或艺术分量。"}]}]},"mnemonics":{"normalIntro":{"en":"Real links: ponere 'place', componere 'put together', compositio, and the separate path of compost.","cn":"真实联系：ponere“放置”、componere“放在一起”、compositio，以及 compost 的独立路径。"},"normal":[{"en":"Componere is 'place together'. Composition is the placing, and then the thing placed.","cn":"componere 是“放在一起”。composition 先是放置动作，后是放成之物。"},{"en":"Ponere 'place' is visible in component, deposit, and postpone; all are about putting somewhere.","cn":"ponere“放置”见于 component、deposit、postpone；全都关于放到某处。"},{"en":"The composer puts notes together; the student puts sentences together. One noun covers both.","cn":"作曲家把音符放在一起；学生把句子放在一起。一个名词覆盖两者。"},{"en":"Compost is a relative that went to the garden: same 'put together', but through mixed organic matter.","cn":"compost 是去了菜园的亲戚：同样“放在一起”，但经由混合有机物。"},{"en":"A composition is judged as a whole; its quality is in the relations, not the parts.","cn":"作品作为整体被评价；质量在关系中，不在部分里。"}],"abstract":[{"en":"Composition is both an act and a result, which is why the same word can name a process, a text, and a material's make-up.","cn":"composition 既是动作也是结果，故同一词可命名过程、文本与材料构成。"},{"en":"Every whole is a claim about which parts matter and how they should be ordered.","cn":"每个整体都是关于“哪些部分重要、应如何排序”的主张。"},{"en":"A composition can be analysed into parts, but its effect often disappears when it is; the whole is not the sum.","cn":"作品可被分析为部分，但其效果常在分析中消失；整体不是总和。"}]},"examples":[{"en":"The composition of the soil affects what will grow.","cn":"土壤的组成影响能种什么。"},{"en":"He wrote a composition about his first trip abroad.","cn":"他写了一篇关于初次出国的作文。"},{"en":"The painting's composition places the figure off-centre.","cn":"这幅画的构图把人物放在偏离中心处。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“康波吉申”——把零件 com 一起 pose（放）好 → composition 组成/作品","word":"composition"},"root":"compose（古法语 composer ← 拉丁 componere“放在一起”= com-“一起”+ ponere“放置”）+ -ition（拉丁 compositio）。","sensesIntro":{"en":"Nine senses of composition: make-up, a school essay, a musical work, visual arrangement, chemical content, typesetting, a creditors' settlement, word compounding, and a finished whole. The thread is placing parts into an order.","cn":"composition 的九个义项：构成、作文、音乐作品、构图、化学组成、排版、债权人和解、复合构词、完整作品。共同线索是把部分放入一个秩序。"},"semanticMap":{"core":{"en":"CORE IMAGE: pigments laid stroke by stroke onto a canvas until an ordered picture appears.","cn":"核心意象：颜料一笔笔落到画布上，直到出现有秩序的画。"},"chain":["TAKE THE PARTS","PLACE THEM TOGETHER","FIX A PROPORTION","MAKE AN ARRANGEMENT","PRODUCE A WHOLE","JUDGE THE WHOLE"],"branches":[{"senses":"S1 · S5","en":"THE MAKE-UP: atmospheric and chemical composition ask what parts, in what ratio.","cn":"构成：大气与化学组成问的是哪些部分、何种比例。"},{"senses":"S2 · S3 · S9","en":"THE WORK: essay, music, and finished art are arrangements made to be read or heard as wholes.","cn":"作品：作文、音乐与成品艺术都是作为整体被读或听的安排。"},{"senses":"S4 · S6","en":"THE FRAME: painting and typesetting place elements inside a fixed visual field.","cn":"框：绘画与排版把元素放进固定视觉场。"},{"senses":"S7","en":"THE SETTLEMENT: parties compose their differences by arranging a payment.","cn":"和解：各方通过安排偿付来 compose 分歧。"},{"senses":"S8","en":"THE WORD: compounding puts existing words together into a new one.","cn":"词：复合把现有词放在一起成新词。"}]},"affixes":{"intro":{"en":"Composition is compose + -ition, from Latin compositio. Compose is componere, com- plus ponere 'place'. The family includes composer, compositional, composite, component, and the look-alike compost; all inherit the 'put together' image.","cn":"composition 是 compose 加 -ition，出自拉丁 compositio。compose 是 componere（com- 加 ponere“放置”）。词族含 composer、compositional、composite、component 与近形词 compost；都继承“放在一起”的意象。"},"latinIntro":{"en":"Latin ponere 'place' gives componere 'put together' and compositio 'arrangement'. English keeps -ition and builds composer, composite, and component on related stems. Compost comes through Old French compost from compositum, but its sense narrowed to mixed organic matter.","cn":"拉丁 ponere“放置”给出 componere“放在一起”与 compositio“安排”。英语保留 -ition，并在相关词干上造 composer、composite、component。compost 经古法语 compost 出自 compositum，但词义收窄为混合有机物。"},"items":[{"word":"composes","structure":"compose + -s (3sg)","meaning":"puts together","meaningCN":"组成（三单）","example":"she composes music","exampleCN":"她作曲"},{"word":"composed","structure":"compose + -ed (past/participle)","meaning":"put together; also 'calm'","meaningCN":"组成了；也指“镇定”","example":"composed of three parts","exampleCN":"由三部分构成"},{"word":"composing","structure":"compose + -ing (participle)","meaning":"in the act of putting together","meaningCN":"组成中的","example":"composing a letter","exampleCN":"写一封信"},{"word":"composition","structure":"compose + -ition (noun)","meaning":"a putting together; a work","meaningCN":"组成；作品（-ition 名词）","example":"a musical composition","exampleCN":"音乐作品"},{"word":"compositional","structure":"composition + -al (adjective)","meaning":"relating to composition","meaningCN":"构成的；构图的（-al 形容词）","example":"compositional balance","exampleCN":"构图平衡"},{"word":"composer","structure":"compose + -er (agent noun)","meaning":"one who composes, especially music","meaningCN":"作曲家（-er 施事）","example":"a film composer","exampleCN":"电影作曲家"},{"word":"composite","structure":"componere + -ite (adjective)","meaning":"made of combined parts","meaningCN":"复合的（-ite 形容词）","example":"a composite material","exampleCN":"复合材料"},{"word":"component","structure":"componere + -ent (noun)","meaning":"a part of a larger whole","meaningCN":"组成部分（-ent 名词）","example":"a key component","exampleCN":"关键部件"},{"word":"compost","structure":"compositum via Old French (noun)","meaning":"mixed organic matter for soil","meaningCN":"堆肥（同源，词义窄化）","example":"garden compost","exampleCN":"园圃堆肥"}],"latinEntries":[{"word":"ponere","structure":"Latin verb","meaning":"to place, put","meaningCN":"放置"},{"word":"componere","structure":"com- + ponere","meaning":"to put together","meaningCN":"放在一起"},{"word":"compositio","structure":"componere + -tio","meaning":"a putting together, arrangement","meaningCN":"安排；组合"},{"word":"compositus","structure":"past participle of componere","meaning":"put together, composite","meaningCN":"被组合的"}]}},{"word":"concentration","ipa_uk":"/ˌkɒnsnˈtreɪʃn/","ipa_us":"/ˌkɑːnsnˈtreɪʃn/","definition_zh":"专注；集中；浓度；浓缩；集中度；富集；（权力）集中","definition_en":"the act of focusing attention or bringing things to one point; the amount of a substance in a given volume or mixture; the degree to which something is gathered in one place","core_image":"散落各处的铁屑被一块磁铁吸到同一点，越聚越密","scene":"实验室里他盯着滴定管，任何一点分神都会让读数偏掉。In the lab he watches the burette without blinking, because reading it takes total concentration.","sceneCN":"这里 concentration 是「专注、集中注意力」（第 1 个义项：把心思聚到一点的能力或状态）；句意：他盯着滴定管不敢眨眼，因为读取它需要全神贯注。图中可辨识物件：滴定管、锥形瓶、磁铁与铁屑、秒表、实验记录本。","pos":[{"tag":"n.","zh":"专注；集中；浓度；浓缩；集中度"}],"collocations":[{"phrase":"concentration of power","zh":"权力的集中"},{"phrase":"high concentration","zh":"高浓度"},{"phrase":"lose concentration","zh":"失去专注"},{"phrase":"concentration camp","zh":"集中营"},{"phrase":"market concentration","zh":"市场集中度"},{"phrase":"concentration of pollutants","zh":"污染物浓度"}],"forms":[{"label":"复数","form":"concentrations"},{"label":"动词","form":"concentrate"},{"label":"形容词","form":"concentrated"},{"label":"形容词","form":"concentrative"}],"derivatives":[{"word":"concentrate","pos":"v./n.","zh":"集中；浓缩；浓缩物"},{"word":"concentrated","pos":"adj.","zh":"集中的；浓缩的"},{"word":"concentrative","pos":"adj.","zh":"集中性的"},{"word":"concentrator","pos":"n.","zh":"浓缩器；选矿机"}],"senses":[{"no":"01","title":"Focused attention","titleCN":"专注；集中注意力","definition":"the ability or state of directing the mind to one task","definitionCN":"把心思指向一项任务的能力或状态","example":"The noise broke her concentration.","exampleCN":"噪声打断了她的专注。","why":"This is the mental sense: attention is gathered from many possible objects onto one. It is a resource that can be spent, broken, and trained, which is why it appears with 'lose' and 'require'.","whyCN":"这是心智义：注意力从许多可能对象聚到一个。它是可消耗、可打断、可训练的资，故常与 lose、require 连用。"},{"no":"02","title":"Strength of a solution","titleCN":"浓度","definition":"the amount of a dissolved substance in a given amount of liquid or mixture","definitionCN":"一定量液体或混合物中溶解物质的量","example":"The concentration of salt in the brine is 20 percent.","exampleCN":"卤水中盐的浓度为百分之二十。","why":"Chemistry makes the gathering quantitative: more solute in the same volume means higher concentration. The word shifts from the act of gathering to the measured result of that gathering.","whyCN":"化学使聚集定量：同体积中溶质更多即浓度更高。该词从聚集动作转向聚集的测量结果。"},{"no":"03","title":"Gathering of people or forces","titleCN":"集中（人力/兵力）","definition":"the act of bringing people or military forces into one place","definitionCN":"把人或兵力带到一处的行为","example":"The concentration of troops near the border alarmed neighbours.","exampleCN":"边境附近的兵力集中令邻国警觉。","why":"Military and political usage keeps the physical image: scattered units are brought to one point. Such concentration is read as preparation, and therefore as a signal, whether or not one is intended.","whyCN":"军事与政治用法保留物理意象：分散单位被带到一点。此种集中被读作准备，因而成为信号，无论是否有意。"},{"no":"04","title":"Reduction to a denser form","titleCN":"浓缩","definition":"the process of removing water or diluent to make something denser","definitionCN":"去除水或稀释剂使某物更浓的过程","example":"The juice is made by concentration under low heat.","exampleCN":"该果汁经低温浓缩制成。","why":"Industry uses the noun for a process, not a state. The volume falls while the amount of substance stays, so concentration rises; the word names the operation that produces the ratio.","whyCN":"工业用该名词指过程，而非状态。体积下降而物质量不变，故浓度上升；该词命名产生此比值的操作。"},{"no":"05","title":"Market concentration","titleCN":"市场集中度","definition":"the extent to which an industry is dominated by a few large firms","definitionCN":"一个行业被少数大公司主导的程度","example":"The merger raised market concentration.","exampleCN":"该合并提高了市场集中度。","why":"Economics measures concentration with shares and indices. High concentration can bring efficiency or market power, and the same number supports both stories, which is why the word is politically loaded.","whyCN":"经济学用份额与指数衡量集中度。高集中度可带来效率或市场势力，同一数字支持两种叙事，故该词带政治负荷。"},{"no":"06","title":"Ore concentration","titleCN":"富集；选矿","definition":"the process of separating valuable minerals from waste rock","definitionCN":"把有用矿物与废石分离的过程","example":"Ore concentration reduces the volume before smelting.","exampleCN":"选矿在冶炼前减小体积。","why":"Mining uses concentration for upgrading a low-grade ore. The valuable part is gathered and the gangue discarded, so the word means both 'bring together' and 'purify by removing'.","whyCN":"矿业用 concentration 指提高低品位矿石。有用部分被聚集，脉石被丢弃，故该词同时意味着“聚起”与“去杂提纯”。"},{"no":"07","title":"Pollutant concentration","titleCN":"（污染物）浓度","definition":"the measured amount of a pollutant in air, water, or soil","definitionCN":"空气、水或土壤中污染物的测量量","example":"Airborne particle concentration exceeded the limit.","exampleCN":"空气中颗粒物浓度超过限值。","why":"Environmental science uses the same quantitative sense as chemistry, but the number is a regulatory object: a threshold triggers action. Concentration here is not neutral description but a measure of harm.","whyCN":"环境科学用与化学相同的定量义，但数字是监管对象：阈值触发行动。此处浓度不是中性描述，而是危害度量。"},{"no":"08","title":"Concentration of power","titleCN":"（权力）集中","definition":"the gathering of authority into fewer hands or institutions","definitionCN":"权威聚至少数人或机构的状态","example":"The constitution limits the concentration of power.","exampleCN":"宪法限制权力的集中。","why":"Political theory uses the noun for centralization. The image is the same: many scattered powers are drawn to one centre, and the debate is whether that makes decision easier or tyranny likelier.","whyCN":"政治理论用该名词指中央化。意象相同：分散权力被吸到一个中心，争论在于这使决策更容易，还是使暴政更可能。"},{"no":"09","title":"A concentration camp","titleCN":"集中营","definition":"a place where people are detained and confined, especially by a state, without normal legal protection","definitionCN":"国家在没有正常法律保障下拘禁人的场所","example":"The term 'concentration camp' entered English from the Boer War.","exampleCN":"concentration camp 一词经布尔战争进入英语。","why":"This is the darkest offshoot: people, not substances, are concentrated. The euphemism of 'gathering' hides coercion, and the phrase now carries the memory of the Holocaust and other mass detentions.","whyCN":"这是最黑暗的分支：被集中的人，而非物质。“聚集”的委婉掩盖强制，该短语现在承载大屠杀与其他大规模拘禁的记忆。"}],"etymology":{"intro":{"en":"Concentration is concentrate plus -ation. Concentrate is formed from con- 'together' plus centrum 'centre', a word borrowed from Greek kentron 'sharp point, goad, the fixed point of a compass'. The verb is not classical Latin but a later formation (French concentrer, 17C), built on the image of bringing things to a common centre. The noun follows. The chemical sense develops in the 18C-19C; the mental sense in the 19C.","cn":"concentration 是 concentrate 加 -ation。concentrate 由 con-“一起”加 centrum“中心”构成，后者借自希腊 kentron“尖点、刺棒、圆规的定点”。该动词不是古典拉丁，而是较晚的构造（法语 concentrer，十七世纪），基于“把事物带到共同中心”的意象。名词随之而来。化学义在十八至十九世纪发展；心智义在十九世纪。"},"items":[{"era":"GREEK","en":"kentron means 'sharp point, goad', and also the fixed leg of a compass; it gives Latin centrum.","cn":"kentron 意为“尖点、刺棒”，也指圆规的固定脚；它给出拉丁 centrum。"},{"era":"LATIN","en":"centrum 'centre' is the borrowed Greek word; English centre and center descend from it.","cn":"centrum“中心”是借入的希腊词；英语 centre 与 center 由此而来。"},{"era":"17C","en":"French concentrer and English concentrate are later formations: con- 'together' plus centrum 'centre'.","cn":"法语 concentrer 与英语 concentrate 是较晚构造：con-“一起”加 centrum“中心”。"},{"era":"18C","en":"The chemical sense appears as a measured amount of substance in a solution or mixture.","cn":"十八世纪出现化学义，指溶液或混合物中物质的测量量。"},{"era":"19C","en":"The mental sense 'focused attention' develops, and the political sense of gathering power follows.","cn":"十九世纪发展出“专注”的心智义，随后出现聚集权力的政治义。"},{"era":"20C","en":"Environmental regulation and market analysis turn concentration into an index and a threshold.","cn":"二十世纪环境监管与市场分析把 concentration 变成指数与阈值。"}]},"similar":{"note":{"en":"The first group is the concentrate family; the second is words for focus and density, which differ in whether they name attention, gathering, or amount per volume.","cn":"第一组是 concentrate 词族；第二组是“专注与密度”类词，差别在于指注意力、聚集还是单位体积的量。"},"groups":[{"heading":"WORD FAMILY","entries":[{"word":"concentrate","ipa":"/kənˈsentrət/","tag":"verb/noun","definition":"to bring to one point; to focus; a concentrated substance.","definitionCN":"集中；专注；浓缩物。"},{"word":"concentrated","ipa":"/kənˈsentrətɪd/","tag":"adjective","definition":"gathered at one point; made denser.","definitionCN":"集中的；浓缩的。"},{"word":"concentrator","ipa":"/kənˈsentrətə/","tag":"noun","definition":"a device that concentrates a substance or signal.","definitionCN":"浓缩器；聚光器。"}]},{"heading":"NEAR MEANING","entries":[{"word":"focus","ipa":"/ˈfəʊkəs/","tag":"noun/verb","definition":"the centre of attention or the point where rays meet. It is more visual and less quantitative.","definitionCN":"注意力中心或光线会聚点。更视觉，少定量。"},{"word":"density","ipa":"/ˈdensəti/","tag":"noun","definition":"mass or number per unit volume. It is a ratio, not the act of gathering.","definitionCN":"单位体积的质量或数量。是比值，而非聚集动作。"},{"word":"centralization","ipa":"/ˌsentrəlaɪˈzeɪʃn/","tag":"noun","definition":"the gathering of authority into one centre. It is institutional and rarely chemical.","definitionCN":"权威聚到一个中心。制度性，少用于化学。"}]}]},"mnemonics":{"normalIntro":{"en":"Real links: centrum 'centre' from Greek kentron, con- 'together', and the shift from gathering to measuring to attention.","cn":"真实联系：centrum“中心”出自希腊 kentron、con-“一起”，以及从聚集到测量再到注意力的偏移。"},"normal":[{"en":"Concentrate is 'bring to one centre'. A crowd, a solute, and a mind can all be brought to a point.","cn":"concentrate 是“带到同一中心”。人群、溶质与心思都能被带到一点。"},{"en":"centrum comes from Greek kentron, the sharp point of a compass; the centre is where the point is fixed.","cn":"centrum 出自希腊 kentron，即圆规的尖点；中心就是尖点固定之处。"},{"en":"Chemistry measures the gathering: same volume, more solute, higher concentration.","cn":"化学测量聚集：同体积，更多溶质，更高浓度。"},{"en":"A concentration camp is the word's darkest turn: people, not substances, are gathered and confined.","cn":"集中营是该词最黑暗的转折：被聚集与拘禁的是人，不是物质。"},{"en":"'Lose concentration' treats attention as a resource that can leak; the metaphor is economic, not chemical.","cn":"lose concentration 把注意力当作会泄漏的资源；这个隐喻是经济的，不是化学的。"}],"abstract":[{"en":"Concentration is always a ratio: something gathered per some space, time, or population. Without the denominator the number means nothing.","cn":"浓度总是比值：某物聚到某空间、时间或人群。没有分母，数字无意义。"},{"en":"The same image serves focus, wealth, power, and poison; gathering can be virtue or danger depending on what is gathered.","cn":"同一意象服务专注、财富、权力与毒物；聚集可为德也可为险，取决于聚的是什么。"},{"en":"To concentrate is to choose one point and pay for it by ignoring others; every focus is also an exclusion.","cn":"集中就是选一点，并以忽略其余为代价；每次专注也是一次排除。"}]},"examples":[{"en":"The experiment requires total concentration.","cn":"这项实验需要完全专注。"},{"en":"The concentration of carbon dioxide in the room was rising.","cn":"室内二氧化碳浓度正在上升。"},{"en":"The merger increased concentration in the airline industry.","cn":"该合并提高了航空业的集中度。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“康森特雷申”——把散的东西 con 到 center（中心）→ concentration 集中/浓度","word":"concentration"},"root":"concentrate（con-“一起”+ 拉丁 centrum“中心”，源自希腊 kentron“尖点；圆规定点”）+ -ation。","sensesIntro":{"en":"Nine senses of concentration: attention, solution strength, troop gathering, condensing, market share, ore upgrading, pollutant levels, political centralization, and the camp. The invariant is many things brought to one point, measured against a denominator.","cn":"concentration 的九个义项：专注、溶液浓度、兵力集中、浓缩、市场集中度、选矿富集、污染物浓度、权力集中、集中营。不变量是把许多东西带到一点，并以分母衡量。"},"semanticMap":{"core":{"en":"CORE IMAGE: iron filings scattered on a sheet drawn to one point by a magnet.","cn":"核心意象：散在纸上的铁屑被磁铁吸到一点。"},"chain":["SCATTERED THINGS","A CENTRE APPEARS","THEY ARE DRAWN IN","DENSITY RISES","THE RATIO IS MEASURED","THE CENTRE HOLDS POWER"],"branches":[{"senses":"S1","en":"THE MIND: attention is gathered from many objects onto one task.","cn":"心：注意力从许多对象聚到一项任务。"},{"senses":"S2 · S7","en":"THE MEASURE: solution and pollutant concentrations are ratios with denominators.","cn":"测量：溶液与污染物浓度是带分母的比值。"},{"senses":"S3 · S8","en":"THE FORCE: troops and authority are brought to one point, and both are read as signals.","cn":"力量：兵力与权威被带到一点，两者都被读作信号。"},{"senses":"S4 · S6","en":"THE PROCESS: condensing and ore upgrading remove what is not wanted.","cn":"过程：浓缩与选矿去除不想要之物。"},{"senses":"S5 · S9","en":"THE MARKET AND THE CAMP: concentration can mean market power, and, at its worst, confined people.","cn":"市场与营地：集中可指市场势力，最坏时指被拘禁的人。"}]},"affixes":{"intro":{"en":"Concentration is concentrate + -ation. Concentrate is con- plus centrum 'centre', from Greek kentron. The family includes concentrated, concentrative, and concentrator; centre, center, and concentric share the same base.","cn":"concentration 是 concentrate 加 -ation。concentrate 是 con- 加 centrum“中心”，后者出自希腊 kentron。词族含 concentrated、concentrative、concentrator；centre、center、concentric 共享同一词基。"},"latinIntro":{"en":"Latin centrum 'centre' is borrowed from Greek kentron 'sharp point'. The verb concentrare is a later formation, not classical; French concentrer and English concentrate build on it. English adds -ation for the noun and -ed, -ive, -or for related forms.","cn":"拉丁 centrum“中心”借自希腊 kentron“尖点”。动词 concentrare 是较晚构造，非古典；法语 concentrer 与英语 concentrate 基于它。英语加 -ation 成名词，加 -ed、-ive、-or 成相关形式。"},"items":[{"word":"concentrates","structure":"concentrate + -s (3sg)","meaning":"brings to one point","meaningCN":"集中（三单）","example":"she concentrates on the task","exampleCN":"她专注于任务"},{"word":"concentrated","structure":"concentrate + -ed (past/participle)","meaning":"gathered; made denser","meaningCN":"集中的；浓缩的","example":"concentrated juice","exampleCN":"浓缩果汁"},{"word":"concentrating","structure":"concentrate + -ing (participle)","meaning":"in the act of gathering","meaningCN":"集中中的","example":"concentrating sunlight","exampleCN":"聚集阳光"},{"word":"concentration","structure":"concentrate + -ation (noun)","meaning":"the act or state of being concentrated","meaningCN":"集中；浓度（-ation 名词）","example":"a high concentration of salt","exampleCN":"高盐浓度"},{"word":"concentrations","structure":"concentration + -s (plural)","meaning":"several measured levels","meaningCN":"多种浓度（复数）","example":"pollutant concentrations","exampleCN":"污染物浓度"},{"word":"concentrative","structure":"concentrate + -ive (adjective)","meaning":"tending to concentrate","meaningCN":"集中性的（-ive 形容词）","example":"concentrative attention","exampleCN":"集中注意"},{"word":"concentrator","structure":"concentrate + -or (instrument)","meaning":"a device that concentrates","meaningCN":"浓缩器；选矿机（-or 工具）","example":"an oxygen concentrator","exampleCN":"制氧机"},{"word":"centre","structure":"centrum via French (noun)","meaning":"the middle point","meaningCN":"中心（同源名词）","example":"the centre of the circle","exampleCN":"圆心"},{"word":"concentric","structure":"con- + centrum + -ic (same base)","meaning":"sharing the same centre","meaningCN":"同心的（同词基）","example":"concentric circles","exampleCN":"同心圆"}],"latinEntries":[{"word":"centrum","structure":"Greek kentron borrowed into Latin","meaning":"centre, fixed point of a compass","meaningCN":"中心；圆规定点"},{"word":"concentrare","structure":"con- + centrum (later Latin)","meaning":"to bring to a centre","meaningCN":"集中到中心"},{"word":"concentratio","structure":"concentrare + -tio","meaning":"a gathering to a centre","meaningCN":"集中；浓缩"},{"word":"kentron","structure":"Greek noun","meaning":"sharp point, goad","meaningCN":"尖点；刺棒"}]}},{"word":"conceptual","ipa_uk":"/kənˈseptʃuəl/","ipa_us":"/kənˈseptʃuəl/","definition_zh":"概念上的；观念的；概念性的；概念模型的；概念设计的；概念艺术的","definition_en":"relating to concepts or mental ideas rather than to physical things or practical details","core_image":"一张画在纸上的思维草图，还没有变成实物，却已决定实物该长什么样","scene":"这个方案的早期阶段已经完成，只有框图和定义，还没有一块真正的材料。The conceptual stage of the plan is finished: there are diagrams and definitions, but not one piece of real material.","sceneCN":"这里 conceptual 是「概念阶段的、概念上的」（第 1 个义项：与概念有关，而非与实物或细节有关）；句意：这个方案的概念阶段已完成：只有框图和定义，还没有一块真正的材料。图中可辨识物件：思维导图、框图、未组装的零件、草图、标注箭头。","pos":[{"tag":"adj.","zh":"概念上的；观念的；概念性的"}],"collocations":[{"phrase":"conceptual framework","zh":"概念框架"},{"phrase":"conceptual model","zh":"概念模型"},{"phrase":"conceptual design","zh":"概念设计"},{"phrase":"conceptual art","zh":"概念艺术"},{"phrase":"conceptual understanding","zh":"概念性理解"},{"phrase":"a conceptual problem","zh":"概念上的问题"}],"forms":[{"label":"副词","form":"conceptually"},{"label":"名词","form":"concept"},{"label":"名词","form":"conception"},{"label":"动词","form":"conceptualize"}],"derivatives":[{"word":"concept","pos":"n.","zh":"概念"},{"word":"conceptually","pos":"adv.","zh":"概念上"},{"word":"conceptualize","pos":"v.","zh":"概念化"},{"word":"conceptualization","pos":"n.","zh":"概念化过程"},{"word":"conception","pos":"n.","zh":"概念；受孕"}],"senses":[{"no":"01","title":"Relating to concepts","titleCN":"概念上的；与概念有关的","definition":"concerned with ideas or general notions rather than with instances","definitionCN":"关乎观念或一般概念，而非具体实例","example":"The paper offers a conceptual analysis of rights.","exampleCN":"论文对权利作了概念分析。","why":"This is the defining sense: it marks a level of abstraction. A conceptual question asks what a term means or how ideas relate, not what happens in a particular case.","whyCN":"这是定义性义：它标记抽象层级。概念问题问的是术语何意、观念如何关联，而非某具体案例发生了什么。"},{"no":"02","title":"Abstract rather than practical","titleCN":"观念性的；抽象的","definition":"existing as an idea rather than as a physical or practical reality","definitionCN":"作为观念而非物理或实践现实存在","example":"The plan is still conceptual.","exampleCN":"该计划仍停留在概念层面。","why":"Here the adjective is a stage marker: nothing has been built. It can be neutral (early design) or critical (all talk, no implementation), depending on tone and context.","whyCN":"此处形容词是阶段标记：尚未建成。它可中性（早期设计），也可批评（全是空谈、未落地），取决于语气与语境。"},{"no":"03","title":"Conceptual art","titleCN":"概念艺术","definition":"art in which the idea or concept matters more than the finished object","definitionCN":"观念或概念比成品更重要的艺术","example":"Conceptual art often exists mainly as text.","exampleCN":"概念艺术常主要以文本存在。","why":"Art history turns the word into a movement: the artwork is the concept, and the object may be secondary or absent. This is the most radical case of 'idea before thing'.","whyCN":"艺术史把该词变成一场运动：作品即概念，实物可以次要甚至缺席。这是“观念先于实物”最激进的例子。"},{"no":"04","title":"A conceptual model","titleCN":"概念模型","definition":"a simplified representation of the ideas and relations in a system","definitionCN":"对系统中观念与关系的简化表示","example":"The team drew a conceptual model before coding.","exampleCN":"团队在编码前画了概念模型。","why":"Modelling uses the adjective for a map of meanings, not of measurements. A conceptual model says which entities and relations matter; a computational model then makes them precise.","whyCN":"建模用该形容词指意义地图，而非测量地图。概念模型说明哪些实体与关系重要；计算模型随后把它们精确化。"},{"no":"05","title":"Conceptual design","titleCN":"概念设计","definition":"the early phase of design in which the main idea and constraints are fixed","definitionCN":"设计早期阶段，主要想法与约束在此确定","example":"Conceptual design precedes detailed engineering.","exampleCN":"概念设计先于详细工程。","why":"Design practice separates phases. The conceptual phase decides what problem is being solved and what counts as a good solution; later phases decide dimensions and materials.","whyCN":"设计实践区分阶段。概念阶段决定要解决什么问题、什么算好方案；后续阶段决定尺寸与材料。"},{"no":"06","title":"A conceptual framework","titleCN":"概念框架","definition":"the set of concepts and assumptions used to organize a study or argument","definitionCN":"用于组织研究或论证的概念与假设集合","example":"The study lacks a clear conceptual framework.","exampleCN":"该研究缺少清晰的概念框架。","why":"Research methods use the phrase for the scaffolding of inquiry. The framework is not data; it is the grid through which data become visible as evidence.","whyCN":"研究方法用该短语指探究的脚手架。框架不是数据；它是使数据显现为证据的网格。"},{"no":"07","title":"A conceptual problem","titleCN":"概念上的问题","definition":"a difficulty in the meaning or logic of an idea rather than in its execution","definitionCN":"出在观念的意义或逻辑、而非执行上的困难","example":"The proposal has a conceptual flaw.","exampleCN":"该提案有概念上的缺陷。","why":"This sense diagnoses where a problem lives. A conceptual problem cannot be fixed by better engineering, because the categories themselves are wrong or inconsistent.","whyCN":"此义诊断问题所在。概念问题不能靠更好的工程解决，因为范畴本身错误或不一致。"},{"no":"08","title":"Conceptual understanding","titleCN":"概念性理解","definition":"grasping the principles and relations of a subject, not just procedures","definitionCN":"掌握学科的原理与关系，而不只是步骤","example":"Students need conceptual understanding, not only drills.","exampleCN":"学生需要概念性理解，而不只是操练。","why":"Education uses the adjective to distinguish knowing why from knowing how. A student can perform a procedure and still lack conceptual understanding if they cannot explain why it works.","whyCN":"教育用该形容词区分“知为何”与“知如何”。学生能执行步骤却讲不出为何有效，仍缺概念性理解。"},{"no":"09","title":"Conceptual vocabulary","titleCN":"概念词汇","definition":"the set of terms that name the ideas of a field","definitionCN":"命名某领域观念的术语集合","example":"The glossary defines the conceptual vocabulary of the field.","exampleCN":"术语表界定了该领域的概念词汇。","why":"This metalinguistic sense names the words that carry concepts. A field's conceptual vocabulary is its toolkit; disputes about terms are often disputes about the ideas themselves.","whyCN":"这一元语言义命名承载概念的词。领域的概念词汇就是其工具箱；术语之争常是观念之争。"}],"etymology":{"intro":{"en":"Conceptual is concept plus -ual. Concept comes from Latin conceptus, 'a taking in, a conception', from concipere 'to take in, receive, conceive', itself com- 'together' plus capere 'to take, seize'. The suffix -ual is Latin -ualis, 'relating to'. So conceptual literally means 'relating to a concept'. Note the pair conceptual / conceptional: both exist, but conceptional usually belongs to conception, including biological conception, while conceptual belongs to concept, the idea.","cn":"conceptual 是 concept 加 -ual。concept 出自拉丁 conceptus“摄入、构想”，源于 concipere“摄入、接受、构想”，即 com-“一起”加 capere“拿、抓”。后缀 -ual 是拉丁 -ualis“与…有关的”。故 conceptual 字面即“与概念有关的”。注意 conceptual / conceptional 这一对：两者都存在，但 conceptional 通常属于 conception（包括生物学受孕），conceptual 属于 concept（观念）。"},"items":[{"era":"LATIN","en":"capere means 'to take, seize, grasp'; it gives capture, captive, and the -ceive verbs.","cn":"capere 意为“拿、抓、握”，给出 capture、captive 与 -ceive 系列动词。"},{"era":"LATIN","en":"concipere is com- 'together' plus capere: to take in, receive, and hence to conceive an idea or a child.","cn":"concipere 是 com-“一起”加 capere：摄入、接受，故构想观念或怀胎。"},{"era":"LATIN","en":"conceptus, its past participle, means 'conceived, a conception'; English concept keeps the mental thing, not the act.","cn":"其过去分词 conceptus 意为“被构想的、构想”；英语 concept 保留心智之物，而非动作。"},{"era":"LATIN","en":"conceptualis adds -ualis 'relating to' to conceptus; English -ual continues this suffix.","cn":"conceptualis 在 conceptus 上加 -ualis“与…有关”；英语 -ual 延续该后缀。"},{"era":"19C","en":"Conceptual becomes common in philosophy and psychology for what belongs to ideas rather than things.","cn":"十九世纪 conceptual 在哲学与心理学中常见，指属于观念而非事物者。"},{"era":"20C","en":"Design, art, and education adopt it for early phases, idea-driven works, and understanding of principles.","cn":"二十世纪设计、艺术与教育采用它，指早期阶段、观念驱动作品与原理性理解。"}]},"similar":{"note":{"en":"The first group is the concept family; the second is adjectives of abstraction, which differ in whether they mean idea-level, theoretical, or merely not physical.","cn":"第一组是 concept 词族；第二组是抽象形容词，差别在于指观念层面、理论性还是仅非物理。"},"groups":[{"heading":"WORD FAMILY","entries":[{"word":"concept","ipa":"/ˈkɒnsept/","tag":"noun","definition":"a general idea or category formed in the mind.","definitionCN":"在心中形成的一般观念或范畴。"},{"word":"conception","ipa":"/kənˈsepʃn/","tag":"noun","definition":"the act of forming an idea; also biological conception.","definitionCN":"形成观念的动作；也指生物学受孕。"},{"word":"conceptualize","ipa":"/kənˈseptʃuəlaɪz/","tag":"verb","definition":"to form a concept of something.","definitionCN":"形成关于某物的概念。"}]},{"heading":"NEAR MEANING","entries":[{"word":"theoretical","ipa":"/θɪəˈretɪkl/","tag":"adjective","definition":"based on theory rather than practice; it may still be testable.","definitionCN":"基于理论而非实践；仍可被检验。"},{"word":"abstract","ipa":"/ˈæbstrækt/","tag":"adjective","definition":"existing as an idea apart from particular things. It is broader and more philosophical.","definitionCN":"作为脱离具体事物的观念存在。更广、更哲学。"},{"word":"notional","ipa":"/ˈnəʊʃənl/","tag":"adjective","definition":"existing only in thought or as a notion; often hypothetical.","definitionCN":"仅存在于思想或观念中；常为假设的。"}]}]},"mnemonics":{"normalIntro":{"en":"Real links: capere 'take', concipere 'take in', conceptus, and the -ual suffix meaning 'relating to'.","cn":"真实联系：capere“拿”、concipere“摄入”、conceptus，以及表“与…有关”的 -ual 后缀。"},"normal":[{"en":"Concept is what the mind has 'taken in' (con-cipere). Conceptual is the adjective of that taken-in idea.","cn":"concept 是心智“摄入”（con-cipere）之物。conceptual 是那被摄入观念的形容词。"},{"en":"The -ual suffix means 'relating to', exactly as in manual, sensual, and conceptual.","cn":"-ual 后缀意为“与…有关”，正如 manual、sensual、conceptual。"},{"en":"Conceptual and conceptional are not interchangeable: conceptional usually means 'of conception', including pregnancy.","cn":"conceptual 与 conceptional 不可互换：conceptional 通常指“受孕的、构想的”，包括怀孕。"},{"en":"Conceptual art makes the idea the artwork; the object can be a receipt or a sentence.","cn":"概念艺术把观念当作作品；实物可以是一张收据或一句话。"},{"en":"A conceptual problem cannot be engineered away; the categories themselves are wrong.","cn":"概念问题不能靠工程消除；范畴本身错了。"}],"abstract":[{"en":"The conceptual level is where categories are chosen, and categories decide what can be seen as evidence afterwards.","cn":"概念层面是选择范畴之处，而范畴决定此后什么能作为证据被看见。"},{"en":"Calling a plan 'merely conceptual' can praise its clarity or dismiss its lack of reality; the adjective is a site of evaluation.","cn":"称计划“只是概念上的”，既可赞其清晰，也可贬其不实；该形容词是评价场。"},{"en":"Every discipline is held together by a conceptual vocabulary, and fights over words are fights over the world those words cut.","cn":"每个学科由概念词汇维系，词语之争即这些词所切割的世界之争。"}]},"examples":[{"en":"The proposal is still at the conceptual stage.","cn":"该提案仍处于概念阶段。"},{"en":"She has a strong conceptual understanding of physics.","cn":"她对物理有很强的概念性理解。"},{"en":"The gallery specialises in conceptual art.","cn":"该画廊专营概念艺术。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“康塞普秋尔”——先有 concept（概念），才有 conceptual（概念的）→ 概念上的","word":"conceptual"},"root":"concept（拉丁 conceptus ← concipere“摄入、构想”= com-“一起”+ capere“拿”）+ -ual（拉丁 -ualis“与…有关”）。","sensesIntro":{"en":"Nine senses of conceptual: relating to concepts, abstract rather than built, idea-driven art, a model of meanings, early design, a research framework, a flaw in categories, understanding of principles, and a field's term set. All mark the level of ideas.","cn":"conceptual 的九个义项：与概念有关、抽象未落地、观念艺术、意义模型、早期设计、研究框架、范畴缺陷、原理性理解、领域术语集。它们都标记观念层级。"},"semanticMap":{"core":{"en":"CORE IMAGE: a mind-map on paper that decides what the physical thing will later be.","cn":"核心意象：纸上的思维草图，决定实物此后该是什么样。"},"chain":["TAKE AN IDEA IN","NAME THE CATEGORY","RELATE THE PARTS","MAP THE RELATIONS","FIX THE DESIGN","JUDGE AT THE LEVEL OF IDEAS"],"branches":[{"senses":"S1 · S7 · S9","en":"THE IDEA: analysis, flaw, and vocabulary all operate on concepts themselves.","cn":"观念：分析、缺陷与词汇都作用于概念本身。"},{"senses":"S2 · S3","en":"THE ABSTRACTION: unbuilt plans and conceptual art put the idea before the object.","cn":"抽象：未建的计划与概念艺术把观念放在实物之前。"},{"senses":"S4 · S6","en":"THE FRAMEWORK: models and research frameworks map which relations matter.","cn":"框架：模型与研究框架勾画哪些关系重要。"},{"senses":"S5","en":"THE PHASE: conceptual design fixes the problem before dimensions are chosen.","cn":"阶段：概念设计在选尺寸之前固定问题。"},{"senses":"S8","en":"THE LEARNING: understanding principles is knowing why, not only how.","cn":"学习：理解原理是知为何，而不只是知如何。"}]},"affixes":{"intro":{"en":"Conceptual is concept + -ual. Concept is Latin conceptus, from concipere, com- plus capere 'take'. The family includes conceptually, conceptualize, conceptualization, conception, and conceptional; the same capere root gives capture and captive.","cn":"conceptual 是 concept 加 -ual。concept 是拉丁 conceptus，出自 concipere（com- 加 capere“拿”）。词族含 conceptually、conceptualize、conceptualization、conception、conceptional；同一 capere 词根给出 capture 与 captive。"},"latinIntro":{"en":"Latin capere 'take' gives concipere 'take in, conceive' and its participle conceptus. conceptus plus -ualis makes conceptualis, the source of conceptual. English also builds conception on conceptio and conceptualize on the adjective.","cn":"拉丁 capere“拿”给出 concipere“摄入、构想”及其分词 conceptus。conceptus 加 -ualis 成 conceptualis，即 conceptual 的来源。英语还在 conceptio 上造 conception，在形容词上造 conceptualize。"},"items":[{"word":"concept","structure":"conceptus (noun)","meaning":"a general idea","meaningCN":"概念（名词）","example":"the concept of justice","exampleCN":"正义的概念"},{"word":"conceptual","structure":"concept + -ual (adjective)","meaning":"relating to concepts","meaningCN":"概念的（-ual 形容词）","example":"conceptual clarity","exampleCN":"概念清晰"},{"word":"conceptually","structure":"conceptual + -ly (adverb)","meaning":"at the level of concepts","meaningCN":"概念上（-ly 副词）","example":"conceptually distinct","exampleCN":"概念上不同"},{"word":"conceptualize","structure":"conceptual + -ize (verb)","meaning":"to form a concept of","meaningCN":"概念化（-ize 动词）","example":"conceptualize the problem","exampleCN":"把问题概念化"},{"word":"conceptualization","structure":"conceptualize + -ation (noun)","meaning":"the act of forming a concept","meaningCN":"概念化过程（-ation 名词）","example":"a new conceptualization","exampleCN":"新的概念化"},{"word":"conception","structure":"concipere + -ion (noun)","meaning":"the act of conceiving; an idea; biological conception","meaningCN":"构想；概念；受孕（-ion 名词）","example":"the conception of the plan","exampleCN":"计划的构想"},{"word":"conceptional","structure":"conception + -al (adjective)","meaning":"relating to conception","meaningCN":"构想的；受孕的（-al 形容词）","example":"conceptional age","exampleCN":"受孕龄"},{"word":"conceive","structure":"concipere (verb)","meaning":"to form an idea; to become pregnant","meaningCN":"构想；受孕（同根动词）","example":"conceive a plan","exampleCN":"构想一个计划"},{"word":"capture","structure":"capere + -ture (same root)","meaning":"to take or seize","meaningCN":"捕获（同根）","example":"capture the moment","exampleCN":"捕捉瞬间"}],"latinEntries":[{"word":"capere","structure":"Latin verb","meaning":"to take, seize","meaningCN":"拿；抓"},{"word":"concipere","structure":"com- + capere","meaning":"to take in, conceive","meaningCN":"摄入；构想"},{"word":"conceptus","structure":"past participle of concipere","meaning":"conceived, a conception","meaningCN":"被构想的；构想"},{"word":"conceptio","structure":"concipere + -io","meaning":"a conceiving, conception","meaningCN":"构想；受孕"}]}},{"word":"conception","ipa_uk":"/kənˈsepʃn/","ipa_us":"/kənˈsepʃn/","definition_zh":"受孕；构想；构思；概念；观念；理解方式；（艺术）构思；开端","definition_en":"the act of forming an idea or plan; the way someone understands something; the beginning of something; biological conception","core_image":"一粒种子落进土里，同时另一颗念头在心里落定，两者都叫“开始成形”","scene":"他对「公平」的理解与同事完全不同。His conception of fairness is nothing like his colleague's, so the same proposal reads as two different things.","sceneCN":"这里 conception 是「（对某事的）理解方式、观念」（第 3 个义项：某人理解某事物的方式）；句意：他对公平的理解与同事完全不同，所以同一份方案被两人读成两件事。图中可辨识物件：两副不同的眼镜、同一份方案、种子与花盆、天平、对话气泡。","pos":[{"tag":"n.","zh":"受孕；构想；概念；观念；理解方式"}],"collocations":[{"phrase":"the conception of a plan","zh":"计划的构想"},{"phrase":"a conception of justice","zh":"正义观"},{"phrase":"from conception to birth","zh":"从受孕到出生"},{"phrase":"the Immaculate Conception","zh":"无原罪成胎"},{"phrase":"a child's conception of time","zh":"儿童的时间概念"},{"phrase":"the conception of the project","zh":"项目的开端"}],"forms":[{"label":"复数","form":"conceptions"},{"label":"动词","form":"conceive"},{"label":"形容词","form":"conceptional"},{"label":"形容词","form":"conceptual"}],"derivatives":[{"word":"conceive","pos":"v.","zh":"构想；受孕"},{"word":"concept","pos":"n.","zh":"概念"},{"word":"conceptional","pos":"adj.","zh":"构想的；受孕的"},{"word":"conceptual","pos":"adj.","zh":"概念的"},{"word":"misconception","pos":"n.","zh":"误解"}],"senses":[{"no":"01","title":"Biological conception","titleCN":"受孕","definition":"the moment when an egg is fertilised and a pregnancy begins","definitionCN":"卵子受精、妊娠开始的时刻","example":"The drug can prevent conception.","exampleCN":"该药可阻止受孕。","why":"Medicine uses the word for a physical beginning. The Latin image of 'taking in' fits: the egg takes in the sperm, and a new process starts. This sense is concrete and dated, unlike the mental ones.","whyCN":"医学用该词指物理开端。拉丁“摄入”意象正合：卵摄入精子，新过程开始。此义具体、可定日期，不同于心智诸义。"},{"no":"02","title":"Forming a plan","titleCN":"构想；构思","definition":"the act of forming an idea or plan in the mind","definitionCN":"在心中形成想法或计划的行为","example":"The conception of the reform took years.","exampleCN":"这项改革的构想用了数年。","why":"Here the word names the act, not the idea produced. A conception is an event in someone's mind; a concept is the content that can be shared afterwards.","whyCN":"此处该词命名动作，而非产出的观念。conception 是某人心中发生的事件；concept 是此后可共享的内容。"},{"no":"03","title":"A way of understanding","titleCN":"概念；观念；理解方式","definition":"the particular way a person or group understands something","definitionCN":"个人或群体理解某事物的特定方式","example":"Different cultures have different conceptions of time.","exampleCN":"不同文化有不同的时间观。","why":"This is the dominant modern sense: conception is perspectival. Two people can share the word 'justice' and still have incompatible conceptions of it, which is why the noun is often paired with 'of'.","whyCN":"这是现代主导义：conception 是视角性的。两人可共享“正义”一词，却对其有不相容的观念，故该名词常与 of 连用。"},{"no":"04","title":"A conception of liberty","titleCN":"（政治）自由观","definition":"a systematic view of what a value means and requires","definitionCN":"关于某价值意味着什么、要求什么的系统看法","example":"Berlin contrasted two conceptions of liberty.","exampleCN":"伯林对比了两种自由观。","why":"Political theory uses the noun for rival interpretations of a shared value. The debate is not whether liberty is good but what counts as liberty, and each conception draws a different boundary.","whyCN":"政治理论用该名词指对共享价值的不同解释。争论不是自由好不好，而是什么算自由；每种观念画出不同边界。"},{"no":"05","title":"The Immaculate Conception","titleCN":"无原罪成胎","definition":"the doctrine that Mary was conceived without original sin","definitionCN":"玛利亚无原罪而成胎的教义","example":"The Immaculate Conception is a Marian doctrine.","exampleCN":"无原罪成胎是关于玛利亚的教义。","why":"Theology fixes a capitalised phrase. Note the common confusion with the virgin birth: the Immaculate Conception concerns Mary's own conception, not the conception of Jesus.","whyCN":"神学固定这一大写短语。注意常与童贞受孕混淆：无原罪成胎讲的是玛利亚自身的受孕，而非耶稣的受孕。"},{"no":"06","title":"Concept formation","titleCN":"（心理学）概念形成","definition":"the mental process by which a child or learner forms categories","definitionCN":"儿童或学习者形成范畴的心智过程","example":"Piaget studied the child's conception of number.","exampleCN":"皮亚杰研究儿童的数字概念形成。","why":"Psychology uses the noun for a developmental achievement. The child moves from particulars to a category, and the timing of that move is what experiments try to measure.","whyCN":"心理学用该名词指发展成就。儿童从个别走向范畴，实验试图测量这一转变的时点。"},{"no":"07","title":"Artistic conception","titleCN":"（艺术）构思","definition":"the original idea and design of a work before or during its making","definitionCN":"作品在制作前或制作中的原初想法与设计","example":"The painting's conception is bolder than its execution.","exampleCN":"这幅画的构思比执行更大胆。","why":"Art criticism separates conception from execution: what was imagined versus what was made. A work can have a strong conception and a weak finish, or the reverse.","whyCN":"艺术批评区分构思与执行：想象之物与制成之物。作品可构思强而完成弱，或反之。"},{"no":"08","title":"The beginning of something","titleCN":"开端；肇始","definition":"the point at which an enterprise or process is first conceived","definitionCN":"事业或过程最初被构想的时点","example":"The conception of the project dates to 2019.","exampleCN":"该项目肇始于二〇一九年。","why":"This sense extends 'conception' from a mind to a project's origin. The plan is treated as an entity with a birth, and the word gives it a biography.","whyCN":"此义把 conception 从心智扩展到项目的起源。计划被当作有出生的实体，该词给它一部传记。"},{"no":"09","title":"A world conception","titleCN":"观念体系；世界观","definition":"an organized set of beliefs about reality and value","definitionCN":"关于实在与价值的组织化信念集合","example":"Marx's conception of history shaped the century.","exampleCN":"马克思的历史观塑造了那个世纪。","why":"Philosophy uses the noun for a comprehensive outlook. A world conception is more than one idea; it is a system in which the ideas support one another.","whyCN":"哲学用该名词指综合视野。世界观不止一个观念；它是一个观念相互支撑的系统。"}],"etymology":{"intro":{"en":"Conception is from Latin conceptio, the action noun of concipere 'to take in, receive, conceive', com- 'together' plus capere 'take'. The base is the same as concept and conceptual, but the suffix -ion names the act or process, while concept names the thing conceived. English uses conception for both biological fertilisation and mental formation, because Latin conceptio covered both: a taking in of seed or of an idea.","cn":"conception 出自拉丁 conceptio，即 concipere“摄入、接受、构想”的动作名词，由 com-“一起”加 capere“拿”构成。词基与 concept、conceptual 相同，但 -ion 后缀命名动作或过程，concept 则命名被构想之物。英语用 conception 兼指生物学受精与心智形成，因为拉丁 conceptio 两者都覆盖：摄入种子或摄入观念。"},"items":[{"era":"LATIN","en":"capere 'to take' and concipere 'to take in' are the base; the same root gives concept and capture.","cn":"capere“拿”与 concipere“摄入”是词基；同根给出 concept 与 capture。"},{"era":"LATIN","en":"conceptio is the action noun: a taking in, a conceiving, whether of seed or of an idea.","cn":"conceptio 是动作名词：摄入、构想，无论种子还是观念。"},{"era":"LATIN","en":"The word covered both biological and mental conception from the start, a double life English inherits.","cn":"该词从一开始就兼指生物受孕与心智构想，英语继承了这双重身份。"},{"era":"14C","en":"English conception enters in the 14C in theology and medicine, then spreads to philosophy.","cn":"英语 conception 于十四世纪进入神学与医学，后扩展到哲学。"},{"era":"17C","en":"The sense 'a way of understanding' becomes central in philosophical writing about ideas.","cn":"十七世纪“理解方式”义在论观念的哲学写作中成为核心。"},{"era":"MODERN","en":"Psychology, art criticism, and political theory each keep a specialised sense of the noun.","cn":"现代心理学、艺术批评与政治理论各保留该名词一个专门义。"}]},"similar":{"note":{"en":"The first group is the conceive family, where conception and concept divide act from product; the second is words for ideas, which differ in whether they name the act, the content, or a mistaken content.","cn":"第一组是 conceive 词族，conception 与 concept 在此分工为动作与产品；第二组是“观念”类词，差别在于指动作、内容还是错误内容。"},"groups":[{"heading":"WORD FAMILY","entries":[{"word":"conceive","ipa":"/kənˈsiːv/","tag":"verb","definition":"to form an idea; to become pregnant.","definitionCN":"构想；受孕。"},{"word":"concept","ipa":"/ˈkɒnsept/","tag":"noun","definition":"the idea that results from conceiving; a general category.","definitionCN":"构想产生的观念；一般范畴。"},{"word":"misconception","ipa":"/ˌmɪskənˈsepʃn/","tag":"noun","definition":"a wrong or mistaken conception.","definitionCN":"误解；错误观念。"}]},{"heading":"NEAR MEANING","entries":[{"word":"idea","ipa":"/aɪˈdiːə/","tag":"noun","definition":"a thought or notion, often less systematic than a conception.","definitionCN":"想法或念头，常不如 conception 系统。"},{"word":"notion","ipa":"/ˈnəʊʃn/","tag":"noun","definition":"a vague or general idea, often informal or slightly dismissive.","definitionCN":"模糊或一般的想法，常口语或略含轻蔑。"},{"word":"interpretation","ipa":"/ˌɪntəprɪˈteɪʃn/","tag":"noun","definition":"a particular reading or explanation of something. It stresses reading a text or event.","definitionCN":"对某物的特定读法或解释。强调解读文本或事件。"}]}]},"mnemonics":{"normalIntro":{"en":"Real links: concipere 'take in', conceptio as action noun, and the double life of biological and mental conception.","cn":"真实联系：concipere“摄入”、conceptio 动作名词，以及生物与心智受孕的双重身份。"},"normal":[{"en":"Concipere is 'take in'. Conception is the taking-in; concept is what has been taken in.","cn":"concipere 是“摄入”。conception 是摄入动作；concept 是被摄入之物。"},{"en":"The same word covers seed and idea because Latin conceptio did: both are beginnings that take hold.","cn":"同一个词覆盖种子与观念，因为拉丁 conceptio 如此：两者都是落定的开端。"},{"en":"Conception of X is how you understand X; a concept of X is the content you can share. Perspective versus package.","cn":"conception of X 是你如何理解 X；concept of X 是可共享的内容。视角对包裹。"},{"en":"The Immaculate Conception is about Mary's own conception, not Jesus's virgin birth; the two doctrines are often confused.","cn":"无原罪成胎讲玛利亚自身的受孕，不是耶稣的童贞降生；两种教义常被混淆。"},{"en":"'The conception of the project' gives a plan a birth date; the metaphor turns an idea into a biography.","cn":"the conception of the project 给计划一个出生日；隐喻把观念变成传记。"}],"abstract":[{"en":"Conception is the act that makes a concept possible; without the act, there is no content to share.","cn":"conception 是使概念成为可能的动作；没有动作，就没有可共享的内容。"},{"en":"Rival conceptions of one value cannot be settled by definition alone, because each conception is a whole way of seeing.","cn":"对同一价值的不同观念不能只靠定义解决，因为每种观念都是一整套看的方式。"},{"en":"Every beginning is a conception in retrospect: the origin is assigned after the fact, not given with it.","cn":"每个开端都是回溯中的构想：起源是事后指派的，而非与生俱来的。"}]},"examples":[{"en":"The conception of the new library began with a public meeting.","cn":"新图书馆的构想始于一次公开会议。"},{"en":"Children's conceptions of distance differ from adults'.","cn":"儿童对距离的概念与成人不同。"},{"en":"The study covers the period from conception to birth.","cn":"该研究涵盖从受孕到出生这一时期。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“康塞普申”——心里“接住”一个念头，或身体接住一粒种子 → conception 构想/受孕","word":"conception"},"root":"拉丁 conceptio（concipere“摄入、构想”的动作名词 = com-“一起”+ capere“拿”）；与 concept、conceptual 同根。","sensesIntro":{"en":"Nine senses of conception: fertilisation, plan-forming, a way of understanding, a political view of a value, a Marian doctrine, concept formation, artistic design, a project's origin, and a world view. The thread is a beginning that takes hold, in body or mind.","cn":"conception 的九个义项：受孕、构想计划、理解方式、价值之政治观、玛利亚教义、概念形成、艺术构思、项目肇始、世界观。共同线索是身体或心智中落定的开端。"},"semanticMap":{"core":{"en":"CORE IMAGE: a seed falling into soil and an idea settling in a mind, both beginning to take form.","cn":"核心意象：一粒种子落入土中，一个念头落入心中，两者都开始成形。"},"chain":["SOMETHING IS TAKEN IN","IT TAKES HOLD","A PROCESS BEGINS","A CONTENT FORMS","A WAY OF SEEING SETTLES","AN ORIGIN IS NAMED"],"branches":[{"senses":"01 · 06","en":"THE BODY AND THE CHILD: fertilisation and concept formation are beginnings that develop.","cn":"身体与儿童：受精与概念形成都是会发展的开端。"},{"senses":"02 · 07 · 08","en":"THE ACT AND THE WORK: planning, artistic design, and a project's origin are conceptions in time.","cn":"动作与作品：计划、艺术构思与项目肇始都是时间中的构想。"},{"senses":"04 · 09","en":"THE OUTLOOK: political conceptions and world views are organized perspectives.","cn":"视野：政治观念与世界观都是组织化的视角。"},{"senses":"05","en":"THE DOCTRINE: the Immaculate Conception fixes a theological sense and a common confusion.","cn":"教义：无原罪成胎固定一个神学义与一种常见混淆。"},{"senses":"03","en":"THE CONTRAST: conception is perspectival where concept is shareable content.","cn":"对照：conception 是视角性的，concept 是可共享内容。"}]},"affixes":{"intro":{"en":"Conception is conceive + -ion, from Latin conceptio. Conceive is concipere, com- plus capere 'take'. The family includes concept, conceptual, conceptional, and misconception; the same capere root gives capture and captive.","cn":"conception 是 conceive 加 -ion，出自拉丁 conceptio。conceive 是 concipere（com- 加 capere“拿”）。词族含 concept、conceptual、conceptional、misconception；同一 capere 词根给出 capture 与 captive。"},"latinIntro":{"en":"Latin concipere 'take in, conceive' gives conceptio 'a conceiving'. English keeps -ion for the act and uses concept for the product. The -ual adjective conceptual belongs to concept, while conceptional belongs to conception, a useful division.","cn":"拉丁 concipere“摄入、构想”给出 conceptio“构想”。英语保留 -ion 指动作，用 concept 指产品。-ual 形容词 conceptual 属于 concept，而 conceptional 属于 conception，这是有用的分工。"},"items":[{"word":"conceives","structure":"conceive + -s (3sg)","meaning":"forms an idea; becomes pregnant","meaningCN":"构想（三单）；受孕","example":"she conceives a plan","exampleCN":"她构想一个计划"},{"word":"conceived","structure":"conceive + -ed (past/participle)","meaning":"formed in the mind; fertilised","meaningCN":"构想出的；受孕的","example":"a well-conceived plan","exampleCN":"构思良好的计划"},{"word":"conceiving","structure":"conceive + -ing (participle)","meaning":"in the act of forming","meaningCN":"构想中的","example":"conceiving of a solution","exampleCN":"构想一个方案"},{"word":"conception","structure":"conceive + -ion (noun)","meaning":"the act of conceiving; a way of understanding","meaningCN":"构想；受孕；观念（-ion 名词）","example":"a conception of justice","exampleCN":"正义观"},{"word":"conceptions","structure":"conception + -s (plural)","meaning":"several ways of understanding","meaningCN":"多种观念（复数）","example":"rival conceptions of freedom","exampleCN":"相互竞争的自由观"},{"word":"conceptional","structure":"conception + -al (adjective)","meaning":"relating to conception","meaningCN":"构想的；受孕的（-al 形容词）","example":"conceptional age","exampleCN":"受孕龄"},{"word":"concept","structure":"concipere + -t (noun)","meaning":"the idea conceived","meaningCN":"概念（同根名词）","example":"the concept of number","exampleCN":"数的概念"},{"word":"misconception","structure":"mis- + conception (prefix)","meaning":"a wrong conception","meaningCN":"误解；错误观念（mis- 前缀）","example":"a common misconception","exampleCN":"常见误解"},{"word":"capture","structure":"capere + -ture (same root)","meaning":"to seize or take","meaningCN":"捕获（同根）","example":"capture the flag","exampleCN":"夺旗"}],"latinEntries":[{"word":"capere","structure":"Latin verb","meaning":"to take, seize","meaningCN":"拿；抓"},{"word":"concipere","structure":"com- + capere","meaning":"to take in, conceive","meaningCN":"摄入；构想"},{"word":"conceptio","structure":"concipere + -io","meaning":"a conceiving","meaningCN":"构想；受孕"},{"word":"conceptus","structure":"past participle of concipere","meaning":"conceived; a conception","meaningCN":"被构想的；构想"}]}},{"word":"conceptualize","ipa_uk":"/kənˈseptʃuəlaɪz/","ipa_us":"/kənˈseptʃuəlaɪz/","definition_zh":"形成概念；概念化；把…抽象为观念；构思；用概念解释；概念化设计","definition_en":"to form a concept or idea of something; to interpret an experience in terms of concepts; to plan something in the mind","core_image":"一团模糊的雾被几根线框住，慢慢显出轮廓，可以被指着说“这是X”","scene":"设计师先把用户的需求从「想要更快」抽象成「减少等待的步骤」。Designers first conceptualize the user's need, turning 'I want it faster' into 'fewer steps to wait through', and only then draw the screen.","sceneCN":"这里 conceptualize 是「概念化、把某事物抽象成概念」（第 2 个义项：用概念来理解和表述经验）；句意：设计师先把用户需求概念化，把「想要更快」变成「减少等待的步骤」，然后才画界面。图中可辨识物件：模糊雾团、线框、便利贴、需求清单、界面草图。","pos":[{"tag":"v.","zh":"形成概念；概念化；构思；用概念解释"}],"collocations":[{"phrase":"conceptualize a problem","zh":"把问题概念化"},{"phrase":"conceptualize the user","zh":"概念化用户"},{"phrase":"conceptualize an experience","zh":"把经验概念化"},{"phrase":"difficult to conceptualize","zh":"难以概念化"},{"phrase":"conceptualize the design","zh":"构思设计"},{"phrase":"conceptualize abstractly","zh":"抽象地概念化"}],"forms":[{"label":"第三人称单数","form":"conceptualizes / conceptualises"},{"label":"现在分词","form":"conceptualizing"},{"label":"过去式/过去分词","form":"conceptualized"},{"label":"名词","form":"conceptualization"}],"derivatives":[{"word":"conceptual","pos":"adj.","zh":"概念的"},{"word":"conceptualization","pos":"n.","zh":"概念化；概念化过程"},{"word":"concept","pos":"n.","zh":"概念"},{"word":"conception","pos":"n.","zh":"构想；概念"}],"senses":[{"no":"01","title":"Form a concept","titleCN":"形成概念","definition":"to build a general idea from particular cases","definitionCN":"从具体案例建立一般观念","example":"Children conceptualize animals before they name them.","exampleCN":"儿童在命名之前就先形成动物概念。","why":"This is the core sense: particulars are compressed into a category. The verb describes a cognitive achievement, and it can be gradual, partial, or failed.","whyCN":"这是核心义：具体被压缩成范畴。该动词描述认知成就，可以渐进、部分或失败。"},{"no":"02","title":"Interpret through concepts","titleCN":"概念化；用概念理解","definition":"to understand an experience by placing it under concepts","definitionCN":"把经验放到概念之下以理解","example":"The study conceptualizes poverty as a lack of capability.","exampleCN":"该研究把贫困概念化为能力不足。","why":"Academic usage makes the verb programmatic: a phenomenon is framed in a particular vocabulary. The framing is an argument, because another vocabulary would make other facts visible.","whyCN":"学术用法使该动词纲领化：现象被特定词汇框定。框定即论证，因为另一套词汇会让另一些事实显现。"},{"no":"03","title":"Plan in the mind","titleCN":"构思","definition":"to work out the main idea of something before making it","definitionCN":"在制作前想清某物的主要想法","example":"They conceptualized the app before writing code.","exampleCN":"他们在写代码前先构思了这款应用。","why":"Design and engineering use the verb for the front end of a project. Nothing exists yet, but the relations that will govern the artifact are already being fixed.","whyCN":"设计与工程用该动词指项目前端。尚无实物，但将支配成品的关系已被固定。"},{"no":"04","title":"Conceptual design","titleCN":"概念化设计","definition":"to define a design at the level of purpose and structure","definitionCN":"在目的与结构层面界定设计","example":"The team conceptualized the building as a stack of courts.","exampleCN":"团队把这座建筑概念化为层层叠起的庭院。","why":"Architecture uses the verb for the governing metaphor of a project. A strong conceptualization gives every later decision a reason; a weak one leaves decisions arbitrary.","whyCN":"建筑用该动词指项目的统摄隐喻。强的概念化给此后每个决定以理由；弱的则使决定任意。"},{"no":"05","title":"Explain by concepts","titleCN":"用概念解释","definition":"to make something intelligible by assigning it to known categories","definitionCN":"通过把某物归入已知范畴而使其可理解","example":"We conceptualize grief as a process, not an event.","exampleCN":"我们把悲伤概念化为过程，而非事件。","why":"This is the explanatory use: categorization does work. Calling grief a process changes what one expects, measures, and offers, so the concept is practical as well as descriptive.","whyCN":"这是解释性用法：归类在做工。把悲伤称为过程，改变人们期待、测量与提供之物，故概念既描述又实践。"},{"no":"06","title":"Conceptualize others","titleCN":"（心理学）概念化他人","definition":"to form a mental model of another person's mind or role","definitionCN":"对他人心智或角色形成心理模型","example":"The child begins to conceptualize others as having beliefs.","exampleCN":"儿童开始把他人概念化为拥有信念的存在。","why":"Developmental psychology uses the verb for theory of mind: another person becomes an object with hidden states. The word marks a step from behaviour to inference.","whyCN":"发展心理学用该动词指心理理论：他人成为有隐藏状态的对象。该词标记从行为到推论的步骤。"},{"no":"07","title":"Classify as a concept","titleCN":"把…归为概念","definition":"to treat something as an instance of a category","definitionCN":"把某物当作某范畴的实例","example":"The report conceptualizes the protests as a single movement.","exampleCN":"报告把抗议概念化为单一运动。","why":"This sense is close to classification but adds a claim: the category is treated as real enough to organize events. The act can be contested, since the grouping may be imposed rather than found.","whyCN":"此义近于分类，但多一个主张：该范畴被当作足以组织事件的实在。此动作可被质疑，因为分组可能是强加的，而非发现的。"},{"no":"08","title":"Build a conceptual model","titleCN":"建立概念模型","definition":"to construct a simplified model of entities and relations","definitionCN":"建构实体与关系的简化模型","example":"The researchers conceptualized the system as a network.","exampleCN":"研究者把该系统概念化为网络。","why":"Modelling uses the verb for choosing the ontology of a study. Before measuring, one decides what counts as an entity and what as a relation; that decision is the conceptualization.","whyCN":"建模用该动词指选择研究的本体。测量之前先决定什么算实体、什么算关系；该决定就是概念化。"},{"no":"09","title":"Conceptual art practice","titleCN":"（艺术）概念化","definition":"to make the idea itself the work, or to treat materials as carriers of ideas","definitionCN":"使观念本身成为作品，或把材料当作观念载体","example":"The artist conceptualized the gallery as a waiting room.","exampleCN":"艺术家把画廊概念化为候诊室。","why":"Contemporary art uses the verb for the move that turns a situation into an idea. The object may remain, but its role is to point at the concept rather than to be the concept.","whyCN":"当代艺术用该动词指把情境转为观念的动作。实物可以仍在，但其角色是指向观念，而非成为观念。"}],"etymology":{"intro":{"en":"Conceptualize is conceptual plus -ize, an English formation of the 19C. Conceptual is concept plus -ual, from Latin conceptus, from concipere 'take in, conceive' (com- plus capere 'take'). The -ize suffix goes back through Latin -izare to Greek -izein, used to form verbs meaning 'make or treat as'. So conceptualize is literally 'to make conceptual'. British spelling conceptualise follows the same suffix.","cn":"conceptualize 是 conceptual 加 -ize，是十九世纪的英语构造。conceptual 是 concept 加 -ual，出自拉丁 conceptus，源于 concipere“摄入、构想”（com- 加 capere“拿”）。-ize 后缀经拉丁 -izare 上溯希腊 -izein，用于构成“使…、把…当作”的动词。故 conceptualize 字面即“使概念化”。英式拼写 conceptualise 用同一后缀。"},"items":[{"era":"LATIN","en":"conceptus, from concipere 'take in', is the noun base; conceptual adds -ualis 'relating to'.","cn":"conceptus 出自 concipere“摄入”，是名词词基；conceptual 加 -ualis“与…有关”。"},{"era":"GREEK","en":"The suffix -izein forms verbs of making or treating as; Latin -izare and French -iser carry it onward.","cn":"后缀 -izein 构成“使…、把…当作”的动词；拉丁 -izare 与法语 -iser 将其传下。"},{"era":"ENGLISH","en":"English -ize is productive from the 16C; conceptualize is a learned 19C coinage on the adjective.","cn":"英语 -ize 自十六世纪起能产；conceptualize 是十九世纪在形容词上的学术新造词。"},{"era":"19C","en":"Philosophy and psychology adopt conceptualize for the act of forming or applying concepts.","cn":"十九世纪哲学与心理学采用 conceptualize 指形成或应用概念的动作。"},{"era":"20C","en":"Design, education, and cognitive science extend it to planning, teaching, and model building.","cn":"二十世纪设计、教育与认知科学把它扩展到规划、教学与建模。"},{"era":"MODERN","en":"British conceptualise and American conceptualize are the same verb with different spelling conventions.","cn":"英式 conceptualise 与美式 conceptualize 是同一动词的不同拼写惯例。"}]},"similar":{"note":{"en":"The first group is the conceptual family and its spelling variants; the second is verbs of thinking, which differ in whether they form an idea, plan it, or merely understand it.","cn":"第一组是 conceptual 词族及拼写变体；第二组是思维动词，差别在于形成观念、规划还是仅仅理解。"},"groups":[{"heading":"WORD FAMILY","entries":[{"word":"conceptual","ipa":"/kənˈseptʃuəl/","tag":"adjective","definition":"relating to concepts.","definitionCN":"与概念有关的。"},{"word":"conceptualization","ipa":"/kənˌseptʃuəlaɪˈzeɪʃn/","tag":"noun","definition":"the act or result of forming a concept.","definitionCN":"形成概念的动作或结果。"},{"word":"conceptualise","ipa":"/kənˈseptʃuəlaɪz/","tag":"verb","definition":"British spelling of conceptualize.","definitionCN":"conceptualize 的英式拼写。"}]},{"heading":"NEAR MEANING","entries":[{"word":"formulate","ipa":"/ˈfɔːmjuleɪt/","tag":"verb","definition":"to express an idea in a precise, often formal, form. It stresses wording more than category-making.","definitionCN":"以精确、常正式的形式表达想法。更强调措辞，而非造范畴。"},{"word":"frame","ipa":"/freɪm/","tag":"verb","definition":"to set up a problem or issue within a particular perspective. It is close to sense 02 but more rhetorical.","definitionCN":"在特定视角内设置问题。近第 2 义，但更修辞。"},{"word":"imagine","ipa":"/ɪˈmædʒɪn/","tag":"verb","definition":"to form a mental picture. It is more sensory and less categorical than conceptualize.","definitionCN":"形成心理图像。比 conceptualize 更感官、更少范畴性。"}]}]},"mnemonics":{"normalIntro":{"en":"Real links: conceptual plus the -ize suffix 'make/treat as', the capere root, and the British/American spelling split.","cn":"真实联系：conceptual 加表“使…/当作”的 -ize 后缀、capere 词根，以及英美拼写分歧。"},"normal":[{"en":"Conceptual + -ize = 'make conceptual'. The suffix turns an adjective into a verb of making.","cn":"conceptual + -ize =“使概念化”。该后缀把形容词变成“使…”动词。"},{"en":"-ize goes back to Greek -izein through Latin -izare; it is the same suffix as in modernize and organize.","cn":"-ize 经拉丁 -izare 上溯希腊 -izein；与 modernize、organize 是同一后缀。"},{"en":"Concept is from capere 'take'; conceptualize is the mind taking a case and holding it under a category.","cn":"concept 出自 capere“拿”；conceptualize 是心智拿起一个案例，把它放到范畴之下。"},{"en":"British conceptualise, American conceptualize: same verb, spelling convention only.","cn":"英式 conceptualise、美式 conceptualize：同一动词，只是拼写惯例。"},{"en":"To conceptualize grief as a process changes what you expect and offer; the concept does work.","cn":"把悲伤概念化为过程，会改变你期待与提供之物；概念在做工。"}],"abstract":[{"en":"Conceptualizing is choosing a vocabulary, and every vocabulary makes some facts visible while hiding others.","cn":"概念化就是选择词汇，而每套词汇让一些事实显现，同时遮住另一些。"},{"en":"To conceptualize is to compress the particular into the general, and something is always lost in the compression.","cn":"概念化是把个别压缩为一般，而压缩中总有东西丢失。"},{"en":"A model's ontology is its politics: what counts as an entity decides who or what can appear in the analysis.","cn":"模型的本体就是其政治：什么算实体，决定谁或什么能出现在分析中。"}]},"examples":[{"en":"It is hard to conceptualize a universe without time.","cn":"很难概念化一个没有时间的宇宙。"},{"en":"The team conceptualized the problem as a flow of resources.","cn":"团队把问题概念化为资源流动。"},{"en":"Children conceptualize the world through stories and play.","cn":"儿童通过故事与游戏概念化世界。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“康塞普秋拉艾兹”——把模糊一团“概念化”成可命名的东西 → conceptualize 概念化","word":"conceptualize"},"root":"conceptual（concept + -ual，源自拉丁 concipere“摄入、构想”）+ -ize（经拉丁 -izare 上溯希腊 -izein“使…、把…当作”）。","sensesIntro":{"en":"Nine senses of conceptualize: form a concept, interpret through concepts, plan in the mind, define a design idea, explain by categories, model another mind, classify as a concept, build a model, and make the idea the artwork.","cn":"conceptualize 的九个义项：形成概念、用概念理解、心中构思、界定设计理念、用范畴解释、建模他人心智、归为概念、建立模型、使观念成为艺术。"},"semanticMap":{"core":{"en":"CORE IMAGE: a blur of fog caught in a wireframe until it can be pointed at and named.","cn":"核心意象：一团模糊的雾被线框框住，直到能被指着命名。"},"chain":["SOMETHING VAGUE","DRAW A BOUNDARY","NAME A CATEGORY","PLACE THE CASE UNDER IT","USE IT TO EXPLAIN","MAKE IT THE WORK"],"branches":[{"senses":"S1 · S7","en":"THE CATEGORY: forming a concept and treating a case as an instance are the basic moves.","cn":"范畴：形成概念与把案例当作实例是基本动作。"},{"senses":"S2 · S5","en":"THE EXPLANATION: a vocabulary frames a phenomenon and changes what counts as a fact.","cn":"解释：词汇框定现象，改变什么算事实。"},{"senses":"S3 · S4","en":"THE PLAN: design and architecture fix the governing idea before making anything.","cn":"计划：设计与建筑在制作前固定统摄理念。"},{"senses":"S6","en":"THE MIND: another person becomes a model with hidden states.","cn":"心智：他人成为有隐藏状态的模型。"},{"senses":"S8 · S9","en":"THE MODEL AND THE ART: an ontology or an artwork makes the idea the object.","cn":"模型与艺术：本体或艺术品使观念成为对象。"}]},"affixes":{"intro":{"en":"Conceptualize is conceptual + -ize. Conceptual is concept + -ual, from Latin conceptus. The -ize suffix comes through Latin -izare from Greek -izein. The family includes conceptualization, conceptual, concept, and conception; the British spelling is conceptualise.","cn":"conceptualize 是 conceptual 加 -ize。conceptual 是 concept 加 -ual，出自拉丁 conceptus。-ize 后缀经拉丁 -izare 来自希腊 -izein。词族含 conceptualization、conceptual、concept、conception；英式拼写为 conceptualise。"},"latinIntro":{"en":"Latin conceptus 'a conception' plus -ualis gives conceptualis. English adds -ize to the adjective, a suffix of Greek origin meaning 'make or treat as'. The noun conceptualization adds -ation. The same base yields concept and conception.","cn":"拉丁 conceptus“构想”加 -ualis 给出 conceptualis。英语在形容词上加 -ize，这是源自希腊、意为“使…/把…当作”的后缀。名词 conceptualization 加 -ation。同一词基给出 concept 与 conception。"},"items":[{"word":"conceptualizes","structure":"conceptualize + -es (3sg)","meaning":"forms a concept","meaningCN":"概念化（三单）","example":"she conceptualizes the issue","exampleCN":"她把问题概念化"},{"word":"conceptualized","structure":"conceptualize + -ed (past/participle)","meaning":"formed into a concept","meaningCN":"被概念化的","example":"a conceptually framed study","exampleCN":"概念化框定的研究"},{"word":"conceptualizing","structure":"conceptualize + -ing (participle)","meaning":"in the act of forming concepts","meaningCN":"概念化中的","example":"conceptualizing experience","exampleCN":"概念化经验"},{"word":"conceptualization","structure":"conceptualize + -ation (noun)","meaning":"the act or result of conceptualizing","meaningCN":"概念化（-ation 名词）","example":"a new conceptualization of poverty","exampleCN":"对贫困的新概念化"},{"word":"conceptual","structure":"conceptualize + -al (back-formation)","meaning":"relating to concepts","meaningCN":"概念的（形容词）","example":"conceptual clarity","exampleCN":"概念清晰"},{"word":"concept","structure":"concipere + -t (noun)","meaning":"a general idea","meaningCN":"概念（同根名词）","example":"the concept of gravity","exampleCN":"重力的概念"},{"word":"conception","structure":"concipere + -ion (noun)","meaning":"the act of conceiving; a view","meaningCN":"构想；观念（同根名词）","example":"a conception of history","exampleCN":"历史观"},{"word":"conceptualise","structure":"conceptualize (British spelling)","meaning":"British form of the verb","meaningCN":"英式拼写","example":"conceptualise the model","exampleCN":"概念化模型"},{"word":"conceptualism","structure":"conceptual + -ism (doctrine)","meaning":"the view that universals exist only in the mind","meaningCN":"概念论（-ism 学说）","example":"medieval conceptualism","exampleCN":"中世纪概念论"}],"latinEntries":[{"word":"capere","structure":"Latin verb","meaning":"to take, seize","meaningCN":"拿；抓"},{"word":"concipere","structure":"com- + capere","meaning":"to take in, conceive","meaningCN":"摄入；构想"},{"word":"conceptus","structure":"past participle of concipere","meaning":"conceived; a conception","meaningCN":"被构想的；构想"},{"word":"conceptualis","structure":"conceptus + -ualis","meaning":"relating to a concept","meaningCN":"与概念有关的"}]}},{"word":"conclusion","ipa_uk":"/kənˈkluːʒn/","ipa_us":"/kənˈkluːʒn/","definition_zh":"结论；推论；结束；结尾；缔结；结局；最终决定；（法律）判决结论","definition_en":"a judgement reached after considering evidence; the end or final part of something; the act of formally completing an agreement","core_image":"最后一页合上，前面所有线索在此收拢成一个判断","scene":"报告写到最后，作者把三组数据收成一句话：证据支持这个假设。At the end of the report the author draws the conclusion in one line: the evidence supports the hypothesis.","sceneCN":"这里 conclusion 是「结论、推论」（第 1 个义项：在考虑证据后得出的判断）；句意：报告结尾，作者用一句话给出结论：证据支持这个假设。图中可辨识物件：合上的报告、三组图表、红色批注、钢笔、封底的绳结。","pos":[{"tag":"n.","zh":"结论；推论；结束；缔结；结局"}],"collocations":[{"phrase":"reach a conclusion","zh":"得出结论"},{"phrase":"in conclusion","zh":"最后；总之"},{"phrase":"draw a conclusion","zh":"得出推论"},{"phrase":"the conclusion of the treaty","zh":"条约的缔结"},{"phrase":"a foregone conclusion","zh":"早已注定的事"},{"phrase":"bring to a conclusion","zh":"使结束"}],"forms":[{"label":"复数","form":"conclusions"},{"label":"动词","form":"conclude"},{"label":"形容词","form":"concluding / conclusive"},{"label":"副词","form":"conclusively"}],"derivatives":[{"word":"conclude","pos":"v.","zh":"得出结论；结束；缔结"},{"word":"concluding","pos":"adj.","zh":"结尾的"},{"word":"conclusive","pos":"adj.","zh":"决定性的；确凿的"},{"word":"conclusively","pos":"adv.","zh":"决定性地"}],"senses":[{"no":"01","title":"A judgement from evidence","titleCN":"结论；推论","definition":"a judgement or opinion reached after considering evidence","definitionCN":"考虑证据后得出的判断或意见","example":"The study's conclusion was that the drug was safe.","exampleCN":"该研究的结论是该药安全。","why":"This is the dominant modern sense: the mind closes an inquiry. The conclusion is not the evidence but the move from it, and it can be strong, provisional, or contested.","whyCN":"这是现代主导义：心智结束一项探究。结论不是证据，而是从证据出发的移动，可强、可暂定、可被质疑。"},{"no":"02","title":"The end of something","titleCN":"结束；结尾","definition":"the final part or point at which something stops","definitionCN":"某物停止的最后部分或时点","example":"The conclusion of the ceremony was a speech.","exampleCN":"典礼的结尾是一场演讲。","why":"This is the spatial or temporal sense: a thing is closed at its edge. It carries no inferential claim, and 'in conclusion' uses it to mark the last section of a text.","whyCN":"这是空间或时间义：事物在其边缘被合上。它不含推论主张，in conclusion 用它标记文本最后一节。"},{"no":"03","title":"Formal completion of an agreement","titleCN":"缔结","definition":"the act of formally completing a treaty, contract, or deal","definitionCN":"正式完成条约、合同或交易的行为","example":"the conclusion of a peace treaty","exampleCN":"和平条约的缔结","why":"Diplomacy uses the noun for the moment an agreement is closed. Here 'conclude' means to bring to a binding end, and the parties are bound by the closing.","whyCN":"外交用该名词指协议达成的时刻。此处 conclude 指带到有约束力的终点，各方因这一闭合而受约束。"},{"no":"04","title":"The outcome of a story","titleCN":"（故事）结局","definition":"the final resolution or outcome of a narrative","definitionCN":"叙事的最终解决或结果","example":"The novel's conclusion surprised readers.","exampleCN":"小说的结局令读者惊讶。","why":"Literature uses the word for how a plot closes. A conclusion need not resolve every thread; it need only end the telling, and an open conclusion is a deliberate choice.","whyCN":"文学用该词指情节如何合拢。结局不必解决每条线；它只需结束讲述，开放结局是刻意选择。"},{"no":"05","title":"A final decision","titleCN":"最终决定；定论","definition":"a decision reached after deliberation, often by a body or authority","definitionCN":"经商议后作出的决定，常由机构或权威作出","example":"The committee came to the conclusion that the plan should proceed.","exampleCN":"委员会得出结论，计划应继续。","why":"Institutional usage makes the conclusion an act of authority. The body closes debate and speaks with one voice, which is why minutes record 'the conclusion' rather than 'an opinion'.","whyCN":"制度用法使结论成为权威行为。机构结束辩论，以一口说话，故会议记录写“结论”而非“意见”。"},{"no":"06","title":"The closing section of a text","titleCN":"（文章）总结；结尾","definition":"the final section of an essay or report that sums up its argument","definitionCN":"文章或报告总结论点的最后一节","example":"The conclusion restates the thesis and looks ahead.","exampleCN":"结论部分重述论点并展望。","why":"Academic writing uses the word for a genre convention. The section does not introduce new evidence; it gathers what has been shown and states what follows.","whyCN":"学术写作把该词用于文体惯例。该节不引入新证据；它收拢已展示之物，并说明由此推出什么。"},{"no":"07","title":"An experimental finding","titleCN":"实验结论","definition":"the interpretation drawn from the results of an experiment","definitionCN":"从实验结果得出的解释","example":"The experiment's conclusion supported the hypothesis.","exampleCN":"该实验的结论支持该假设。","why":"Science uses the word carefully: the conclusion is an inference from data under assumptions. Good practice states the scope, because a conclusion can hold for the sample and fail for the population.","whyCN":"科学谨慎使用该词：结论是在假设下从数据作出的推论。良好做法会说明范围，因为结论可对样本成立而对总体失效。"},{"no":"08","title":"A legal conclusion","titleCN":"（法律）判决结论","definition":"the legal result a court reaches after applying law to facts","definitionCN":"法院把法律适用于事实后得出的法律结果","example":"The court's conclusion was that the clause was void.","exampleCN":"法院的结论是该条款无效。","why":"Law separates findings of fact from conclusions of law. The conclusion applies rules to facts, and it is the part an appellate court reviews for error.","whyCN":"法律区分事实认定与法律结论。结论把规则适用于事实，是上诉法院审查是否有误的部分。"},{"no":"09","title":"The inferred proposition in logic","titleCN":"（逻辑）推论；结论","definition":"the proposition that follows from premises in an argument","definitionCN":"论证中由前提推出的命题","example":"If the premises are true, the conclusion must be true.","exampleCN":"若前提为真，结论必为真。","why":"Logic uses the word as a technical term: the conclusion is the proposition supported by premises. Validity concerns the link, not the truth of either part, which is why a valid argument can have a false conclusion.","whyCN":"逻辑把该词作技术术语：结论是被前提支持的命题。有效性关乎连接，而非任一部分的真，故有效论证可有假结论。"}],"etymology":{"intro":{"en":"Conclusion is conclude plus -sion, from Latin conclusio. Conclude comes from Latin concludere 'to shut up, enclose, end', com- 'together' plus claudere 'to close'. The literal image is closing something off, and the sense 'inference' grows from closing an argument. The same claudere gives close, clause, include, exclude, and claustrophobia. The word's path is physical closing → ending → formal completion → judgement.","cn":"conclusion 是 conclude 加 -sion，出自拉丁 conclusio。conclude 出自拉丁 concludere“关闭、围住、结束”，由 com-“一起”加 claudere“关闭”构成。字面意象是把某物合上，“推论”义由合上论证生长而来。同一 claudere 给出 close、clause、include、exclude、claustrophobia。词的路迹是物理关闭 → 结束 → 正式完成 → 判断。"},"items":[{"era":"LATIN","en":"claudere means 'to close, shut'; it gives close, clause, include, exclude, and claustrophobia.","cn":"claudere 意为“关闭、合上”，给出 close、clause、include、exclude、claustrophobia。"},{"era":"LATIN","en":"concludere is com- 'together' plus claudere: to shut up, enclose, bring to an end.","cn":"concludere 是 com-“一起”加 claudere：关闭、围住、带到终点。"},{"era":"LATIN","en":"conclusio is the action noun, 'a closing'; English conclusion keeps the -sion abstract-noun pattern.","cn":"conclusio 是动作名词“关闭”；英语 conclusion 保留 -sion 抽象名词模式。"},{"era":"14C","en":"English conclusion enters in the 14C for both ending and inference, since closing an argument yields a judgement.","cn":"英语 conclusion 于十四世纪进入，兼指结束与推论，因为合上论证即产生判断。"},{"era":"16C","en":"The diplomatic sense 'conclusion of a treaty' is established, treating an agreement as something closed.","cn":"十六世纪“条约缔结”的外交义确立，把协议当作被合上之物。"},{"era":"MODERN","en":"Logic, law, and science each fix a technical sense of the noun, while 'in conclusion' remains a text marker.","cn":"现代逻辑、法律与科学各固定该名词一个技术义，而 in conclusion 仍是文本标记。"}]},"similar":{"note":{"en":"The first group is the conclude family; the second is words for results and endings, which differ in whether they are inferred, decided, or merely last.","cn":"第一组是 conclude 词族；第二组是“结果与结尾”类词，差别在于指推论、决定还是仅仅最后。"},"groups":[{"heading":"WORD FAMILY","entries":[{"word":"conclude","ipa":"/kənˈkluːd/","tag":"verb","definition":"to reach a judgement; to end; to complete an agreement.","definitionCN":"得出结论；结束；缔结。"},{"word":"conclusive","ipa":"/kənˈkluːsɪv/","tag":"adjective","definition":"decisive, putting an end to doubt.","definitionCN":"决定性的；确凿的。"},{"word":"conclusively","ipa":"/kənˈkluːsɪvli/","tag":"adverb","definition":"in a decisive way.","definitionCN":"决定性地。"}]},{"heading":"NEAR MEANING","entries":[{"word":"inference","ipa":"/ˈɪnfərəns/","tag":"noun","definition":"the process of deriving a conclusion from evidence. It names the move, not the endpoint.","definitionCN":"从证据推出结论的过程。命名移动，而非终点。"},{"word":"finding","ipa":"/ˈfaɪndɪŋ/","tag":"noun","definition":"a result established by research or an inquiry. It is often more empirical and less final.","definitionCN":"研究或调查确立的结果。常更实证、更少终局性。"},{"word":"ending","ipa":"/ˈendɪŋ/","tag":"noun","definition":"the last part of a story or process. It is temporal and has no inferential content.","definitionCN":"故事或过程的最后部分。时间性，无推论内容。"}]}]},"mnemonics":{"normalIntro":{"en":"Real links: claudere 'close', concludere 'shut up, end', and the path from closing to inferring.","cn":"真实联系：claudere“关闭”、concludere“合上、结束”，以及从闭合到推论的路径。"},"normal":[{"en":"Concludere is 'shut up, close'. A conclusion closes an argument the way a lid closes a box.","cn":"concludere 是“合上、关闭”。结论合上论证，像盖子合上盒子。"},{"en":"The claudere family is all about closing: include, exclude, clause, claustrophobia.","cn":"claudere 词族全关于关闭：include、exclude、clause、claustrophobia。"},{"en":"'In conclusion' marks the last section; it is a text sign, not a claim that anything was proved.","cn":"in conclusion 标记最后一节；它是文本符号，不表示已证明什么。"},{"en":"A treaty's conclusion is its closing, which also binds: the deal is shut and cannot be reopened at will.","cn":"条约的 conclusion 是其合拢，也有约束力：交易被合上，不能随意重开。"},{"en":"In logic, validity is about the link from premises to conclusion, not about the truth of either.","cn":"逻辑中，有效性关乎从前提到结论的连接，而非任一方的真。"}],"abstract":[{"en":"A conclusion is a closure that claims to be earned: it ends inquiry by asserting that the path to it was sound.","cn":"结论是一种声称有资格取得的闭合：它以断言路径可靠来结束探究。"},{"en":"Every ending is also an exclusion: to conclude is to decide that further evidence will not change the judgement.","cn":"每个结束也是一次排除：得出结论就是决定后续证据不再改变判断。"},{"en":"The same word covers a treaty and a syllogism because both are acts of binding: parties or premises are tied into one result.","cn":"同一个词覆盖条约与三段论，因为两者都是约束行为：各方或前提被系成一个结果。"}]},"examples":[{"en":"The report's conclusion is that the policy failed.","cn":"报告的结论是该政策失败了。"},{"en":"In conclusion, I would like to thank the committee.","cn":"最后，我要感谢委员会。"},{"en":"The two countries announced the conclusion of a trade agreement.","cn":"两国宣布缔结一项贸易协定。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“康克鲁申”——把话“关”起来（claudere），最后盖棺定论 → conclusion 结论","word":"conclusion"},"root":"conclude（拉丁 concludere“关闭、结束”= com-“一起”+ claudere“关闭”）+ -sion（拉丁 conclusio）。","sensesIntro":{"en":"Nine senses of conclusion: a judgement from evidence, an ending, a treaty's completion, a story's outcome, a final decision, a closing section, an experimental finding, a legal result, and a logical proposition. The thread is closing, whether a text, a deal, or an inquiry.","cn":"conclusion 的九个义项：证据判断、结束、条约缔结、故事结局、最终决定、文章结尾、实验结论、法律结论、逻辑命题。共同线索是“合上”，无论合上文本、交易还是探究。"},"semanticMap":{"core":{"en":"CORE IMAGE: a report closing, its threads gathered into one judgement on the last page.","cn":"核心意象：报告合上，前面所有线索在最后一页收成一个判断。"},"chain":["GATHER THE EVIDENCE","CLOSE THE ARGUMENT","STATE THE JUDGEMENT","END THE TEXT","COMPLETE THE DEAL","BIND THE RESULT"],"branches":[{"senses":"S1 · S7 · S9","en":"THE INFERENCE: evidence, experiment, and premises all lead to a supported proposition.","cn":"推论：证据、实验与前提都通向一个被支持的命题。"},{"senses":"S2 · S6","en":"THE TEXT: an ending and a closing section mark where the telling stops.","cn":"文本：结尾与结论节标记讲述停止之处。"},{"senses":"S3 · S5","en":"THE DEAL AND THE DECISION: a treaty and a committee's judgement are closed with authority.","cn":"交易与决定：条约与委员会判断以权威合上。"},{"senses":"S4","en":"THE STORY: a plot's outcome closes the narrative without necessarily resolving every thread.","cn":"故事：情节结果合上叙事，未必解决每条线。"},{"senses":"S8","en":"THE LAW: conclusions of law apply rules to facts and are reviewed for error.","cn":"法律：法律结论把规则适用于事实，并受错误审查。"}]},"affixes":{"intro":{"en":"Conclusion is conclude + -sion, from Latin conclusio. Conclude is concludere, com- plus claudere 'close'. The family includes conclusive, conclusively, and concluding; the same claudere root gives close, clause, include, and exclude.","cn":"conclusion 是 conclude 加 -sion，出自拉丁 conclusio。conclude 是 concludere（com- 加 claudere“关闭”）。词族含 conclusive、conclusively、concluding；同一 claudere 词根给出 close、clause、include、exclude。"},"latinIntro":{"en":"Latin claudere 'close' gives concludere 'shut up, end' and conclusio 'a closing'. English keeps -sion for the noun and builds conclusive and concluding on the stem. The same root appears in clause and include, where the closing image is less visible.","cn":"拉丁 claudere“关闭”给出 concludere“合上、结束”与 conclusio“关闭”。英语保留 -sion 作名词，并在词干上造 conclusive 与 concluding。同根见于 clause 与 include，关闭意象较不明显。"},"items":[{"word":"concludes","structure":"conclude + -s (3sg)","meaning":"ends or judges","meaningCN":"得出结论（三单）","example":"the study concludes that","exampleCN":"研究结论是"},{"word":"concluded","structure":"conclude + -ed (past/participle)","meaning":"ended; judged","meaningCN":"结束了；已判定","example":"the meeting concluded at noon","exampleCN":"会议中午结束"},{"word":"concluding","structure":"conclude + -ing (participle)","meaning":"forming the end","meaningCN":"结尾的","example":"the concluding chapter","exampleCN":"最后一章"},{"word":"conclusion","structure":"conclude + -sion (noun)","meaning":"a judgement or ending","meaningCN":"结论；结束（-sion 名词）","example":"a firm conclusion","exampleCN":"坚定的结论"},{"word":"conclusions","structure":"conclusion + -s (plural)","meaning":"several judgements","meaningCN":"多个结论（复数）","example":"draw conclusions","exampleCN":"得出结论"},{"word":"conclusive","structure":"conclude + -ive (adjective)","meaning":"decisive, ending doubt","meaningCN":"决定性的（-ive 形容词）","example":"conclusive evidence","exampleCN":"决定性证据"},{"word":"conclusively","structure":"conclusive + -ly (adverb)","meaning":"decisively","meaningCN":"决定性地（-ly 副词）","example":"prove conclusively","exampleCN":"确凿证明"},{"word":"clause","structure":"claudere + -s (same root)","meaning":"a closed unit of a sentence or contract","meaningCN":"从句；条款（同根）","example":"a contract clause","exampleCN":"合同条款"},{"word":"include","structure":"in- + claudere (same root)","meaning":"to shut in, contain","meaningCN":"包括（同根）","example":"include a note","exampleCN":"附上说明"}],"latinEntries":[{"word":"claudere","structure":"Latin verb","meaning":"to close, shut","meaningCN":"关闭；合上"},{"word":"concludere","structure":"com- + claudere","meaning":"to shut up, enclose, end","meaningCN":"关闭；围住；结束"},{"word":"conclusio","structure":"concludere + -io","meaning":"a closing, conclusion","meaningCN":"关闭；结论"},{"word":"clausa","structure":"claudere + -sa","meaning":"a closed thing, clause","meaningCN":"关闭之物；条款"}]}}]);
